window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_020"]={"n":"邵宝","dyn":"明","poems":[{"t":"胥门","f":"古风","c":["臣奢无辜为君戮，臣胥敢怒不敢哭。","朝辞楚疆暮吴国，还兵入郢亦太酷。","愤愤心，还未足。","楚何怨，吴何恩。","豫让死，王裒存。","是邪非，不必论。","一片鸱夷皮，裹骨难裹魂，北风莫遣向越奔。","向越奔，无不可，只恐仇吴似仇楚。"]},{"t":"寄题东林寺壁","f":"七言古诗","c":["雁门僧避胡尘来，匡庐山中寻讲台。","谁云净土在西竺，此池自有莲花开。","莲花开时千万朵，江南君臣不疑我。","渊明故是避世人，菊花醉插头上巾。","攒眉掉臂谢公去，一杯浊酒堪全真。","当年意在谁独识，虎溪笑处泉流石。","至今古塔依西林，月落江云树千尺。"]},{"t":"小孤山","f":"七言古诗","c":["昔闻砥柱黄河中，万古坐镇狂澜东。","小孤乃是江砥柱，特起不与群山同。","群山随江挺奔马，爱此石笋凌苍穹。","孤哉孤哉本天造，一任巨浪乘长风。","节宣夙受神禹戒，滔滔不碍江朝宗。","我来信宿彭泽下，咫尺仰望天妃宫。","翠烟霏霏落杯酒，千帆阅尽澄潭空。","举杯酹江江日红，隔江缥缈留青峰。","便当载笔赋东海，三山点破云冥濛。"]},{"t":"题钱世恒吊文山遗墨卷","f":"五言古诗","c":["北风吹南冠，行行一匏瓜。","作书谢骨肉，涕泪纷交加。","此行已忘身，此书又忘家。","身家既两忘，未忘者何邪。","至哉君与臣，大哉夷与华。","片纸今又灰，浩叹天无涯。"]},{"t":"冬夜观树影","f":"五言古诗","c":["月树影在地，横斜复横斜。","谁为水墨画，老笔全无华。","又如春雷动，初惊蛰龙蛇。","因之得篆法，锥铁行平沙。","海云漾双玕，江风落孤楂。","玄冬万景閟，嘉此独咨嗟。","他宵有繁阴，莫向时人誇。"]},{"t":"为宁庵题画","f":"五言古诗","c":["修竹满舍傍，长松当道周。","青山生白云，隐隐屋上头。","出门见溪水，有桥复有舟。","天风作前驱，时引幽人游。","琴尊侑高谈，兴尽不强留。","静游羲皇梦，閒听尧民讴。","命笔书暄凉，山林有春秋。","独乐得深味，岂尝抱先忧。","莫问此何人，吾当意中求。"]},{"t":"三竺道中","f":"五言律诗","c":["人行松径静，数里不知遥。","路转还逢寺，僧迎只过桥。","岩姿收独妙，泉响息群嚣。","东去频回首，山花似我邀。"]},{"t":"秋野用杜韵二首 其一","f":"五言律诗","c":["河汉三秋隔，星辰万里违。","客怜双鸟去，僧讶一人归。","相马吾何有，知鱼尔亦非。","春风故相爱，吹绿北山薇。"]},{"t":"留别娄郎中元善","f":"五言律诗","c":["廿载论交地，溪山古信州。","晚园收硕果，周道傍寒流。","天与裁春服，人将渡野舟。","夕佳轩外月，还照越江秋。"]},{"t":"金溪怀徐嘉兴用济","f":"五言律诗","c":["晚负苍生望，寻山只欲深。","孤忠天北极，遗爱海东浔。","霜骨全欺杖，风髯半拂琴。","丹崖人似玉，吾道愧知音。"]},{"t":"胶山忠定祠次施克和韵","f":"七言律诗","c":["壮怀千古了难偿，太息群阴剥一阳。","鸣凤未闻声徵角，战龙曾见血玄黄。","薄茅藉处非无地，老树阴中合有堂。","风雨去城三十里，满山箫鼓为谁忙。"]},{"t":"寄庄定山","f":"七言律诗","c":["几年书断定山翁，极目江天送去鸿。","野史不妨朝报外，病怀长托醉吟中。","短筇向晚云随在，小榻逢秋月与同。","尚忆长安吟别地，夜深风雨烛花红。"]},{"t":"盂城即事","f":"七言律诗","c":["盂城驿前吟夕阳，高邮湖上好秋光。","红分菡萏初经雨，绿满蒹葭未受霜。","远浦有波皆浴鹭，近堤无路尚垂杨。","南来时见吴江棹，却倚船窗问故乡。"]},{"t":"经元世祖庙次王应韶韵","f":"七言律诗","c":["断碑閒倚庙门斜，往事伤心付一嗟。","春草长沙仍牧马，晚风疏树偶栖鸦。","角端虚忆传神语，劈正何从纪梦华。","谁向渎山陈酒海，飞尘如雨乱闻蛙。"]},{"t":"谒谢叠山祠","f":"七言律诗","c":["从容就义几封书，三百年来养士馀。","商老不知周粟富，晋人方恨楚材虚。","庭留旧柏生同劲，鼎荐新薇死亦臞。","有诏作人无事日，江花江草正愁予。"]},{"t":"谢方石先生挽词","f":"七言律诗","c":["我归林下公长逝，千里诗筒望不来。","海隐本非唐少室，山居真似宋徂徕。","雅歌何处声相和，野服它年手自裁。","有石大书明祭酒，古松阴里墓门开。"]},{"t":"谢邑令请乡饮","f":"七言律诗","c":["迷途岁晚尚茫茫，谓我嘉宾讵敢当。","扬觯有人惭杜举，承筐无地想周行。","一经讲受曾它日，三老周旋即此堂。","为语县侯休见讶，莱衣方作小儿狂。"]},{"t":"太伯庙","f":"七言律诗","c":["太伯新祠古让乡，老梅根畔水流长。","十年梦寐三间屋，万古纲常一瓣香。","扁榜大书元自孔，衣冠遗制合存商。","向来曾拟荆蛮曲，许作迎神第几章。"]},{"t":"雪中赏红梅奉次涯翁先生时邃翁携酒共饮怀麓堂二首 其一","f":"七言律诗","c":["浅绛英英忽满枝，春风到此复何之。","正怜与雪相逢地，却讶如人欲醉时。","南国已通千里信，西湖空负一生诗。","白头二老青灯夜，笑对江东绿酒卮。"]},{"t":"雪酒为孙司徒赋奉次涯翁先生","f":"七言律诗","c":["玄酒曾闻侑大烹，酿来寒雪品尤清。","也知承露能高致，须信藏冰为曲成。","光动夜杯如有物，暖销春瓮本无声。","相看莫谓人间味，一滴先天万古情。"]},{"t":"袁州谒韩文公祠","f":"七言律诗","c":["一上春台草陆离，忽瞻遗像起遐思。","江山恨少滕王赋，风水愁多二女祠。","石廪不知云去地，雷塘犹想雨来时。","凭君莫引飞鸿望，万里骑龙任所之。"]},{"t":"忆母","f":"七言律诗","c":["手线缝衣欲问寒，慈颜时向梦中看。","世间尽道为官好，天下无如别母难。","读罢家音添鬓白，书成国事剩心丹。","青灯自照塼河夜，回首江南路渺漫。"]},{"t":"归兴六首 其二","f":"七言律诗","c":["东归诏许省慈亲，瀛海西头问旧津。","宿麦穗馀三月饷，枯杨皮尽几家薪。","平生酒慕苏门老，它日羹怜颍谷人。","闻道王师频报捷，中原今已息风尘。"]},{"t":"归兴六首 其三","f":"七言律诗","c":["镇日冲风起九河，沽潮东上不胜波。","云蒙日影当晡密，雨送雷声入夜多。","野史一书还夏五，客灯十载几连窝。","新凉却动江南思，卧看青山听棹歌。"]},{"t":"归兴六首 其四","f":"七言律诗","c":["漕堤杨柳昔人功，六月清阴处处同。","东国共看归海水，南船方趁过淮风。","寻常民俗兵兴后，百万军储岁挽中。","我有瓣香何所致，礼官新祀宋司空。"]},{"t":"归兴六首 其五","f":"七言律诗","c":["舣棹来看治水碑，沙湾堤上蚤凉时。","汉防故迹嗟谁志，禹贡全书愧我师。","铁柱尚存尘漠漠，盐舟不至草离离。","忧勤更忆东山老，白发江村一短藜。"]},{"t":"次魏士华韵岳州道中","f":"古风","c":["懒赋新诗记所经，谁欤能为我歌听。","日生凉色荒荒白，山露寒姿叠叠青。","晚席洗?分急水，夜船挝鼓视明星。","长沙有约君先到，何处登高倚草亭。"]},{"t":"送马参议公御之陜西","f":"七言律诗","c":["外省元兼内六曹，使君西去更贤劳。","迎舟风助黄流急，随马云分华岳高。","远道谁教歌憩茇，丰年独遣问啼号。","一尊未尽临岐思，寒日荒荒满节旄。"]},{"t":"夜坐怀刘用熙","f":"七言律诗","c":["芦泉本是神仙骨，误落人间识者稀。","听竹每联风雨榻，涉江曾制芰荷衣。","台荒蓟北千金筑，帆远吴西一鹤飞。","寒日萧萧那可度，凭君预拂钓鱼矶。"]},{"t":"送工侍徐公致政南还途中有作","f":"七言律诗","c":["祖帐东门久不陈，古人高致又今人。","阙庭回首风光远，岐路关心雨色新。","图画应传千万本，经纶方倚二三臣。","送君濯发沧溟水，晚节堂前戴角巾。"]},{"t":"送张淳安羽","f":"七言律诗","c":["清才往往爱君诗，百里为郎奈别离。","州县未为吾道屈，江湖真见此行宜。","水连晚渡宁辞远，春入山城却恨迟。","更爱公馀多古意，蛟峰高处读遗碑。"]},{"t":"赠李天瑞","f":"七言律诗","c":["坐听寒漏二更馀，一榻全胜两地书。","愁到几时凭我解，病从今日为君除。","雪泥满地淹行李，云岛如天阻卜居。","莫怪明朝欲投辖，江湖回首雁应疏。"]},{"t":"送朱工部请告归上虞","f":"七言律诗","c":["记得逢君在乐平，新凉庭院碧梧清。","周官六典曾司寇，禹贡三江又水衡。","泽国烟波吟里兴，云林风日病馀情。","西兴渡口犹回首，闻道秋潮昨夜生。"]},{"t":"大忠祠奉次西涯先生韵二首 其一","f":"七言律诗","c":["水上浮城忽已墟，龙宫真作帝王居。","生回故主时无及，死见先君地有馀。","一息尚存经合讲，百身难赎史空书。","从来独许王陵正，平勃虽贤恐未如。"]},{"t":"大忠祠奉次西涯先生韵二首 其二","f":"七言律诗","c":["瓣香难救欲沉舟，虏气昏昏暗九州。","今日鲁连真蹈险，它年江统浪含愁。","馀生未了东还计，即死能忘北向雠。","地下欲从行在所，海陵朝撼朔风秋。"]},{"t":"答陈提学文鸣","f":"七言律诗","c":["楚帆连日阻南东，到处鱼羹老母同。","春水稳当新涨后，晚山青在旧游中。","宦情于我聊今日，师道如公自古风。","遥想楼船吟眺处，潇湘千里一虚空。"]},{"t":"通州相城呈同事诸公二首 其一","f":"七言律诗","c":["眼中形势尽登临，前辈经营亦苦心。","一道星河天廪近，千年风气水门深。","驿亭东去多辽使，商舶南来半越吟。","漕计经春定何似，长安三月米如金。"]},{"t":"通州相城呈同事诸公二首 其二","f":"七言律诗","c":["肩舆南浦复西邱，尽日淹留为此州。","云隐层城才见塔，水漫孤渡偶逢舟。","林风力浅花能晚，山雨声迟麦未秋。","最是中丞忧国计，几回独立向东流。"]},{"t":"乞终养未许","f":"七言律诗","c":["乞归未许奈亲何，帝里风光梦里过。","三月春寒青草短，五湖天远白云多。","客囊衣在缝犹密，驿骑书来字欲磨。","圣主恩深臣分浅，百年心事两蹉跎。"]},{"t":"闻侍养命喜而有述","f":"七言律诗","c":["五疏才蒙一语俞，拜扶老母望天除。","孤孀节操劬劳外，独苦心情喜惧馀。","宽处栽花占月令，静中检药印方书。","东风吹绿长春径，不羡潘家有板舆。"]},{"t":"客有持宁庵诗至山中者次韵赠之","f":"七言绝句","c":["山中十里绿阴长，新涨浮浮架石梁。","赋罢蒹葭掩僧舍，午风销尽佛前香。"]},{"t":"雪中题陈工部画用苏韵","f":"七言古诗","c":["马蹄踏遍秋风叶，客怀还赏长安雪。","焚香小院对此图，此人此景俱清绝。","恍然不识是何方，冻云压峰峰欲折。","草亭孤坐非君谁，閒从水泡观生灭。","秋林老笔逼夏圭，千载风神一挥掣。","得来价直奚可论，万镒黄金千綵缬。","羡君平生有高趣，下视尘寰真不屑。","明朝持此归江南，小舸乘风去如瞥。","也知象意君自得，我为题诗皆赘说。","欲分半幅遮眼前，剪刀安得并州铁。"]},{"t":"九江赠冯地官","f":"七言古诗","c":["东曹故人东道主，今雨相逢如旧雨。","江边新阁速我登，坐阅千帆集烟渚。","百年榷政如江风，倏平忽险胡能同。","平涵云日浴凫鹭，险鼓雷雨腾蛟龙。","我行观风四经此，野有歌谣民有史。","燕南楚北天茫茫，青眼高歌对吾子。"]},{"t":"赠陆瘦竹","f":"五言律诗","c":["郡幕奔趋日，谁知瘦竹公。","愁深相别处，兴远独归中。","古篆山中石，新歌水上风。","宁庵如我问，夜夜梦江东。"]},{"t":"次南沙宿惠山寺","f":"五言律诗","c":["才阁南沙榻，乘閒我又来。","为谁山有月，从此径无苔。","霜怯千年树，云低百尺台。","题名忘岁月，岩畔桂初开。"]},{"t":"偶饮野翁庄有怀翁他日相与之雅情见乎词用元人韵","f":"七言律诗","c":["相逢馆下屡宾阶，卷有新诗许我开。","鬓未及年皤似雪，眼将入道碧于苔。","良工心苦春收药，佳客盟寒晚折梅。","酒罢题诗脩竹上，邻僧犹待野翁来。"]},{"t":"羲皇谣","f":"古风","c":["无怀民，葛天民，梦邪真，天下无邦我有身。","有身可醉亦可贫，我将用此全吾神。","归来赋成《江有津》，茫茫海内皆风尘。","菊花吾秋柳吾春，先生非邪谁谓羲皇人。"]},{"t":"天马来","f":"古风","c":["天马来，来何方。","易有占，乃尔荒。","先乌孙，后大宛。","马是非，天近远。","使端广，民怨多。","天不闻，如马何。"]},{"t":"三千牍","f":"古风","c":["三千牍，二月读。","君何劳，臣何渎。","申公言，言不在多。","止辄乙，今如何。","右《吕獒》，左《无逸》。","不如对此朝还夕。"]},{"t":"禽言","f":"楚辞体","c":["看蚕看火。","昨夜小姑今夜我。","夜不能眠昼不坐。","火弗戒兮蚕受祸。","无丝可。","无绵可。","蚕死惨那。","看蚕看火。"]},{"t":"听松","f":"五言古诗","c":["听松复听松，松声在高阁。","阁成四十年，听者今如昨。","风来春涛生，风去秋涛落。","当其无风时，萧然亦微作。","聪者听于斯，冥心对寥廓。"]},{"t":"和浦文玉观水 其一","f":"五言律诗","c":["新晴出郭门，四野惟一水。","忆自庚午年，雨恒尝见此。","坐我天上身，江南画船里。","陶谢空遐思，今有桂岩子。"]},{"t":"和浦文玉观水 其四","f":"五言律诗","c":["万壑正横流，我方浚泉水。","山灵如有知，应笑我为此。","我泉亦何心，一道苍茫里。","沧浪复沧浪，野歌听孺子。"]},{"t":"醉石为王翁赋","f":"古风","c":["湖上秋容淡如拭，有人时卧林间石。","石边有路通醉乡，梦邪真邪人不识。","人有托，物无情。","石可醉，亦可醒，一声何处沧浪清。"]},{"t":"题画","f":"七言古诗","c":["近山如城人可住，远山如屏带烟雾。","天际孤舟何处来，云中指点津头树。","客至桃源花正春，回首空嗟相见暮。","苍壁丹厓几万寻，飞鸟回旋不知路。","路逢樵者问山名，山深只为无名故。","中有青莲今古青，时向幽人一披露。","冯生学画举业馀，胸中尘土先扫除。","清秋此幅展向我，请我茅笔纵横书。","南沙风韵杜陵后，随物赋形吾不如。"]},{"t":"送萧户部","f":"七言古诗","c":["水衡之司天下七，算舟通楮时制同。","京师南来四千里，浒墅实当吴会中。","地官主事延平彦，鸾栖旧在吴江县。","政平如水起歌谣，今之歌谣乃重见。","司徒搉课岁有常，数或不经宁惠商。","太原周公有是语，至今传诵盈庙堂。","萧君不苛亦不纵，隐然名为司徒重。","江边野老阅人多，独汲山泉远相送。"]},{"t":"太白山人歌为关西孙太初赋","f":"七言古诗","c":["山人西从太白来，东南胜览穷天台。","凤歌落落复自和，笑问楚狂安在哉。","江陵曾见子微否，道骨仙风子真有。","神游八极偕者谁，江上听潮何太久。","山人西望几回首，石室高寒逼星斗。","六月争传雪未消，万峰谁遣云长守。","南来遗我方山冠，何以报之青琅玕。","杜陵诗人不可作，击节虚堂风雨寒。"]},{"t":"再作太白山人歌","f":"古风","c":["吾闻太白之山倚西极，华岳崚嶒势相敌。","上凌刚风太古雪尚寒，下抚苍茫鸟无力。","吁嗟兹山有径不与终南通，士将避世往往游其中，超历万壑巢云松。","伊昔丈人负刍者，危言曾动河汾公，至今谈麈流清风。","孙君关中豪，仰止兹山高。","自称山人巾葛白布袍，入山静坐观众妙，出指八极将翔翱。","胸有五色文，眼底无青紫。","名家自视出杜陵，走笔题诗乃如史。","子长有语称董生，季主何心讥贾子。","迩来五见江东春，南寻禹穴能知津。","相逢下我东野拜，何人复谓秦无人。","我作山人歌，物色其柰山人何。","山林岁年晚，江海风雨多。","山人不归太白空嵯峨。"]},{"t":"南轩为陈廷仪赋","f":"五言律诗","c":["南轩何处是，负郭小桥东。","客复来今雨，山如对此翁。","有怀将献曝，无愠亦歌风。","期日往称寿，老人星正中。"]},{"t":"赠周育斋","f":"五言律诗","c":["风雨秋堂冷，公来便作春。","雅情长共物，妙语不惊人。","池养寒泉静，园收硕果仁。","飘然还画舫，湖海自知津。"]},{"t":"渐霁","f":"五言律诗","c":["渐霁驱愁思，无风稻正花。","径来今雨客，烟起野人家。","晚榻将新月，秋溪有净沙。","东邻知我兴，多事报山华。"]},{"t":"赠钱校书","f":"七言绝句","c":["夫椒山前孤草亭，水风吹月秋冥冥。","客来鹤去主人返，七十二峰湖上青。"]},{"t":"寄许东庐","f":"七言绝句","c":["冲雨冲风一事无，东陂南荡水连湖。","兴如王戴非因雪，他日休烦作画图。"]},{"t":"白石草堂奉次涯翁先生二首 其一","f":"七言律诗","c":["北望长安近日边，春风函丈忆当年。","新题岁月经纶外，晚节乾坤杖几前。","诗卷有情多汲引，门墙何日更延缘。","朝来忽对林京口，却道西堂别是天。"]},{"t":"白石草堂奉次涯翁先生二首 其二","f":"七言律诗","c":["草堂回首海云边，旧路依稀几隔年。","白石峰高幽兴里，沧江水阔大方前。","閒来月棹频乘梦，老去云巢再结缘。","领得涯翁新墨去，文星长照斗南天。"]},{"t":"又用前韵寄林镇江","f":"七言律诗","c":["诗兴时来案牍边，故山风物自年年。","渌分一水桥南北，青拥群峰屋后前。","明月半窗空有梦，清风两腋竟何缘。","秪应独上金山寺，吟倚沧江万里天。"]},{"t":"雨坐用旧韵","f":"七言律诗","c":["檐溜声闻隐几边，去年多雨复今年。","林皋绿树层城外，江浦黄梅五月前。","夜榻长悬须雅客，昼帘深下谢尘缘。","西山云气东山月，他日容春亦此天。"]},{"t":"静中写怀用前韵","f":"七言律诗","c":["策杖山边复水边，病馀翻喜得长年。","风光共逐初晴后，春色还怜未雨前。","何处乾坤堪一啸，平生泉石本多缘。","閒来独上西楼望，古华峰高正倚天。"]},{"t":"寄崔工侍民瞻用前韵","f":"七言律诗","c":["郴州南望楚云边，颜色长怀别我年。","岭北春从梅折后，衡阳书在雁归前。","雪淹夜榻无佳兴，月照秋槎有胜缘。","病起莱衣方再舞，晚风吹雨过梅天。"]},{"t":"荅朱云厓何梅壑复用前韵","f":"七言律诗","c":["腹笥便便不姓边，暮年诗兴似青年。","一春风雨题缄外，万古江山放笔前。","壑倚梅花真入画，云生厓石自成缘。","晚凉相过须乘兴，酒在清樽月在天。"]},{"t":"又荅林镇江","f":"七言律诗","c":["麻姑山下石矶边，舣棹逢君是此年。","落月梦长千里外，归云心远九峰前。","东曹吏牍忙中事，南国诗筒病后缘。","公暇漫从江郭眺，沧浪歌起白鸥天。"]},{"t":"书院新成再用前韵 其一","f":"七言律诗","c":["小堂开向绿阴边，故老相过问往年。","水接少陵新槛外，草生茂叔旧庭前。","山从西望城才隔，溪自东行路亦缘。","微醉独歌人莫讶，春衣初试晚晴天。"]},{"t":"书院新成再用前韵 其二","f":"七言律诗","c":["书策重翻架上尘，两年多负病中春。","手将笔试初知健，心与盘铭几见新。","方得养亲真爱日，未成报国敢轻身。","冉泾门巷深如许，击节高歌不和人。"]},{"t":"病起山行","f":"七言律诗","c":["半年病足懒登山，咫尺烟霞梦寐间。","再到欲题新岁月，相逢争识旧容颜。","流过乱石清泉静，飞尽浮云翠壁间。","漫道坐来多渴思，一茶还待老僧还。"]},{"t":"寒日怀卧云上人用昌黎韵","f":"七言律诗","c":["病馀情绪还无赖，久拟临泉洗宿埃。","载酒定须三宿返，送茶时复一僧来。","身从白日风时避，眼到青山雪处回。","为问西斋悬榻地，荒云和叶几堆堆。"]},{"t":"幽居四咏 其一 树色","f":"七言律诗","c":["乍浓还淡弄朝晖，树色依稀定是非。","楼上望回川历历，城阴遮断路微微。","晓云有影团倾盖，春水无波渌染衣。","独坐怀人心正远，天空渭北雁初归。"]},{"t":"幽居四咏 其二 花香","f":"七言律诗","c":["花气絪缊共煖风，谁从起处问西东。","偶来似与游丝下，却散还随梦蝶空。","曲槛有时应独驻，幽居何地不相通。","等閒拟得涯翁句，已落人间色相中。"]},{"t":"幽居四咏 其三 鸟声","f":"七言律诗","c":["一鸟不鸣山可怜，更怜鸣鸟过檐前。","友声信有如莺语，喜报曾闻是鹊传。","南国音成非别调，北窗梦醒正閒眠。","近来习静心初定，独把无声寄五弦。"]},{"t":"幽居四咏 其四 鹤舞","f":"七言律诗","c":["误向丹邱共羽流，多情今得此亭幽。","长鸣似与高人语，屡舞谁于醉客求。","风羽九逵能抗晚，野心万里欲横秋。","试将衣袖閒招引，转尽花阴意未休。"]},{"t":"寄贺黄门先生","f":"七言律诗","c":["万丈医闾万丈云，白头何地可寻君。","懒招海贾非无谓，笑荅山灵似有闻。","秋水竿留巢父在，春风榻与管宁分。","数封再检先朝疏，望断天涯坐夕曛。"]},{"t":"送戴仲鹖谪岭南和侯明府","f":"七言律诗","c":["清江浦口驰词地，左顺门前待报时。","远道谪官何日到，小臣忧国有天知。","镜看白发朝还掩，棹指青山晚更移。","老我閒居复多病，秋来愁和送君诗。"]},{"t":"雪洲追吊夏叔度亦用涯翁尊师韵","f":"七言律诗","c":["月寒沙白水如烟，兴在中洲望宛然。","岂有机心将避世，不知医道已通仙。","孤舟自系须人渡，一鹤时飞为客传。","雨露春来江岸阔，吊君何处放湖船。"]},{"t":"雨中和荅浦文玉","f":"七言律诗","c":["五月江寒昼阁清，雨中草色唤愁生。","系舟未问水深浅，策杖还看云重轻。","客去不知谈未尽，诗来刚及梦初醒。","百年吾道今如此，何处沧浪共濯缨。"]},{"t":"山中访王校书 其二","f":"七言律诗","c":["连阴晓为北风开，春入山中第一回。","亭上远天须捲幔，槛前新水欲浮杯。","校书客避参军辟，问字人传别驾来。","明日更邀朱趣玉，黄公涧畔踏苍苔。"]},{"t":"九日与诸生适南野","f":"七言律诗","c":["重阳无雨慰农家，我亦閒行野水涯。","高岭未登心独往，美人不见眼谁遮。","云随风散千林净，溪抱村流一道斜。","有酒莫教都饮尽，明朝还约看黄花。"]},{"t":"松风阁追次莫东川韵二首 其一","f":"七言律诗","c":["倚天松不受风摇，白鹤回翔似有招。","何处客来忘此阁，故人诗在忆同朝。","采苓每带云双屐，供石时添水一瓢。","莫道山中无语者，老僧送罢又逢樵。"]},{"t":"惠山杂歌 其一","f":"七言绝句","c":["踏踏儿郎从老翁，惠山寺里看新钟。","问道新钟几时撞，九秋霜落树头红。"]},{"t":"惠山杂歌 其二","f":"七言绝句","c":["箫鼓迎神神下山，香烟满路送神还。","安得村村无病苦，灵泉不动庙门閒。"]},{"t":"惠山杂歌 其三","f":"七言绝句","c":["听松庵里双古松，松下石床苍藓封。","洗却苔痕看古刻，志书传是米南宫。"]},{"t":"惠山杂歌 其四","f":"七言绝句","c":["漪澜堂下水长流，暮暮朝朝客未休。","纵有《茶经》无陆羽，空教煎白老僧头。"]},{"t":"惠山杂歌 其五","f":"七言绝句","c":["登登山路转山阿，须向仙人洞口过。","涧水满时青草短，岩花深处白云多。"]},{"t":"惠山杂歌 其六","f":"七言绝句","c":["南祠忠定北文襄，千古青山两瓣香。","莫问前朝松柏树，祗今何处有甘棠。"]},{"t":"八月二十九日门人华云来自汪司成器之所致吾师少师西涯先生之讣哭已有作","f":"七言律诗","c":["忽自司成得讣音，燕山湘水夜沈沈。","百年恩义师兼父，千载文章古在今。","无路可奔空缟素，有身堪铸乏黄金。","京华北斗遥瞻处，泣对朱弦欲毁琴。"]},{"t":"越明日寝哭后作","f":"七言律诗","c":["别公已分见无期，不谓伤心在此时。","再致语将茎露酒，两知音托惠泉诗。","山中几杖操今远，雪里门墙立故迟。","最是寿筵宾客散，西风吹雨夜凄其。"]},{"t":"是日检箧得公壬戌和宝哭徵伯诗","f":"七言律诗","c":["悲歌当哭不论诗，长忆先生哭子时。","今日又兴天下恸，他年真拜古人师。","涛驱东海曾于砚，石采西山故可碑。","一念九原应未暝，白头亲尚在慈闱。"]},{"t":"雨中念乔司马不得会哭","f":"七言律诗","c":["烛照高斋坐论文，十回侍侧九乔君。","讣传两地恸复恸，声隔九原闻不闻。","南国江山愁夜雨，西涯水月梦秋云。","独怜风雪泷冈馆，犹许幽谈到夕曛。"]},{"t":"张提学寄先师文正公新集至代简为荅","f":"七言律诗","c":["遗书新刻自徽州，千里缄来百拜收。","自是叔孙知不朽，未应巢父得长留。","秘藏不作山中计，重购还供海外求。","青眼独看张侍御，瓣香今有古风流。"]},{"t":"忆文正公尝欲卜居宜兴","f":"七言律诗","c":["几年卜筑欲江东，阳羡溪山罨画中。","千里有情春草遍，一樽无地暮云空。","相州未得归韩老，汝颍犹堪葬长公。","曾说近游须馆我，吾亭今合号涯翁。"]},{"t":"发文正公吊书后有作 其四","f":"五言律诗","c":["有句传江左，长教和且歌。","未应知己少，自是爱人多。","云野秋无雨，风江晚更波。","伤心门下士，鬓发渐成皤。"]},{"t":"听松偶成","f":"七言绝句","c":["秋深水国候来鸿，一夜悲凉见朔风。","行遍冉泾无语者，听松阁上哭涯翁。"]},{"t":"毁龙骨辞","f":"楚辞体","c":["变化风雨兮上下于天。","古人有言兮维龙则然。","龙曷能然兮乘气与时斯以体乾。","尺窟兮非渊。","勺水兮非川。","彼朽骨兮几何岁年。","击鼓兮田田。","巫舞兮翩翩。","士女会兮如廛。","龙无灵兮胡托彼传。","龙有灵兮彼胡制旃。","骨则何罪兮巫之愆。","逐彼巫兮毁斯骨。","为吾民兮辟妖物。"]},{"t":"荆蛮操","f":"楚辞体","c":["彼有物兮不可以取。","我有心兮不可以语。","不可以语兮安可以处。","荆蛮渺兮何许。","逝将徂兮终我攸宇。","吁嗟乎，苟获我心兮孰非我所。"]},{"t":"哀秦封君辞","f":"楚辞体","c":["违先生盖数载兮，忽南向以兴嗟。","望碧山而不可往兮，渺愁云于天涯。","问九原之安在兮，慨德音之永遐。","维先生之明哲兮，固神启而天赋。","筮遇履而之无妄兮，曰坦坦其幽素。","服兰菊而佩蘅兮，步前修以为度。","春与秋其汲汲兮，恐岁年之迟暮。","惟至美不能以终秘兮，于灿发于文章。","窥门墙乎汉魏兮谐律吕于中唐。","挥贾涕于太息兮，舒孙啸于独伤。","知先生谓为逸民兮，不知者曰其忘世。","言博利以为仁兮，守善藏以为智。","维厥子之登庸兮，亦讵非先生之所施。","繄太邱之率物兮，树东京之高风。","越弘景之退处兮，乃托迹于神农。","众剪剪于寻丈兮，亦孰能知夫所从。","苟此志之不愆兮，又何分乎达与穷。","始趋涂之各异兮，终要归以皆同。","徵孟生之为贞兮，附陶氏之为靖。","曰舆情其既公兮，信棺盖而后定。","彼曷其独不死兮，顾偷生之为幸。","呜呼先生兮，庶其得正。","怅余怀之无聊兮，掩遗编以长谣。","极四方与上下兮，肆远索而旁招。","典刑辽阔兮，里社萧条。","彼水之澨兮，山之椒。","先生不归兮，使我心劳。"]},{"t":"庆成侍燕","f":"五言古诗","c":["嘉燕陈明堂，黼座当春阳。","惠风拂宫扇，亲睹穆穆光。","冠簪肃趋拜，共进万寿觞。","箫韶叶舞佾，宛然见虞唐。","三苗独何为，不如兽跄跄。","天高复地厚，永世垂衣裳。"]},{"t":"送东山公行边","f":"五言古诗","c":["司徒始受命，朝野贺得人。","两边数万骑，所望公一身。","公囊无刍粮，公心有经纶。","亦有为国念，对越天与神。","岂不知匮乏，鞠躬在兹辰。","公复不自用，乃荐一二臣。","遗事旁搜阅，微言博咨询。","稽首殿陛下，丰仪动高旻。","登车向西郭，尊俎罗朝绅。","慨然尽馀酌，老眼无边尘。","谓公唐室晏，谓公汉家恂。","千载有韩范，公也真其伦。","公有激众义，公有抚众仁。","未至百草秋，既至万卉春。","缓急在公手，琐琐何足陈。"]},{"t":"送刘用熙","f":"七言古诗","c":["今之异人刘牧龙，绰有两汉先秦风。","等閒踪迹不肯露，下混此世将无同。","或时耿耿作怪语，恍忽使我难形容。","殷彝周鼎初出土，置在清庙明堂中。","又如江水撞石钟，天然音调非人工。","蛟龙跃舞送雷雨，倏歘霁景留云松。","直将飞步泰华峰，沐浴沆瀣观洪濛。","身骑白鹤真自适，口啖紫芝犹未穷。","彼哉皦皦不解事，唯子能固还能通。","我今规子复有说，古来夷隘惠不恭。","吁嗟此别拟三载，河淮合流日夜东，尚友千古谁其从。"]},{"t":"惠山泉歌奉次涯翁先生","f":"古风","c":["击石长歌复长啸，山无人声泉有窍。","诗人曾谓兹山空，又闻山与南海通。","向来泉托山人姓，公为收名名始定。","石池左右多槛泉，东流迤逦非突还非悬。","公门如海纳川水，肯向东方遗一士。","出山还似在山清，中有石子星之精。","别公无言怀独泻，公乃题诗赠行者。","高词尽得今古奇，我歌合向观泉时。","年年寿公泉一酌，公每书来问瀺灂。","援琴欲寄山中音，水风吹月千里无遐心。"]},{"t":"世恩席上答诸公","f":"七言古诗","c":["我行西江自江东，载书千里乘天风。","今夕何夕诗坛中，碧瞳共照灯花红。","欧阳居士苏坡翁，文星烂漫今古同。","不才有幸承诸公，翰林四老儒之通。","金石一振万籁空，司封明并两考功。","高堂白日悬青铜，少游才思如冥鸿。","江湖渺渺谁能穷，职方平生怀至忠。","每谈疆埸思弯弓，从容授简钱南宫。","总会诸壑归三洪，清秋携对江上枫。","亦有短句随鸣虫，云霄北上劳湘筒。"]},{"t":"寿张都运先生","f":"古风","c":["古之洛社在洛中，其人往矣犹高风。","今之洛社名偶同，乃在蓉湖之北龙。","峰之东，中有主者心好古，脱略尘网追遗踪。","忆从三策献天子，释褐登廷称进士。","漫将时事寄吟哦，对客挥毫思如水。","职方郎官领禁符，观风三辅赋两都。","朝鲜使者出关去，尽道威明前所无。","镇东楼高绝云海，想见当年美丰采。","洞庭烟水严滩云，耿耿幽怀三十载。","人言州县徒劳人，使君所至皆阳春。","平生经济有馀地，万里江湖空一身。","今年归来闽海上，洛社新堂旧屏障。","满庭宾客燕清秋，水色山光正相向。","先生谢客焚妙香，紫微天远云衢长，膝前觞献森诸郎。","君不见黎平谣，东平志，回首他年皆小试。","愿公再起再归来，手植青松看晚翠。"]},{"t":"赠王生子春","f":"五言古诗","c":["子从天台来，衣裳带云气。","谁知山泽臞，有志在当世。","经史随所询，一一见深致。","董生去古近，高明得超诣。","胡然丛猥中，独与前修契。","士患饥与寒，大节穷愈励。","论事须尽变，变尽乃精义。","源头浚真泉，如斯日川逝。","孰谓政粗迹，而谓文小技。","所贵道在兹，毫釐辨同异。","我行入湖南，子作东归计。","伯氏古逸民，知我知子意。","明年黄鹤楼，待子共光霁。"]},{"t":"邃庵诗","f":"七言古诗","c":["长安陌上结书屋，庭院沈沈几纡曲。","最深者号文密房，如度层云入幽谷。","主人峨冠讲且读，上溯虞唐犹未足。","手探元化玄更玄，诸生拱侍森如玉。","原泉滔滔放四隩，始知大雅歌穆穆。","声宏以实理则然，陋彼寻常事边幅。","陵莪菁菁时雨沐，不出户庭人望属。","乍闻俎豆复军旅，平视边隅如辇毂。","隐微知谨公所独，至虚生白能旁烛。","苏公漫说风水涣，邵子閒吟地雷复。","我曹浅薄徒有目，辱许升堂载瞻肃。","行行深入得大观，何处湘南还岳麓。"]},{"t":"江雨来","f":"七言律诗","c":["西津渡头江雨来，雨点入江江水回。","云飞逐风沙走石，咫尺不见东冈台。","台树丛丛还可望，台上看江更奔放。","明朝拟下鄱阳船，月色浮江水微浪。"]},{"t":"题卧龙庵用晦翁韵","f":"五言古诗","c":["此有石如龙，天成谅非凿。","是何空洞中，云水起复落。","常疑雷雨时，飞舞出深壑。","作庵者何人，清风宛如昨。","两公固龙德，恨也俱晚作。","秋霖不济旱，千载领馀酌。","方切忧旱怀，行矣予所乐。","江湖极秋波，长歌对冥漠。"]},{"t":"至亡女七儿墓","f":"楚辞体","c":["日无光兮风色寒，望儿坟兮心悲酸。","坟有土兮土有棺，儿咫尺兮欲见难。","浇浇坟头酒易乾，纸成灰兮散漫漫。","散漫漫，魂不返，清泪下兮盈酒?。"]},{"t":"题元章拜石图为俞国昌","f":"五言古诗","c":["元章玩世人，低头拜奇石。","或问此何为，我意人不识。","璆琳岂有声，碣砥且无力。","拜如或使之，但觉吾意适。","石奇恐未多，屡拜非所惜。","我心不可转，万仞立苍壁。","石也倘能拜，向我须屈膝。","今虽无膝屈，有拜当以臆。","我今对画图，兀坐风雨夕。","击磬和新吟，他年亦陈迹。"]},{"t":"泉上赠钱水部","f":"五言古诗","c":["君来访我庐，我方行山中。","命驾即我所，浩兴乘天风。","风晨与雪夕，今古将无同。","岂在形迹间，所贵心相逢。","我有一勺泉，坐奠桑苧翁。","载酌持献君，侑以金芙蓉。","或歌沧浪篇，声在涧水东。","君闻乃和之，击节秋山空。","坐我石坛上，共听风前松。"]},{"t":"寄题钱水部诗冢次沈石田韵","f":"五言古诗","c":["钱翁作诗冢，粤惟己巳年。","厥地乃旧游，山水相延缘。","翁诗出翁心，混混真源泉。","譬诸山泽臞，勤修欲成仙。","载赓阳春调，剩读秋水篇。","知音孰云少，三叹闻朱弦。","嗟予遇君晚，纵言及前贤。","官衔列水部，诗名亦由天。","投簪谢明主，瀼西视琴川。","点检手所笔，清兴常飘然。","天机忌独泄，穴置还幽玄。","行将化为石，万古存贞坚。","寻常有匡山，头白归青莲。","韬光伺来哲，古道君有焉。"]},{"t":"忠定祠享歌二首 其一 迎神","f":"楚辞体","c":["吉日蠲兮祠公。","佩锵趋兮庭中。","湛露洒兮天风。","暾初发兮水东。","灵皇皇兮既降。","凤下仪兮翔龙。","响应谷兮鼓钟。","慰予思兮公有嘉容。"]},{"t":"忠定祠享歌二首 其二 送神","f":"楚辞体","c":["神翱翔兮渐遐。","载白云兮紫霞。","墓闽山兮天之涯。","钱塘兮公第，梁溪兮公家。","陆有梁兮海有槎。","我思公兮咨嗟。"]},{"t":"酒间短歌次吴太史","f":"七言古诗","c":["延陵太史文之豪，手持椽笔轻一毫。","却厌漆镂思匏陶，别筑坛社延风骚。","健如风舸凌秋涛，元气浩浩天滔滔。","忽入冰壑难容舠，豫章言必称禹皋。","下视元白等播鼗，坐令万类归笼牢。","间出水碧兼金膏，关西夫子真凤毛。","咳唾中律鸣鸾刀，风吹锦服飘双绦。","仙骨曾啖瑶池桃，手持权衡有纵操。","收敛英迈胸中韬，彼哉坐井吝以骄。","瑞物一见辟百妖，裁之品藻谁能逃。","深许抱瓮恶桔槔，一日千里不觉劳。","何尝仰首逢人号，我喜麻直能扶蒿。","起家江左大布袍，两以文字魁群髦。","宝鉴出匣弓辞韬，东陵野人随羽旄。","不饮自醉黄生醪，雅终奏俗空嘈嘈。","不可得麾安可招，自知一著良独高。"]},{"t":"芝山寺题壁","f":"五言古诗","c":["芝山草如黛，青春空复过。","我来憩古寺，落花看渐多。","林莺惜芳景，和我登山歌。","白日不可挽，更奈风雨何。","老僧供香茗，小坐成天和。","江公旧游处，长松挂新萝。","止水一亩池，流衍同江河。","晚峰纵高眺，番阳渺云波。","五老近相别，笑指庐山阿。"]},{"t":"湘夫人用唐人韵","f":"五言古诗","c":["洒泪向楚岫，白云生远愁。","重华不复返，江水日夜流。","美人美如玉，春草满汀洲。"]},{"t":"望云卷","f":"五言律诗","c":["龙山一片云，万古白未了。","松楸谁家坟，青青倚孤峤。","望云起孝思，无间昏与晓。","我怀狄梁公，清风满华表。"]},{"t":"剑江道中","f":"五言古诗","c":["我携数卷书，歌诵剑江上。","书中何所言，一一超形象。","我心会其神，源泉莫知乡。","中有几微存，欲语恐添障。","安得凌长风，趋拜濂溪丈。"]},{"t":"为龙佥事致仁题画","f":"七言律诗","c":["爱汝钟山草堂静，我欲造之无所因。","百年观物自得意，风吹淮水波潾潾。","小舟西来乘有人，悠然兴到山花春。","便须入室尽此夕，沧浪一声何处津。"]},{"t":"吴太史画册","f":"五言古诗","c":["云飞本无意，鹤鸣复何心。","危登复长啸，我亦开吾襟。","云哉承我御，鹤也起我吟。","兴至不自知，天地高且深。","俯仰八极中，悠悠怀古今。"]},{"t":"无鱼","f":"五言古诗","c":["沽海富鱼虾，过者多买食。","异哉有今年，兹物或几息。","载歌丰年诗，临渊三太息。"]},{"t":"乐安大岭次见素公","f":"五言古诗","c":["海岭夙孕秀，登廷持忠清。","廿载正色立，千秋和声鸣。","此地屈体力，吾人增光精。","雾瘴久阏积，霆飙初流行。","鹤骨瘦竦直，鸾仪繁披横。","在北本岱岳，于南聊方城。","万姓忽雨润，三公真云轻。","亢作汲老揖，卑为侯生迎。","吏属苦切束，工徒欣番更。","辟异有故事，推贤无遗名。","父老睹后恐，儿童瞻先争。","一语破讼牒，双声游诗评。","砥柱赖独障，扶摇看高征。","孔孟道雅振，皋夔功奇成。","凿凿社稷计，昭昭神明盟。","传纪黜楚越，诗歌惩舒荆。","雅颂古圣则，春秋今王程。","面质祖训若，心期皇猷平。","谊策重国事，轲书高天氓。","九鼎任一摰，无劳怀莘耕。"]},{"t":"题郭子仪见虏图","f":"古风","c":["唐之大将汾阳公，天畀才略成贞忠。","平生信义贯金石，仓卒眼底无羌戎。","戎来如云驱以风，我下我马何从容。","诸酋罗拜誓酹酒，大人先兆巫言中。","世称谈笑可折冲，万古一羽云霄空。","龙眠居士丹青雄，笔到此事真奇逢。","寻常传玩岁复月，时于敝箧腾长虹。","焚香坐阅精神通，古来尚友只数老，九原可作吾其从。","于嗟乎九原可作吾其从。"]},{"t":"济河谣夜过青县作","f":"古风","c":["河可济济师，不可济济贼。","贼济避我师，东入钜野泽。","泽西为济南为淮，贼乎贼乎安往哉。","野多罄室无青草，豕突鲸奔我师老，却恨令公来不蚤。"]},{"t":"天津舟中夜坐观水","f":"五言古诗","c":["河水东注海，海流亦复东。","人言如沃焦，毕竟谁能穷。","蓬莱不可渡，万里悲天风。","北斗揭西柄，影落清波中。","耿耿欲回澜，荡漾涵虚空。","昔闻有碣石，助禹成神功。","我将往求之，道险多蛟龙。","静观叹逝者，缅怀川上翁。"]},{"t":"偶读盖岩传","f":"楚辞体","c":["六兽入室莫敢撄，岩也追格不税缨。","仆分有死义无生，家为重兮身为轻。","兽在途，剑在手。","一狐歼，五狼走。","我报主人我何有，有仆如岩主知否。"]},{"t":"题太白图","f":"七言古诗","c":["仙人骑驴如骑鲸，睥睨尘海思东瀛。","等閒相逢但叱咜，谁知万古千秋情。","醉来天地小于斗，鞭策雷霆鬼神走。","豪奇自比齐东人，大雅犹怀鲁中叟。","青春想像华清宫，解识仙人图画中。","满浮渌酒唤不醒，葛巾飒飒生天风。"]},{"t":"山樵曲","f":"古风","c":["南山高，高入云。","中有隐者操斧斤。","上方伐木下界闻。","声可闻，人不可即。","自上求之雾湿我衣，自下从之涧阻我舄。","县厓如天劳我力。"]},{"t":"郊坛分献东镇退而有述","f":"五言古诗","c":["登坛礼东镇，嶪峨如在前。","惟皇对上帝，小臣敢忘虔。","沂山望海岱，其高薄云天。","岂无方国祀，百灵合从乾。","惠风自巽隅，馨香偏中天。","明神固无语，我思通幽玄。","心祈耳复听，影响若有然。","山东盗方蔓，禾稼妨大田。","辑宁当自兹，在在歌丰年。","何以明予衷，素月西南悬。"]},{"t":"元夕独坐","f":"五言古诗","c":["月光照灯夕，清赏人所同。","而我独不乐，有亲在江东。","江东岂无月，白发少欢容。","念子未即见，厌见灯花红。","冉冉天边云，悠悠江上峰。","当食发长叹，何时得相从。"]},{"t":"秀江舟中","f":"五言古诗","c":["上水复下水，昨日非今朝。","春江渌如酒，天风澹飘摇。","坐数江上峰，乍近忽已遥。","归心如东流，迤逦迎海潮。","长歌武夷曲，和以庐山谣。","閒情寄芳草，极目青迢迢。"]},{"t":"渊明图为邃庵先生题","f":"古风","c":["吾闻先生本是山中人，谁遣作吏随风尘。","督邮迎送亦常事，浩然归兴凌秋旻。","孤怀每感孔明汉，一咏漫及荆轲秦。","北窗午梦入寥廓，南山秋色争嶙峋。","昨非今是公自道，门前五柳年年春。","柴桑彭泽才尺只，五老峰高隔彭蠡。","片帆朝挂暮及门，万古乾坤一江水。","昔闻奇幻谷城石，又闻清激严陵滩，是谁为易谁为难。","菊松三径地虽小，鸿鹄千里天何宽。","三南夫子今傅相，心期远在羲皇上。","君不见丁卯桥边山水深，江南春暮劳归心。","风云天上济时了，我亦访公携我琴。"]},{"t":"庐山谣用李韵","f":"古风","c":["庐山倚南极，乾坤一高邱。","绝顶有佳处，可作仙人楼。","诏书命我访奇品，等閒却遂平生游。","白鹿洞在五老傍，我来讲席重铺张，青云见彩霞生光。","玉声左右泉不断，我行东峰涧有梁。","眼明还直西南望，澄湖烟水俱苍苍。","不知乘舟者谁子，望我应恨天衢长。","庐山如庐几万间，与仙作主去复还。","黄尘滔滔似海水，此山即是蓬莱山。","载歌唐人诗，我句亦时发。","九江秀色行揽之，楚帆风送飞鸿没。","五老五老真有情，万峰之中独自成。","何时拄杖往参立，上呼群仙下紫京。","笑攀北斗挽银汉，共洗浊世邻太清。"]},{"t":"人日喜晴","f":"五言古诗","c":["我来洪都城，人日喜初霁。","夙兴省钟声，起视星斗丽。","澄湖动晨光，云霾散天际。","楼台东复西，参差蔼清气。","惠风荡前楹，公馀步还憩。","案牍杂诗书，吾事非日计。","独贺阳道亨，从兹破阴翳。","请看回轺时，春深满庭翠。"]},{"t":"新喻道中","f":"五言古诗","c":["夏木交垂阴，登登入山路。","遥峰薄云青，川原莽回互。","逾冈见长溪，可涉亦可渡。","驱车独西之，磴小仅容步。","幽花自成姿，时时竹间露。","仰观天宇宽，万有悉中布。","我怀美一人，沧江渺烟雾。"]},{"t":"香炉峰怀李谪仙","f":"七言律诗","c":["半空飞流天作奇，谪仙之诗真似之。","云松有巢今不见，但见老僧歌妙词。","香炉紫烟日复夕，散落平湖渺无迹。","九江秀色如我何，我访仙人东挂席。"]},{"t":"采薇曲","f":"五言律诗","c":["岐山有仁者，白首思来归。","愿闻康衢谣，不图见戎衣。","渴梦北海水，饥谢西山薇。","死从泰伯游，此志终无违。"]},{"t":"感兴和李懋卿 其一","f":"五言律诗","c":["明生又今夕，浮云亦消除。","风吹薄暮雨，炎歊为之袪。","而我坐中庭，洒然心静虚。","浩歌古人句，得意已忘书。"]},{"t":"感兴和李懋卿 其二","f":"五言律诗","c":["夏日苦炎热，浩思嵩山巅。","清泉环左右，佳木荫后前。","天风有时至，大音犹浑全。","坐此不能往，西望心独怜。"]},{"t":"感兴和李懋卿 其三","f":"五言律诗","c":["我行汝颍间，陶穴犹太古。","譬如观鼎彝，令人变闻睹。","岂无好楼居，巧极易摧腐。","回首太室山，一望高万武。"]},{"t":"久闻徐朝文讣见胡献臣始信","f":"五言古诗","c":["明听得金矢，有誉淮海区。","南征载持宪，清风与之俱。","楚氛接腥蜃，兵符杂刑书。","郑侨戒水狎，一日三年如。","慈元复祠庙，俨然古文儒。","坐令弄潢子，稍戢萑蒲馀。","进阶始称使，滇途险仍纡。","方忧万里驾，坦道生悲吁。","君病果何似，却怪平生臞。","琼瑰夙入梦，邱首真成虚。","瞑矣缘国事，浅之谁敢欤。","野哭古所恶，洒泪兰陵墟。"]},{"t":"楚江渔父图","f":"古风","c":["有臞一夫立荒浦，人云三闾问渔父。","楚江风景是邪非，而况原心越千古。","原心上有先王知，天地可质中无疑。","夫岂不解渔父意，扬波歠醨焉用之。","物无滞碍能推移，是圣者事吾何知。","苍苍故吾山，湛湛故吾水。","宗国如何吾病矣，九死侵寻无一是。","苍梧帝远天阍幽，上下四方徒远游。","云骖风驾倏万里，归来江上令人愁。","长揖向渔父，渔父难与谋，誓将鱼腹为狐邱。","君不见沧浪歌，渔父去，烟雾茫茫不知处。"]},{"t":"止水池","f":"古风","c":["止水池，芝山阴。","丞相初去国，指水矢此心。","水止心亦止，上有青天临。","朝临池，暮临池。","丞相心，人不知。","风尘来，江汉沸。","止水池，丞相死。","他日之心止于此。"]},{"t":"饶娥哭","f":"古风","c":["饶娥哭，哭何为。","哭求见父面，不图今见尸。","尸浮水怪露，已矣娥不知。","即使娥不死，见尸未但已。","伏尸三日哭，娥也终赴水。","娥心诚，水神灵。","江上如闻号恸声，水怪水怪犹纵横。"]},{"t":"砥柱歌","f":"古风","c":["黄河之水天上来，越数千里龙门开。","龙门南东有山出，是名砥柱千丈高崒嵂。","水来不敢冲，左右互洄潏。","山石岩岩复齿齿，力有几何能胜水。","从来元气植根深，万古千秋此中止。","君不见金焦两山控海门，江水到此势已分。","不如此山当河急流处，骤如风马方群奔。","秋涛春涨，暮撞朝击岿独存。","又不见碣石遮海道，九河播合今澜倒，不如此山为障早。","柱哉柱哉立自天，功成神禹乘舟年，沧桑有变此柱终无迁。","于嗟乎，沧桑有变此柱终无迁。"]},{"t":"补洛中越歌三首 其一 慕歌","f":"楚辞体","c":["慕歌兮慕歌。","东渐兮海波。","海无波兮山有阿。","明德远兮玉帛孔多。","微斯人兮吾如鱼何。","慕歌兮慕歌。"]},{"t":"补洛中越歌三首 其二 河女之章","f":"楚辞体","c":["潮何为兮不回，人何之兮不起。","父生兮女生，父死兮女死。","岁复岁兮江滨，人之心兮潮水。","潮水兮有声，伯姬兮有灵。","纷两涯兮观者，孰父子兮无情。","秋冥冥兮江峰青。"]},{"t":"补洛中越歌三首 其三 小海唱","f":"楚辞体","c":["潮来兮无天，潮去兮何地，若为凭兮斯厉。","彼鸱夷兮水中，匪匏瓜兮焉系。","潮来兮谁驱，潮去兮谁殿。","言之流兮何从，海东回兮镠箭。","潮来兮悲吴，潮去兮吊越。","忠千古兮长冤，潮复潮兮江月。"]},{"t":"观李剑州乐歌谱","f":"七言律诗","c":["凤箫声断惊风雨，十有三弦移短柱。","江上何人一笛横，别作黄钟起宫羽。","剑州剑州何苦心，小悬钟鼓高张琴。","吴歌听罢今蜀道，金玉近来真尔音。"]},{"t":"拟子陵辞","f":"楚辞体","c":["陵来为臣。","陵亦有言，辅义怀仁。","吾丧我守。","臣于何有。","陵去为友。","客星犯兮，日月光。","故人卧兮，江湖长。","来时心，去时迹。","山有云兮，江有石。"]},{"t":"狄国老","f":"古风","c":["五龙夹日日不沈。","公门桃李皆成林。","狄国老，伊周心。","迁桐辟管天下乂。","伊周之学春秋义。","狄国老，忠有馀。","平生曾读伊周书。","为唐讨贼当何如。","如是邪，不如是。","独怜国老身先死。"]},{"t":"鼌错墓","f":"五言古诗","c":["鼌公颍川产，墓在城东隅。","顾兹一抔土，尔来千载馀。","中更几兵戈，不与荒城俱。","公计不庇身，朝议夕就诛。","我昔读公传，亦尝笑其愚。","岂有身后谋，犹能庇邱墟。","大愚见深忠，耿耿固不渝。","而况公论在，信史有特书。","自今重封植，永久期无虞。"]},{"t":"八龙冢","f":"五言古诗","c":["北原有荒邱，累累亘西东。","相传自古昔，葬者汉八龙。","一蛰呼不起，幽幽閟玄宫。","适野见遗迹，徘徊仰高风。","于嗟此神物，时用乃不终。","孰为神君藏，孰为慈明封。","千秋气不泯，化为草丛丛。","立石当古道，我意将焉穷。"]},{"t":"尉氏妇","f":"楚辞体","c":["嗟汝妇，孝汝姑，三年庐墓声呜呜。","泪洒墓上柏，柏树为之枯。","彼反唇，此庐墓，此可讶兮彼可怒。","寸土如寸金，寸寸皆妇心。","取汝心，不取汝孝，天地之间有名教。"]},{"t":"送陈都宪赴南台","f":"五言古诗","c":["雄都镇南服，江流走其隈。","惊风鼓高浪，驾御须公才。","公船树双帜，令重御史台。","轻裘兀中坐，一鼓千艘开。","江灵戒百神，前驱步浮埃。","有陈既如云，有声复如雷。","见将不见水，颓波为之回。","周流有馀暇，独起吊古怀。","汉功陋昆明，天堑胡为哉。","巍巍皇祖业，万载恒规恢。","安危系所修，愿见封章来。"]},{"t":"题王晋溪画兰","f":"五言律诗","c":["之子有国香，幽居秘踪迹。","吾将一采之，荐之君王席。","英英雅淡姿，可写不可即。","珍重无奈何，黄金以为饰。"]},{"t":"望瀑布亦用李韵","f":"五言古诗","c":["昔闻地中山，今见天上水。","对日生虚明，光照数百里。","声将助雷行，势欲随云起。","矫矫白玉龙，人立烟霞里。","飞流何其雄，不受神禹功。","净洗下界浊，无言归太空。","精灵忽旁射，秀色溢厓壁。","动荡元化机，落星不为石。","观水复观山，万古心自閒。","愿借一泓清，鉴我尘外颜。","布邪可剪裁，衣被尽世间。"]},{"t":"湖口阻风书所见","f":"五言律诗","c":["湖西有青草，湖东有白石。","水与草有情，与石乃相激。","草边水微波，石也奈水何。","有石水不滥，不愿青草多。"]},{"t":"寄秦择之用莫如山韵","f":"五言古诗","c":["春江生绿芜，所思恨远别。","美人有新篇，开缄动风日。","商谣跂吴云，转使心旌孑。","谁能袪渴尘，惠我太古雪。","广文今冷官，五斗腰不折。","朝吟水洋洋，晚眺山嵲嵲。","君庭梧十寻，我方咏瓜瓞。","大哉唐虞谈，出口陋猥屑。","夕灯照虚堂，屡系康侯节。","填然鸣鼓中，乃独按鲁薛。","南沙旧同游，有操如玉洁。","赠君四三章，古调超巧拙。","岁寒结深盟，纷华以为瞥。","劝君勿太潜，行止故有说。","秋芳淡无姿，美在人未撷。","我歌亦吾情，不为闻者说。"]},{"t":"屯田二首寄胡用晦 其一","f":"五言古诗","c":["从军古云苦，况复远戍边。","强者乘障去，羸弱乃屯田。","恶土不生草，漠漠沙兼天。","犁锄亦病甚，幸免荷戈鋋。","但得烽火息，聊以延岁年。"]},{"t":"屯田二首寄胡用晦 其二","f":"五言古诗","c":["边塞少雨雪，岁丰亦如荒。","相逢莫相问，丰荒两无望。","荒岁固饥饿，一死足以当。","幸哉遇丰年，诛求益遑遑。","有生不如死，长恸天苍茫。"]},{"t":"赠王古直二首 其一","f":"五言古诗","c":["碌碌长安市，有客戴葛巾。","问之何为者，自言我山人。","山人本在山，偶然落风尘。","尚馀丘壑念，时向诗中陈。","暮作琳宫主，朝为玉堂宾。","兴到即成往，孰能疏与亲。","浩歌对尊酒，一醉全吾真。"]},{"t":"赠王古直二首 其二","f":"五言古诗","c":["栖栖复栖栖，而谓古遗直。","曾从西曹游，冒禁为所识。","长揖称诗人，法吏不敢斥。","泡灯亦儿戏，破碎何足惜。","西堂坐春风，凄凉泪沾臆。","兹事久已传，野史谁当职。"]},{"t":"疏山寺","f":"五言古诗","c":["我来访疏山，幽赏酬夙昔。","秋风吹新波，系舟岩下石。","吊古诵其诗，手拂苍藓壁。","游云相徘徊，去地不盈尺。","清歌复清梦，聊以终此夕。"]},{"t":"高安县学观习冠礼柬守巡二王君","f":"七言古诗","c":["洪州江涛激堤急，江中老蛟似人立。","春来风雨助江灵，万丈新堤无芥力。","谁将神物障狂流，铁柱宫成几百秋。","番阳湖深东入海，空厓禹庙何悠悠。","筠州有蛟今有柱，山雾如江化为雨。","弦歌在泮修旧章，允矣嘉宾吾愧主。"]},{"t":"朱仙镇","f":"古风","c":["绣旗扬扬出朱仙，中原王气熄更然。","敌军万骑鸣归鞭，故宫遗庙在眼前，奈何忽有金牌宣。","金牌宣，事甚迫。","将之南，将之北，南为吾君北社稷。","敢言君重社稷轻，彼奸在侧方经营。","社稷无功君有罪，到头两事恶乎成。","岳将军，决南行。","南行即就死，死不愧臣子。"]},{"t":"东山公书来问久无书舟中作书怅然有感","f":"五言古诗","c":["不上山翁书，非懒亦非傲。","知我者谓谁，而不能一报。","平生观物心，未得从吾好。","世途渺江湖，执简靡所告。","章水东北流，秋日波浩浩。","惟有匡庐峰，万变犹古貌。","吾将作新图，用为识者道。"]},{"t":"送王朝言","f":"五言古诗","c":["朝言天下士，乃作西江行。","把酒酹岐路，清风引双旌。","尊前即万里，动我淮阳情。","淮阳岂可薄，所志在汉庭。","君去江湖重，君留江湖轻。","君行何所挟，岱岳云英英。","远浮洞庭白，高点匡庐青。","谁知造化意，藉此方经营。","归欤作霖雨，四海多苍生。"]},{"t":"赤壁图为王冬官题","f":"七言古诗","c":["古之达者苏黄州，览尽赤壁无馀秋。","至今赋在景亦在，诵者如与公同舟。","公舟凌空与物游，东山月出水漫流。","清风徐来酒在手，羽人何处仍丹邱。","曹吴胜负江山羞，洞箫一声生远愁。","眼前水月客知否，一笑自点仙翁头。","水曹年来作浙游，苏堤风景应全收。","却望美人图画里，蒹葭霜满湖南洲。"]},{"t":"哭李方伯惟诚用老杜哀李北海韵","f":"五言古诗","c":["朋游三十年，道谊曾不替。","知公定交初，德音日相继。","公本西平胄，水木有源柢。","少年擅才名，文词出新制。","上书排帝阍，此志一何锐。","门停长者车，青眼风尘际。","仰窥古作者，流衍得真裔。","主司跃然惊，擢桂亦常例。","献策回重瞳，一朝荷嘉惠。","轩昂露头角，清光映宸卫。","寻常笑语间，历历邦家计。","力深稽古馀，致远未尝泥。","大哉养材功，不负文明世。","钟镛悬华轩，圭璧藉文罽。","令弟共翱翔，科重甲辰岁。","发轫铨曹郎，优游养经济。","登俊拔芳翘，黜邪洗荒秽。","公馀日扃门，惟有庭鹤唳。","读礼归故山，三年泪盈袂。","夏官故本兵，独立谢权嬖。","三边诸将臣，始得重轻势。","公心如青天，风月动光霁。","挥毫寓军法，烟云乱行缀。","奉使历南邦，爽气消瘴疠。","西藩领参伯，简在荷先帝。","公初度函关，在在减征税。","向来暴如焚，屏若扫以彗。","所不活群生，臣也誓有毙。","人情甚苦荼，而我独深哜。","移旌向浙江，山水心夙契。","相逢我知心，欢颜照堂砌。","冉冉山云浮，滔滔海波逝。","倡和吊忠魂，情真句还丽。","恶风从北来，群芳不胜脆。","万怪歘呈露，共讶天地闭。","公时居左辖，只手披蒙翳。","抗冲等铁石，调剂参姜桂。","哭声动九关，天乎竟迢递。","力穷叫苍梧，重华久云瘗。","飘然得赋归，冰霜日凌厉。","乾坤浩茫茫，吾道真成滞。","讣音隔三秋，乃复自燕蓟。","日斜望芜汀，些罢愁云蔽。"]},{"t":"萍乡虎","f":"古风","c":["萍乡山中虎，食畜不食人。","人亦感虎意，罟阱不复陈。","虎乃有俗俗有仁，不啻古云父子亲。","姚源洞，华林山。","有人杀人如草菅，吏见野人应厚颜。"]},{"t":"听雨歌读见素所上封事作","f":"七言古诗","c":["章江门下春水来，黄流浑浑无津涯。","居人争言二月八，水神作会多风雷。","拥衾听雨坐中夜，我船明发开未开。","湿云十里接南浦，滕王高阁空崔嵬。","我歌欲登江上台，吁嗟行路真难哉。","莆阳谏草忽在眼，歌声入江江欲回，君看铁柱生莓苔。"]},{"t":"建昌分司古松","f":"五言律诗","c":["古松当中庭，荒馆幸有此。","微风亦秋涛，雨翠复烟紫。","月来夜如何，对我阅文史。","我爱巡行初，见汝见君子。"]},{"t":"拟谒李旴江祠","f":"五言古诗","c":["旴江傍群山，何处李公墓。","城西深树林，宛转通细路。","秋雨漫如丝，沾湿兼瘴雾。","缅怀千载人，乃独缺瞻顾。","惟公力古学，虞周在襟度。","平生抱遗经，芜径倏超惊。","周行日千里，不识草多露。","典谟二三语，一笔万蛟负。","横亘天地间，精光破昏暮。","大哉忠孝词，居然见公素。","宝也晚且愚，焉能踵高步。","耿耿结中怀，所向惟恐误。","何当洁芳尊，再拜酬夙慕。"]},{"t":"宜黄秋日用韩韵","f":"五言古诗","c":["不雨已数日，萧萧叶声乾。","青青独可爱，庭下群琅玕。","阴云何处来，与雾昼作团。","驱瘴无妙术，只在心气安。","古井湛止水，安从起波澜。","焚香坐数息，日月通泥丸。","江浅舟可放，喜谢山中鞍。"]},{"t":"别罗太史景鸣用东坡韵","f":"七言古诗","c":["秋雨湿地无尘沙，萧然薄暮居官衙。","人言此郡有岚瘴，八月桂树初开花。","欲行未行待天霁，取道特过山人家。","山人如鹤心万里，争林每笑群栖鸦。","我昔对语尽长夜，别后四见春林葩。","人间万事似泉水，谁哉鸿渐能尝茶。","台前舞剑聊一试，楼上更鼓方三挝。","悬河之论透骨爽，背痒安用麻姑爬。","明朝分手各大笑，寻常为别何云嗟。","赠君此曲当琼佩，报我万斛仙坛霞。"]},{"t":"李车驾行","f":"古风","c":["李车驾，奉玺书，西行入关到边隅。","驾言数马阅牧地，要穷利病实与虚。","有疏驰达承明庐，镇将不敢沮，藩吏不敢拘，揽辔四顾意有馀。","李车驾，中州豪。","读书万卷志当世，排云阊阖曾鸣号。","奈何落落不谐俗，不为台谏为郎曹。","朝回闭阁日静坐，簿领之外更有经济为心劳。","李车驾，才瑚琏，声球琳。","大司马，知君深，千钧重任他日须君任。","等閒一使亦易事，中有至意试君以百年未断之盘错，历君以万里未极之岩嵚。","登台长啸望西北，秦城莽莽汉关磊磊吊古还思今。","挥君贾生涕，动君杜甫吟。","收罗胜槩入胸臆，不数双璧千黄金。","李车驾，须早返。","落花如云春色晚，风光去人不可挽。","宗社万年计，庙堂四海忧。","车驾，车驾，何以为今谋。"]},{"t":"梦希翁","f":"七言古诗","c":["云顶仙人入我梦，玉台之冠杖青藜。","不知此地是何所，山水满坐风披披。","仙人命予歌古诗，把酒向天天听之。","平生意气重韩孟，壮大何以酬相知。","仙人仙人今茹芝，清时吏隐非予谁。","春秋经世二三策，化作水上沧浪词。","沧浪清浊两言足，仙人一笑天无涯。","笑声到耳惊梦破，惟见寒月悬松枝。"]},{"t":"理发见白有感","f":"五言古诗","c":["日来栉我发，渐觉白者多。","世事非我力，我忧欲如何。","我齿邻半百，光阴逝江河。","老至不自觉，自谓心无他。","我心但不改，不妨发皤皤。"]},{"t":"次吴匏翁谢冯廷伯送惠泉韵","f":"五言古诗","c":["我爱冯龙厓，视山如画屏。","视泉复如酒，有量元泓渟。","竹炉效僧海，一煮尽一瓶。","朝朝亦暮暮，相对双眼青。","细酌入肺腑，洒然涤膻腥。","北燕又南粤，观水记所经。","惠通万里外，不似渭属泾。","昔人作水记，高调声泠泠。","水行大地中，有穴无人铭。","君行一尝饮，却忆漪澜亭。","梁溪带蓉湖，飘然昼扬舲。","痛饮三百杯，醉向泉头停。","携垆试煎法，如酿新春醽。","饮罢更须汲，一童负双瓴。","回视世间物，洪波泛轻莛。","高情漫为戏，题诗谢园丁。","夕斋待明月，禅灯坐青荧。","试诵卢仝歌，山僧或来听。","竹枝弄云影，松花递风馨。","石床独高卧，月上人初醒。","尝闻黄河源，有海名为星。","于江复于海，一泻不计龄。","悟泉未为悟，惺泉未为惺。","烦君奠山堂，陆羽故有灵。"]},{"t":"送彭佥宪还莆田","f":"楚辞体","c":["壶公山南南海滨，山中人兮尧舜民。","淮南有招招不得，桂树丛丛秋复春。","壶山主人大隐者，缄书远致南峰下。","丹厓青壁勿自誇，我有幽怀为君写。","我招不是淮南招，考槃同赋还同谣。","避人避地两无谓，白云杳杳壶山高。","昔居郎曹更宪府，理是渔纶断樵斧。","十年吏隐人不知，却道渔樵自今伍。","掉头巢父入海东，冥鸿万里商颜翁。","何如兹山倚南极，中深可著神仙宫。","七人作者莫知氏，为溺为沮竟谁是。","能从吾游吾与之，坐共閒鸥看川逝。"]},{"t":"和陈玉溪得古刀歌","f":"七言古诗","c":["玉溪老人鬓雪色，平生气薄秋空碧。","严冬遗我古刀歌，白日无风寒慄慄。","公从何处得此刀，而我未见难论直。","向来沦落未逢人，有时隐跃光腾日。","一朝白璧落公手，堪笑当时卞和泣。","乾坤万物递升沈，今古千年超恍惚。","也知刚德本天成，等閒未肯为人役。","西戎北虏不足诛，豺狼在道那容息。","由来神物不自用，义士兼资机与力。","昔年我亦得一镜，篆刻摩挲汉遗迹。","愿将此镜配公刀，共保刚明勿戕贼。"]},{"t":"读杨君谦和雪诗次韵寄之","f":"七言古诗","c":["秃豪一扫繁枝叶，咏雪诗成淡于雪。","眼中作者吾君谦，后出辞高意尤绝。","直追坡老千载上，我辈不觉腰罄折。","看君风槩有如此，当知此制难磨灭。","愧我浅薄曾效颦，把笔对君如或掣。","便欲索君书一通，大卷珍藏饰文缬。","文章所贵自己出，下此纷纷徒琐屑。","浑然元气未雕凿，言外风神亦飞瞥。","知言未敢轻自许，和篇聊致评诗说。","他年大作禆雅颂，磨有贞珉镌有铁。"]},{"t":"寄王推府","f":"五言古诗","c":["王郎关西彦，今为苏郡推。","忆昔骑瘦马，送我黄金台。","寄言问江东，谢公安在哉。","感此不能对，惭愧经济才。","坐驰楚云尽，望极吴天回。","遗君尺素书，珍重烦君裁。"]},{"t":"答尹吉士","f":"五言古诗","c":["斋居坐薄暮，西阳照墙东。","垂帘绝宾客，树影何丛丛。","尹生偶入室，依然故相从。","数语勤请益，令人契深衷。","妙龄志尚友，文翰岂徒工。","远游出彭蠡，浩思偕溟濛。","登廷列周士，所得良己丰。","弦琴谢俗调，三叹歌虞风。","大哉经世业，乾坤与无穷。","吾衰负吾道，俯仰增愧容。","安能挽星汉，一洗兵戈空。"]},{"t":"闻贺黄门讣","f":"五言古诗","c":["平生慕斯人，室远不可即。","海云日悠悠，医闾几千亿。","岁晚抚孤松，山居正幽寂。","百章对秋旻，耿耿梦畴昔。","清时乃遗贤，风教与有力。","往因范长史，问我书咫尺。","好风从东来，新诗寄相忆。","迩来十年馀，长空断飞翼。","哀昔忽予闻，独坐风雨夕。","白沙久亡矣，而公复窀穸。","北南两茫然，乾坤浩无极。","短词托高侯，歌残泪沾臆。"]},{"t":"都昌谒陶桓公祠","f":"五言古诗","c":["我航东汇泽，来拜陶公祠。","英灵邈千古，犹系吾人思。","公才不世出，幼学多师资。","时衰领重镇，光辉动旌旗。","大哉砥柱力，江汉如潢池。","公生清谈后，惟勤禹为师。","运甓投博具，举措非徒为。","道积业可大，所志在济时。","挥霍掣雷电，呼吸飞云霓。","公在国与立，桓文下风斯。","进退自明正，陋者徒生疑。","孙曾志公志，痛恨晋祚移。","一辞谢世事，采菊忘东篱。","公心愈表表，后哲谅有知。","鄱湖水浩渺，公神亦随之。","醴牲岁复岁，乾坤以为期。"]},{"t":"发都昌","f":"七言古诗","c":["彭蠡古来称险绝，其间左蠡尤滕说。","两山对峙舟中行，白浪乘风昼翻雪。","都昌枯坐三日来，一日东风帆早开。","匡庐云外露轻碧，水如新镜无尘埃。","苍烟茫茫隔重浦，风力催帆更双橹。","行行指点落星湾，宛在中央手堪拊。","南康太守送我船，船头忽见瀑布泉。","飞流未便解肺渴，自觉清兴同神仙。","我今西南访黄鹤，一水之间望官阁。","棹歌起处天风长，行尽澄湖帆未落。"]},{"t":"开先僧送泉水","f":"七言古诗","c":["泉斋爱泉如爱玉，每向名山观未足。","长言世味无此真，俗客浪誇鱼我欲。","匡庐瀑布故有名，几回坐饮龙池清。","不知泉亦我知否，我独与泉如结盟。","兹行未暇登山寺，远汲双瓶解焦思。","老僧闻我送茶来，笑揖山灵谢珍赐。","剩携阳羡新春芽，夜烹落尽青灯花。","吾泉在惠久能味，岂以异好成遗遐。","相将一椀复一椀，此味天教吾辈管。","明朝西望双虹垂，放笔大书湖水满。"]},{"t":"为黄公献题和靖咏梅图","f":"七言古诗","c":["江梅万树万树春，水边一株偏可人。","山人观物著妙语，云月惨淡愁花神。","诗中香影本无色，宛然眼界翻成真。","谁今以色写香影，山人含笑花应嗔。","山人山人久寥落，风韵犹存松与鹤。"]},{"t":"竹鹤图歌","f":"楚辞体","c":["国之元老太原公，立朝鲠鲠持清忠。","作堂晋水近十载，但见歌颂传儿童。","祝公何言再入相，更期寿在乔松上。","东风吹嘘遍八埏，乾坤无言物有象。","绿竹猗猗鸟鹤鹤，石岩岩兮松落落。","众禽鸣树山起云，千花万花色相错。","苑马南来西入秦，献图称寿意独真。","惟天佑德辅皇极，岁寒贞操公其人。","宝也公门旧游者，有怀如画无能写。","愿公自寿寿苍生，士庆在朝农在野。"]},{"t":"为李惟诚题画","f":"五言古诗","c":["江边草亭好，兴在江上山。","山留万古色，白云时往还。","云来荡胸臆，云去开姿颜。","云哉或出岫，化为水潺潺。","观云复观水，有道心自閒。","策杖者何人，行将坐其间。","我怀李芜湖，欲谢功名关。"]},{"t":"别王演之","f":"五言古诗","c":["驱马出国门，风动晨光绚。","我怀方南驰，北望逾眷恋。","之子何所来，昨别今再面。","嘱予彊加餐，执手当觞饯。","驾言询江东，畴应谢公选。","微词不自竟，舆诵若为献。","离筵纷陆离，宾客催入燕。","举首复叮咛，上马君乃先。","君言良过哉，相思泪如线。","经纶予何知，浮云未成变。"]},{"t":"与王德华别","f":"五言古诗","c":["初辞浑河津，轻舟疾如驾。","相逢忽相问，兹会乃天假。","去来各匆匆，聊此半日暇。","对君新凉馀，王事深慰藉。","东藩税方逋，北徼师未罢。","悠哉远臣心，焦劳达晨夜。","谓予汝何言，予有再拜谢。","依依复依依，孤舟竟东下。"]},{"t":"孙翊妻","f":"古风","c":["夫死矣妾何敢生。","夫雠为重身为轻。","贼尚生妾何敢死。","旧门幸有诸君子。","号召如风赴如水。","奉贼头，祭夫墓。","白日下高天，何处黄泉路。"]},{"t":"次乔考功种竹","f":"五言古诗","c":["考功忆南曹，新竹旧所艺。","岁寒凡两经，不见霜雪厉。","虚怀效前修，浅薄谅非计。","斐然淇水涯，千秋一根柢。","独立良可嘉，群居亦何戾。","体疑墨君诬，用笑楮生敝。","城中地如金，省庭更难诣。","植之固由人，长养荷天惠。","醴酒散馀酣，医俗得妙剂。","等閒供听观，淡中有真丽。","风清玉声流，月暗金影翳。","结实虽未成，凤鸟或来憩。","主人道眼明，许与松齐岁。","岂无一视心，馀卉直柔脆。","我将节下题，相过及春霁。"]},{"t":"次孙司勋种松","f":"五言古诗","c":["观树如观民，岂不试故艺。","勋曹庭中松，植难果谁厉。","公为百年谋，乃徇一朝计。","知乎向来非，勤搔动浮柢。","揠苗信轲书，免归僮仆戾。","元气天地间，万木未尝敝。","吾心有妙机，到此深造诣。","况当春雨时，点点荷嘉惠。","一培一灌之，缓急在调剂。","新梢隐孤高，短叶露修丽。","虽无虬龙姿，白日弄阴翳。","主人退自公，往往成小憩。","奇哉拔地材，卓尔倚天势。","作诗告方来，植也自兹岁。","桃李正芳华，何心较坚脆。","请公看岁寒，雪馀晚峰霁。"]},{"t":"宿池江 其一","f":"五言律诗","c":["秋热大可畏，舟行乘微风。","岂不爱燕息，兴在临川东。","晚泊择所止，碧水连遥空。","沙鸥解人意，来往如相从。"]},{"t":"宿池江 其二","f":"五言律诗","c":["放船泊中洲，不住亦不流。","爱风当南港，畏日背西邱。","浩歌待明月，解带倚柁楼。","水花向我笑，我意方悠悠。"]},{"t":"风雩台","f":"五言律诗","c":["危厓接云雨，不雩自成坛。","偶从沂上游，振衣复弹冠。","晚风西南来，五老生高寒。","吾襟对阳春，浩然天宇宽。"]},{"t":"鹿洞","f":"五言律诗","c":["山人与鹿游，乃以鹿名洞。","洞草春复春，人与物情共。","呦呦诗有之，作者非好弄。","偶名亦佳哉，千古兴弦诵。"]},{"t":"奉寄东山公 其一","f":"五言律诗","c":["不见东山公，已历两冰雪。","江远天与俱，山深地尤绝。","吾道付閒云，苍生望终觖。","月明千里心，相望独纠结。"]},{"t":"奉寄东山公 其二","f":"五言律诗","c":["巴陵胜槩地，岳阳天下奇。","公昔游且钓，今归几登之。","惊波感世路，江湖渺无期。","再读希文记，千古长相思。"]},{"t":"灵济宫即席赋白岩","f":"五言古诗","c":["孤峰何处所，屹立太行东。","耸拔群厓异，苍茫四望同。","润疑连析木，高欲跨崆峒。","绘妙初施处，锋神未露中。","远堪回俗驾，清许筑仙宫。","灵秀从何代，风流到此公。","无劳成独迈，不饰见真工。","点缀长凝雪，跻攀合驭风。","一元开混沌，万仞倚虚空。","夜共星辰烂，春分雨露濛。","凭谁磨藓壁，为我扫榛丛。","明日西回首，秋云渺去鸿。"]},{"t":"闻宪宗皇帝遗诏","f":"五言律诗","c":["帝德难思拟，天高后土深。","惊闻八月诏，哀裂万邦心。","慈壸虚文膳，明堂辍舜琴。","扣头瞻北极，清泪满衣襟。"]},{"t":"昭明太子读书台","f":"五言律诗","c":["江左风流在，前梁复后唐。","壁分新竹色，台散旧芸香。","迹与仙风远，名随佛日长。","澄湖回首地，云水一茫茫。"]},{"t":"赠李参政士清","f":"五言律诗","c":["两世交承旧，三年晤语新。","艰危临塞日，勤苦报君身。","藩省衔初大，丘园业尚贫。","公心元似水，何处见缁尘。"]},{"t":"春野卷","f":"五言律诗","c":["白洲千载笔，春野百年心。","云白山无际，草青江有浔。","杖藜乘晚霁，鼓瑟散寒阴。","人去遗书在，悠然怀古今。"]},{"t":"望龟峰","f":"五言律诗","c":["望里龟峰寺，幽寻路可穷。","风尘四壁外，天日一方中。","水曲真疑断，云盈不碍空。","往来题未了，独立叹神功。"]},{"t":"醴陵靖兴寺","f":"五言律诗","c":["古寺渌江畔，僧閒喜客来。","殿堂分宝界，钟磬落瑶台。","兴远云俱定，情多雨未回。","旧庭元有树，若为老夫栽。"]},{"t":"湘东道中括杜句二首 其一","f":"五言律诗","c":["江汉风流在，坐来春水船。","蚤闻黄阁画，晴检白云篇。","节上风尘际，司存雨露边。","朝班几回点，奔走已三年。"]},{"t":"湘东道中括杜句二首 其二","f":"五言律诗","c":["浦雷喧昨夜，瀼滑限西东。","径筱含风净，林花著雨红。","短墙残草里，高叶乱帆中。","长路关心在，潇湘虚映空。"]},{"t":"送郑刑部汝华","f":"五言律诗","c":["郑君瑚琏器，瘦马亦随行。","秋晚天涯别，山多溪水长。","眼应空冀野，泪欲洒泷冈。","直北须回首，郎星帝座傍。"]},{"t":"送僧圆显住慧山寺","f":"五言律诗","c":["寺据诸山会，公因一檄来。","梦惊松阁雨，归扫石床苔。","得主怜西社，遗书吊北台。","野云心迹在，古洞傍泉开。"]},{"t":"舟中和唐诗五首 其一 游少林寺","f":"五言律诗","c":["西出登封县，来寻古少林。","幢开青嶂近，钟隐白云深。","雨积溪初霁，峰遮日早阴。","长廊诗刻满，拂拭倩僧吟。"]},{"t":"舟中和唐诗五首 其二 晚至华阴","f":"五言律诗","c":["西瞻自夙心，歇马向山阴。","玉井连云远，金茎入露深。","半峰留夕照，万籁起秋林。","往事今何在，温泉未陆沈。"]},{"t":"舟中和唐诗五首 其三 岳阳晚景","f":"五言律诗","c":["木下秋风起，青山送雨归。","日低真见落，云远不知飞。","江色烟中淡，鸿鸣渚外稀。","倚阑情未极，寒气湿人衣。"]},{"t":"舟中和唐诗五首 其四 经废宝庆寺","f":"五言律诗","c":["山中留古寺，门对夕阳开。","苓露松春长，鸦风鹤夜回。","佛龛尘伏鼠，僧榻雨封苔。","解得真空意，荒凉未足哀。"]},{"t":"舟中和唐诗五首 其五 晚发五溪","f":"五言律诗","c":["晚鼓溪船发，秋风动楚天。","月生洲杜外，烟起渚鸥边。","野艇横村渡，农蓑散水田。","夜凉何处宿，远思正相牵。"]},{"t":"示吴宪","f":"五言律诗","c":["宪也来还去，离怀奈尔何。","雨添双涧满，云隔九峰多。","趋鲤承韦训，迁莺和木歌。","源泉才一勺，江海有馀波。"]},{"t":"哭李徵伯三首 其一","f":"五言律诗","c":["安得惊心语，疑真幸未真。","谁能知我意，天乃夺斯人。","京国同游地，江湖独坐身。","更堪风雨夜，愁绝欲沾巾。"]},{"t":"哭李徵伯三首 其二","f":"五言律诗","c":["信也还非信，东来近有书。","病怜秋省误，吟想夜斋虚。","标格风尘外，珠玑咳唾馀。","不须论旧事，泪满故人裾。"]},{"t":"哭李徵伯三首 其三","f":"五言律诗","c":["多情如子少，忍弃白头亲。","晚节吾方爱，中峰孰与邻。","月仍留客夜，风亦散朝晨。","欲慰无由往，空然北望频。"]},{"t":"苏门山","f":"五言律诗","c":["万古苏门胜，乘閒一览之。","秋逢收潦后，泉看出山时。","湿气生清润，晴光动碧漪。","坐来心与湛，昏黑忘归迟。"]},{"t":"挽秦封君","f":"五言律诗","c":["寥落湖山晚，伊人谢草堂。","子迟封尚蚤，身隐道逾光。","杖老曾于国，祠贤合在乡。","未能从吊客，东望意何长。"]},{"t":"再至东海祠","f":"五言律诗","c":["东海祠何处，兹山旧所游。","带缘禅语舍，衣为旅情留。","鸟弄峰云定，花开涧水流。","凭人订遗像，还似此翁不。"]},{"t":"宿池江","f":"五言律诗","c":["水落沙新白，蝉鸣叶半黄。","郁蒸仍午焰，淡荡自秋光。","梦就书应掷，吟馀牍未妨。","晚风生别渚，起坐听沧浪。"]},{"t":"九江赠冯户部用见素韵","f":"五言律诗","c":["五载三曹彦，登楼感旧游。","帆阴连水岸，帘爽带云邱。","院静风生鹤，城春雨应鸠。","明朝有尊酒，还拟为君留。"]},{"t":"送人","f":"五言律诗","c":["解摈不足作，江上悲蚤秋。","文非今日贽，道有古人谋。","井恻泉初渫，洋望潦已收。","千年陈榻后，为我吊南州。"]},{"t":"挽姚提学秀夫","f":"五言律诗","c":["经济平生志，江湖远奈何。","惠留吴地志，哀起楚人歌。","卜筑溪边小，交游海内多。","吊君追赋鵩，愁绝洞庭波。"]},{"t":"上航夜泊","f":"五言律诗","c":["雪后过江驿，平沙水半篙。","我方甘老懒，谁复叹贤劳。","峰影云中淡，滩声月下高。","回思十年里，几度驻旌旄。"]},{"t":"将至邬子舟中作","f":"五言律诗","c":["咫尺鄱湖水，相将入楚乡。","雨中帆力缓，风外笛声长。","梦渴山泉茗，吟销海岛香。","旧游堪一憩，何处有甘棠。"]},{"t":"赠陈平江","f":"五言律诗","c":["南浦逢君处，相看各问津。","乘槎元有汉，怀璧故无秦。","带砺千年地，风波万里身。","东风淮水上，古庙不胜春。"]},{"t":"过严滩","f":"五言律诗","c":["独上客星亭，群峰雨外青。","公心如介石，吾道亦沧溟。","出处轻商楫，来归重汉庭。","渔歌朝又暮，云掩北山铭。"]},{"t":"女埠夜泊问章枫山","f":"五言律诗","c":["女埠芗溪上，幽居路不遥。","山风听夕濑，江雨问春潮。","清秩辞新命，华缄忆旧招。","何时拜床下，鄙吝为公消。"]},{"t":"秋野用杜韵二首 其二","f":"五言律诗","c":["亦知樵径窄，且放钓竿长。","夕籁成竽调，寒潭发镜光。","小桥当驿道，精舍近禅房。","十月春如许，疏梅几蕊香。"]},{"t":"答孙山人","f":"五言律诗","c":["湖海有此客，飘然何所投。","一瓢将水去，双屐为山留。","落落弥明鼎，茫茫太乙舟。","几时盛水石，古寺共寻幽。"]},{"t":"追挽蒋参议惟深","f":"五言律诗","c":["忆驻西藩节，观风几论心。","云收庐岳远，水入蠡湖深。","正气埋邱剑，馀音挂壁琴。","箕裘佳子在，相对一沾襟。"]},{"t":"读章恭毅年谱","f":"五言律诗","c":["国论非难定，惟应敢谏难。","一封心自白，九死泪如丹。","遗像凭谁问，新编许我看。","敢言容易拜，东向欲为坛。"]},{"t":"闻白沙先生讣二首 其一","f":"五言律诗","c":["不仕缘慈母，山林七十年。","识高翻似剧，语妙欲无禅。","未肯桴浮海，真将剑倚天。","沧波今夜月，空向白沙圆。"]},{"t":"闻白沙先生讣二首 其二","f":"五言律诗","c":["近读慈元记，知公用意深。","若非碑矗矗，空有树森森。","南海诸陵泪，东山十载心。","春秋遗策在，请听石翁吟。"]},{"t":"和盛汉臣二首 其一","f":"五言律诗","c":["数年王事里，奔走愧缨冠。","行止惟天在，弦歌敢自安。","云松看卧鹿，风竹听鸣鸾。","奉母馀春酒，须君罄一欢。"]},{"t":"和盛汉臣二首 其二","f":"五言律诗","c":["鹤老何年逝，遗音在士林。","诗中空见面，史外独传心。","风月襟怀远，湖山梦寐深。","愿君歌旧曲，吾谱入吾琴。"]},{"t":"泉上答平江用姚少师韵","f":"五言律诗","c":["未了登山兴，楼船冒雨开。","不须留带去，便拟赐环来。","宝剑时时拭，甘棠处处栽。","醉吟吾老矣，迟子有茶杯。"]},{"t":"慧山十贤堂成有作","f":"五言律诗","c":["万古名泉地，诸贤合有堂。","云龛藏旧影，水鉴发新光。","国史千钧笔，乡评一瓣香。","烦僧语游客，到此肃冠裳。"]},{"t":"麻姑山次万长史韵二首 其一","f":"五言律诗","c":["亭依青嶂曲，路出绿萝间。","泉听云中佩，峰看雾里鬟。","风烟初旷远，花鸟各幽閒。","落尽西林日，游人始拟还。"]},{"t":"麻姑山次万长史韵二首 其二","f":"五言律诗","c":["景与情俱胜，人归酒未阑。","舆分秋籁爽，桥倚晚淙寒。","石鼎诗中纪，兰亭画里看。","好山游欲遍，东望眼初宽。"]},{"t":"次许给事启衷九日感怀因以为赠二首 其一","f":"五言律诗","c":["南极开天诏，春来万物苏。","节随星动速，槎向海浮迂。","鲲运溟风翼，龙收渥水驹。","故园聊暂驻，松菊未曾芜。"]},{"t":"次许给事启衷九日感怀因以为赠二首 其二","f":"五言律诗","c":["贾涕频封疏，因诗复一号。","风尘人落落，江汉日滔滔。","径晚菊生色，庭秋鹤毨毛。","玉峰青琐外，何处赋登高。"]},{"t":"南安谒濂溪先生祠","f":"五言律诗","c":["一脉濂溪水，中涵太极天。","契符三圣后，冠冕四儒前。","庭谒初除草，峰寻几问莲。","略谙光霁在，有笔未能传。"]},{"t":"夜坐","f":"五言律诗","c":["听雨山中寺，萧条对佛灯。","春怀偏恼客，野兴未嫌僧。","雷似千峰动，泉应一夜增。","壮心方激烈，静坐欲飞腾。"]},{"t":"王敬止使朝鲜卷","f":"五言律诗","c":["玉树挺高标，绯袍敕度辽。","风传箕子国，星动汉官轺。","沈斥春回蚤，封疆晓望遥。","清名满东裔，疋马自还朝。"]},{"t":"徐文靖公挽词","f":"五言律诗","c":["公为苍生恸，私还哭所知。","名成归老日，功在荐贤时。","风采山中杖，文章海内碑。","向来参谒地，风动古槐枝。"]},{"t":"登白云阁待友不至","f":"五言律诗","c":["路左离亭北，幽寻兴亦多。","偶登仙阁坐，又听道童歌。","云远双峰出，林深一鸟过。","长吟无和者，奈此素秋何。"]},{"t":"秋溪卷","f":"五言律诗","c":["潢潦初收尽，寒泉走白沙。","云来疑雁影，雪舞爱芦花。","有客同书舫，何人独钓槎。","沧浪才两语，歌起水无涯。"]},{"t":"慧山寺次姚少师韵","f":"五言律诗","c":["十年酬远兴，秋晚寺门开。","山色空中落，泉声起处来。","草香寻异品，树老问初栽。","欲为茶神酹，还将酒一杯。"]},{"t":"闻西园叔讣","f":"五言律诗","c":["素守邱樊节，无书谒贵人。","占从閒处熟，吟到醉时真。","北渚鸿何晚，西园草又春。","正怀家国念，闻讣益沾巾。"]},{"t":"题观松卷","f":"五言律诗","c":["散步古松阴，清风吹满襟。","雨滋萝薜密，云隐茯苓深。","静对宁须臆，真知只在心。","寒岩梅竹畔，更许一相寻。"]},{"t":"赠毛渊之","f":"五言律诗","c":["寒风吹客衣，之子正东归。","云影连蓬岛，江光动少微。","天边栖凤沼，海上钓鱼矶。","折得梅花在，还将寄北扉。"]},{"t":"过龟山","f":"五言律诗","c":["渎庙龟山顶，长淮日夜东。","放船方海月，挂席更天风。","鬼物荒唐里，神功镇静中。","济川吾岂敢，斯道正无穷。"]},{"t":"答杨仪部","f":"五言律诗","c":["驱驰山水国，野兴入秋多。","佳处每十宿，浩然时一歌。","渡江乘月坐，题石带云磨。","为问南峰主，相逢谓我何。"]},{"t":"德兴思家","f":"五言律诗","c":["正是思家地，山中更雨中。","林明初得月，泉响半因风。","卧榻辰瞻北，巡车道指东。","慈闱无一字，何处问来鸿。"]},{"t":"访舒方伯本直","f":"五言律诗","c":["细雨深山路，高风勇退人。","骨同仙入相，心与道为邻。","白发霜馀少，丹崖眼底真。","归舟逐烟水，回首已迷津。"]},{"t":"次杨澹成新春感怀韵","f":"五言律诗","c":["喜雪还愁雪，人将谓我何。","不堪雷太蚤，况复雨兼多。","黄鸟声全涩，红梅色半酡。","凭谁吹古律，一笑转阳和。"]},{"t":"将赴许州奉别西涯先生","f":"五言律诗","c":["我有文章愿，公今海内师。","南畿叨荐日，东阁听谈时。","地重怜才甚，名高入相迟。","茫茫离与合，何以尽心期。"]},{"t":"送邹光大","f":"五言律诗","c":["分手金台下，东南望故乡。","春随三月尽，水入五湖长。","爱石焚香拜，评泉挟茗尝。","风光看不了，一一付奚囊。"]},{"t":"次韵寄陆兵侍","f":"五言律诗","c":["仗剑风尘地，皇言属汝为。","一书知胜算，三月定还期。","露檄晨驰遽，围棋夜卧迟。","凯歌催布谷，草绿雨丝丝。"]},{"t":"闻工侍徐公讣","f":"五言律诗","c":["千里闻公讣，悲深吊却难。","客衣新泪湿，宾馆旧盟寒。","南国兴居重，东门进退宽。","诔词书不尽，江水易为乾。"]},{"t":"过天津见新筑台","f":"五言律诗","c":["台起孤城外，风尘地有馀。","奔鲸惊筑观，飞鸟避储胥。","鸥白连渔浦，杨青引漕渠。","它年志兵卫，史笔定联书。"]},{"t":"过沧州","f":"五言律诗","c":["指点沧州路，秋来屡受攻。","一言符间法，数矢奏奇功。","败屋寒灰后，荒城野浸中。","鱼盐近何价，欲问海滨翁。"]},{"t":"德州","f":"五言律诗","c":["北路临流郡，南来奉使身。","将怜初领地，器问旧藏人。","独立金汤险，先登矢石亲。","盗平看出猎，春草四郊新。"]},{"t":"夜遇高县尹","f":"五言律诗","c":["独行寒夜清，惊乌时一鸣。","相逢即相别，翻使客愁生。","微论开新瘴，幽怀抱宿酲。","临分还致语，侧耳听贤声。"]},{"t":"清源别吴马二生","f":"五言律诗","c":["卫水西风急，将归客去时。","愁难禁下拜，苦不会成诗。","三月师应老，诸州盗未夷。","慈闱问消息，言喜莫言悲。"]},{"t":"二生临行得家信","f":"五言律诗","c":["正恨慈闱远，如何动笑颜。","一书三月至，千里两人还。","岁月它乡误，风尘此道艰。","何时拜家庆，春酒对云山。"]},{"t":"临清都府感旧","f":"五言律诗","c":["宪府荒城里，重门倚茂林。","壮怀天地阔，旧梦岁年深。","月幌思秋霁，风檐坐夕阴。","静中军国计，一日几经心。"]},{"t":"晚至临清","f":"五言律诗","c":["汶水穷诸闸，西来更卫川。","堤黄犹有柳，浸白已无莲。","驿骑冲残日，城鸦起宿烟。","时时闻盗警，烽火似三边。"]},{"t":"武城夜泊","f":"五言律诗","c":["日暮路堪愁，长河正北流。","风声城上柝，星影驿边舟。","贤宰怀前辈，儒官感旧游。","黎明促南发，漕卒正焦头。"]},{"t":"跃马泉","f":"五言律诗","c":["跃马泉何在，西岩洞北头。","无疆坤亦健，有本坎还流。","块历风争骤，空行雪避遒。","百年谁执御，江汉日悠悠。"]},{"t":"诸公以将石联句为赠次韵以答","f":"五言律诗","c":["泉已离山久，谁教冽且寒。","无形成砥柱，有价比琅玕。","重在移时试，清从激处看。","不妨江海上，风雨落花残。"]},{"t":"泉亭卷","f":"五言律诗","c":["此泉天下胜，公乃爱泉人。","吾道今犹古，空亭秋复春。","眼明曾作鉴，心渴几生尘。","最喜前川水，泠然却近真。"]},{"t":"答王进士演之","f":"五言律诗","c":["才短惭乡国，君胡问谢安。","自缘忧世切，谁谓识人难。","行卷诗俱漫，离杯酒独乾。","相思江汉外，回首朔云寒。"]},{"t":"匏翁东庄杂咏九首 其一 东城","f":"五言绝句","c":["有圃城东偏，石梁度幽径。","隐然见东城，不见东山胜。"]},{"t":"匏翁东庄杂咏九首 其二 竹田","f":"五言绝句","c":["楚云梦潇湘，卫水歌淇澳。","吴城有竹田，亦有人如玉。"]},{"t":"匏翁东庄杂咏九首 其三 南港","f":"五言绝句","c":["南渡通西湖，晚多渔艇宿。","人家深树中，青烟起茅屋。"]},{"t":"匏翁东庄杂咏九首 其四 桑洲","f":"五言绝句","c":["汲溪灌桑树，叶多蚕亦稠。","衣被尽天下，美哉真此洲。"]},{"t":"匏翁东庄杂咏九首 其五 全真馆","f":"五言绝句","c":["何处适馀兴，寻师谈道经。","隔桥云满屋，钟磬晚泠泠。"]},{"t":"匏翁东庄杂咏九首 其六 耕息轩","f":"五言绝句","c":["陇上阅耕罢，北窗清卧风。","豳诗读未了，梦已见周公。"]},{"t":"匏翁东庄杂咏九首 其七 鹤洞","f":"五言绝句","c":["老鹤爱云栖，石洞自天凿。","秋风时一声，飞云散寥廓。"]},{"t":"匏翁东庄杂咏九首 其八 朱樱径","f":"五言绝句","c":["叶间缀朱实，实落绿成阴。","一步还一摘，不知苔径深。"]},{"t":"匏翁东庄杂咏九首 其九 曲池","f":"五言绝句","c":["曲池如曲江，水清花可怜。","池上木芙蓉，红映池中莲。"]},{"t":"题画","f":"五言绝句","c":["日暮风雨恶，咫尺不可去。","危桥下马过，犹胜无桥处。"]},{"t":"湖上口占二首 其一","f":"五言绝句","c":["不到西湖上，于今二十年。","相逢多白发，山色只如前。"]},{"t":"湖上口占二首 其二","f":"五言绝句","c":["画船入西湖，风光正春暮。","指点两峰云，先寻岳王墓。"]},{"t":"松下作二首 其一","f":"五言绝句","c":["泉流古松下，松影流不去。","时方望云霓，谁留卧龙住。"]},{"t":"松下作二首 其二","f":"五言绝句","c":["孤笛横秋江，一声山月白。","芦花起天风，萧瑟溪南北。"]},{"t":"题画二首 其一","f":"五言绝句","c":["银河天上来，不复上天去。","千载乘槎人，应迷问津处。"]},{"t":"题画二首 其二","f":"五言绝句","c":["偶来坐松下，爱此流泉声。","云山隔遥浦，悠然空复情。"]},{"t":"春江曲","f":"五言绝句","c":["春色将归去，江南草正新。","南风亦何意，偏脑欲归人。"]},{"t":"有待","f":"五言绝句","c":["芳洲草青青，云水半吞吐。","前船已过湖，还听后船橹。"]},{"t":"寄吴嗣业","f":"五言绝句","c":["茶香邻酒国，知味各称仙。","何日携茶具，云山共我泉。"]},{"t":"题文徵明画","f":"五言绝句","c":["于画见书法，萧然无滞情。","君看片石畔，丛竹忽生生。"]},{"t":"雨过独坐","f":"五言绝句","c":["暑雨过不尽，斜阳穿湿云。","雷声近还远，隐隐隔江闻。"]},{"t":"为钱忠言题画","f":"五言绝句","c":["偶舣北来棹，淮阴听晚钟。","明朝渡江去，秋浦采芙蓉。"]},{"t":"和溪为程进士赋","f":"五言绝句","c":["家住万山中，云峰翠几重。","东山朝日出，望见海霞红。"]},{"t":"不寐","f":"五言律诗","c":["清风何飘飖，左盻澄江湘。","天高万物肃，松柏郁芒芒。","通波激柱渚，大道夷且长。","愿为双鸣鹤，施翮起高翔。"]},{"t":"遇王参政汝言","f":"五言古诗","c":["兰泽多芳草，引领遥相晞。","河汉清且浅，愁思当告谁。","我有一尊酒，客从远方来。","临河濯长缨，乐饮不知疲。","努力崇明德，馀光照我衣。"]},{"t":"述怀","f":"五言律诗","c":["东园桃与李，白日忽蹉跎。","左右佩双璜，徙倚引芳柯。","寒衣欲谁待，春风扇微和。","齐心同所愿，结根太山阿。"]},{"t":"有所思","f":"五言律诗","c":["兰荣一何晚，向风长叹息。","褰裳欲从之，磷磷水中石。","西游咸阳中，入道逢深识。","驾鸿乘紫烟，高举振六翮。"]},{"t":"闻时事有感集李四首 其一","f":"五言律诗","c":["松柏本孤直，翠绿如芙蓉。","独立自萧飋，楚山邈千重。","安知天汉上，乘云驾轻鸿。","沈叹终永夕，世无洗耳翁。"]},{"t":"闻时事有感集李四首 其二","f":"五言律诗","c":["吾衰竟谁陈，焉得偶君子。","倚楼青云端，千春隔江水。","大雅思文王，行行未能已。","鸑鷟有时鸣，雄断自天启。"]},{"t":"闻时事有感集李四首 其三","f":"五言律诗","c":["长鲸正崔嵬，世路有屈曲。","自挟两青龙，挥手折若木。","沿芳剧春洲，凤饥不啄粟。","楼船几时回，秋露白如玉。"]},{"t":"闻时事有感集李四首 其四","f":"五言律诗","c":["明月出海底，回风送天声。","宝剑双蛟龙，虚步蹑太清。","云卧游八极，三公运权衡。","努力保霜雪，群才属休明。"]},{"t":"舟中怀李方伯惟诚集杜二绝 其一","f":"五言绝句","c":["老去才难尽，秋天忆射雕。","白鸥波浩荡，寒水不成潮。"]},{"t":"舟中怀李方伯惟诚集杜二绝 其二","f":"五言绝句","c":["海内知名士，如公复几人。","千秋一拭泪，鼓柂视青旻。"]},{"t":"赐大明会典","f":"七言律诗","c":["缃函新捧出天衢，十载文光照石渠。","唐作一经徒托语，周遗六典始成书。","圣神功化三才里，今昔经纶万卷馀。","遐想先皇初诏日，洞观千古欲何如。"]},{"t":"醴陵旋节","f":"七言律诗","c":["三月湘东应召还，君恩免过万重山。","正缘岐路生愁思，总为庭闱动笑颜。","云与新篇封石壁，风随旧节度江关。","百年报答知何地，只在丹心一寸间。"]},{"t":"歌风台","f":"七言律诗","c":["欲上高台水漫波，向来遗恨付长河。","雄图自谓千年少，猛士犹嫌一语多。","白日无端江草合，赤龙何在野云过。","登临更作它时约，却向中流听棹歌。"]},{"t":"苦雨","f":"七言律诗","c":["江寒五月拥重衾，雨滴空阶夜夜深。","无地诛求贫到骨，有人恸哭苦关心。","百川何处堪回砥，三日它年本作霖。","坐对青灯头欲白，敢言吾道在山林。"]},{"t":"拟游慈恩寺用涯翁韵","f":"七言律诗","c":["春残才作探春行，古寺寻僧懒问名。","近海景多频立马，对花情剧更闻莺。","镜湖敢乞君分赐，宝地偏教佛主盟。","却忆江南如画里，万峰青接水边城。"]},{"t":"谒文信国祠","f":"七言律诗","c":["春色无端满地莎，伤心燕市偶经过。","清风又读忠臣传，白日如闻正气歌。","社稷一身惟死是，纲常千古有功多。","瓣香未了平生拜，回首荒祠独奈何。"]},{"t":"答钱户部世恩","f":"七言律诗","c":["梅村东去问前津，自折梅花欲赠人。","别恨却寻何处在，寄声翻笑向来频。","鱼龙漫拟秋为夜，草木先知地有春。","莫向尊前论出处，綵衣公亦赐归臣。"]},{"t":"闻秦修敬讣","f":"七言律诗","c":["太守官封处士名，十年诗社忽凋零。","伤心忍读苏洵传，好事争誇许劭评。","下榻独怀它夜永，濯缨谁爱此泉清。","故山回首相从地，一曲哀歌万古情。"]},{"t":"陆宫詹廉伯挽词","f":"七言律诗","c":["谩为斯文叹寂寥，长安谁赋楚人招。","江山奇气还千古，台阁清衔在两朝。","门刺有名尘榻静，院灯无梦玉堂遥。","西风落日铭旌短，回首乡园恨未消。"]},{"t":"李絅庵渠南一老亭","f":"七言律诗","c":["诗名晚岁满江南，却向渠南小结庵。","尘起污人聊作界，客来看竹亦容参。","迹如盘谷还嫌僻，计似菟裘已绝贪。","不用丹青写行乐，白头临水影涵涵。"]},{"t":"通州遇老母生日","f":"七言律诗","c":["去岁兹辰正在家，笑倾春酒对梅花。","日长自计还千算，地远谁教各一涯。","天上鸾书重雨露，山中萱室自烟霞。","凭谁为报真消息，己谢秋风奉使槎。"]},{"t":"少师公祈雪斋居代启奉问辛未","f":"七言律诗","c":["白头灯火玉堂深，三叹朱弦对古琴。","庭鹤梦清知夜气，江梅花蚤见天心。","日将南至迎修景，风自东来问捷音。","咫尺门墙劳跂望，五云城阙漏沈沈。"]},{"t":"馀干寄秦择之","f":"七言律诗","c":["别君风雨便随舟，刚得山亭半日留。","乱草没泥还宿鹭，密云笼树更鸣鸠。","山中一馆邻僧寺，沙际诸生杂吏邮。","惭愧旧游无可道，湖船连夜发饶州。"]},{"t":"题显公房寓泉窝","f":"七言律诗","c":["满道清阴绿树遮，肩舆坐我胜乘车。","僧头似雪逢应晚，山价如金欲敢奢。","一榻此堂真有否，百年吾道果非邪。","不须更索行窝记，击壤歌中日未斜。"]},{"t":"答杨杭州","f":"七言律诗","c":["京兆重分郡守符，春风花鸟动西湖。","邺侯功远千年有，坡老情閒一事无。","益下真成军国计，虚中元出庙堂谟。","还朝请画东南水，不但流民可献图。"]},{"t":"僧圆显请记行窝以诗答之","f":"七言律诗","c":["随意云山放我歌，不须文字记行窝。","梦回赤壁月还小，濯罢沧浪水更多。","静定故知禅榻在，虚明今谓佛灯何。","相逢莫认鹅湖寺，旧学无朋鬓欲皤。"]},{"t":"重登松风阁","f":"七言律诗","c":["天风满榻坐参禅，上有松声下有泉。","高阁我来三纪外，老僧谁起百年前。","茶垆夜湿昙花雨，画壁春销劫火烟。","最是泷冈犹未表，北山回首思悠然。"]},{"t":"卜居次西涯公","f":"七言律诗","c":["偶侍西堂坐夕阴，可胜欢喜动幽襟。","邻州卜筑闻新语，晚岁依归惬素心。","不朽功言方远大，本佳山水更高深。","愿教多植梧桐树，次第行听彩凤音。"]},{"t":"沛县怀古次韵","f":"七言律诗","c":["台有遗基水有滨，汉家碑刻未成尘。","独怜沛邑还称沛，却笑秦人自灭秦。","猛士存时犹北顾，故乡归日正东巡。","城阴秋草孤舟路，往事茫茫问野人。"]},{"t":"和吴太史种竹","f":"七言律诗","c":["此君不作此老客，庭院真应长绿苔。","古风藉汝数辈在，今雨从渠何所来。","岁晚简书留石室，月明环佩傍瑶台。","亦知径造有故事，一月须过三十回。"]},{"t":"谢方石以祖母旌门有作次韵","f":"七言律诗","c":["怀清台倚海天遥，台上风吹宿瘴消。","云汉章回联北极，山川光被表南条。","宁无乡里评如史，信有闺门礼似朝。","白发贤孙拜恩地，贞魂应亦望层霄。"]},{"t":"游从姑山","f":"七言律诗","c":["回首麻姑复从姑，江中烟雾两峰孤。","伊人似玉丹崖阻，吾道如川白日徂。","曾是待年终偃蹇，也应阅世未模糊。","晚来数点神灵雨，莫谓巫山作画图。"]},{"t":"游麻姑山二首 其一","f":"七言律诗","c":["千载荒坛故姓麻，劫灰漫道在烟霞。","泉流云壑真能胜，海变桑田或是誇。","此日佩兰贻水裔，它年笙鹤问天涯。","不须更索题名记，八月星河有使槎。"]},{"t":"游麻姑山二首 其二","f":"七言律诗","c":["几曲登登破岭烟，一亭一曲兴超然。","开云田画殷人井，转壑泉分禹日川。","独鹤每翔新表外，双松长倚旧坛前。","颜碑谩为传闻录，屈指于今又许年。"]},{"t":"都下诸友联句见寄用韵答之","f":"七言律诗","c":["千里怀人似望仙，春波碧漾草青芊。","周京汉署天寥阔，楚缆吴樯地接连。","山下石钟谁定论，江边铁柱或虚传。","欲凭山水寻诗句，录取图经次第笺。"]},{"t":"山行觅句","f":"七言律诗","c":["尽日山行苦乏诗，此山佳绝句难奇。","秖应使者孤吟在，安得仙人一和之。","千涧水流皆独往，万峰云起似相期。","春来漫兴何须记，它日重寻亦未迟。"]},{"t":"东林寺","f":"七言律诗","c":["东西林在万山中，石塔棱层见远公。","人结净缘还未了，天留佳境本无穷。","千峰云影朝还暮，一夜溪声雨更风。","欲觅莲花何处是，旧池惟有水涵空。"]},{"t":"谒李忠文公祠","f":"七言律诗","c":["江上孤城尽力支，忽惊风急仆旌旗。","已无天诉吾穷矣，空有人书某死之。","不负大魁真此地，终为厉鬼是何时。","何当合祀余安庆，再刻文山双庙词。"]},{"t":"送徐耕隐","f":"七言律诗","c":["白头京国为谁来，星聚应占近上台。","天下仲淹元老在，山中宏景隐君回。","竹林有句人争和，云岫无心鹤漫猜。","相业家声千百世，义庄新倚洑溪开。"]},{"t":"别后忆张元之","f":"七言律诗","c":["敝裘羸马未胜寒，近别其如数会难。","郢国书来心独切，江州衫在泪初乾。","月明西寺陪僧坐，天阔东楼挟客看。","忆昔不知今又昔，玉河风雪梦长安。"]},{"t":"梦松露公","f":"七言律诗","c":["几杖相从十载前，东曹斋阁故依然。","远书泪落西江水，旧梦心悬北阙天。","秋渚孤鸿还信信，春风嘉树自年年。","平生手疏遗编在，海内于今已有传。"]},{"t":"南昌感旧","f":"七言律诗","c":["舟行何处不通津，六载章江忆旧巡。","南浦但知乘传客，西山独识倚楼人。","坛松月静斋居夜，庭草风和燕坐春。","还向东亭问丛竹，别来烟露几回新。"]},{"t":"湘东夜宿","f":"七言律诗","c":["到处春禽弄碧杨，山行三月杂暄凉。","宜春台上吴关远，萍实桥西楚路长。","使节乘风朝渡水，客楼听雨夜焚香。","宪臣自识均劳义，不向长沙吊洛阳。"]},{"t":"哭王都宪汝言","f":"七言律诗","c":["未尽平生已盖棺，中丞风采豸为冠。","君臣药笼诸藩小，江汉戎衣六月寒。","岁月几何惊世短，风尘如此叹才难。","旧游却忆钱塘上，泪满遗书不忍看。"]},{"t":"赠户侍王德华分赈东行","f":"七言律诗","c":["燕山东去马骎骎，百姓应知使者心。","野有赭衣人似兽，途多菜色米如金。","天开岱岳增新观，春到甘棠复旧阴。","若过青州须吊古，范公祠下石泉深。"]},{"t":"与毛三江访匏翁故第暮归有作","f":"七言律诗","c":["久矣门墙梦寐中，偶来还喜故人同。","赋诗尚有庭前树，醒酒兼多竹外风。","百岁遗情孤绿野，一言嘉惠重南宫。","贤郎不负箕裘语，地下真堪慰乃翁。"]},{"t":"通州遇老母生日","f":"七言律诗","c":["去岁兹辰捧寿觞，一时冠盖总成行。","萱从蓟北还新梦，梅到淮南有蚤香。","寓客馆看东野线，望慈闱著老莱裳。","稀龄只在明年是，春酒亲持笑上堂。"]},{"t":"答成户部汝从","f":"古风","c":["一日看君或两过，相思还问夜如何。","西风乌鸟听时切，南国梅花梦里多。","吾道也知元尚白，此心空有贲如皤。","旧传康济无它术，数?缊絪是太和。"]},{"t":"次崔世兴西郊韵","f":"七言律诗","c":["炎风吹雨满山阳，正想西园七月凉。","医国自知投药苦，登山犹怪赋诗忙。","篇章独得君多有，几杖相从我亦尝。","抚卷匆匆又陈迹，江湖回首寸心长。"]},{"t":"途中次白参议辅之","f":"七言律诗","c":["舟行数日远尘歊，秋旱长河潦未消。","程趣漕兵无邸阁，报传候吏有津桥。","道傍垂枣全供鸟，野外飞蝗半食苗。","几度观风入村落，舆人堪诵不堪谣。"]},{"t":"登旴?山忆陈明之","f":"七言律诗","c":["汴泗南来见此山，米翁书在翠峰间。","唐人漫诧僧归塔，宋代曾悲使出关。","新讣忽迷云树碧，旧题空拭雨苔斑。","欲登高处谁相伴，黄鸟声中一啸还。"]},{"t":"和李方伯惟诚","f":"七言律诗","c":["西湖烟树晓依微，正是平轩忆我时。","采石眺缘仙客晚，金山留为故乡迟。","席随爽气真成画，笔写幽怀不当诗。","它日别情君记否，映江楼上酒盈卮。"]},{"t":"刘广德介夫至","f":"七言律诗","c":["千里缄书两日前，今朝丰采复依然。","金莲寺里观风地，白鹿斋中听雨年。","夜雪梦回开小径，秋涛观罢乏平川。","梅花已有真消息，不用江南驿使传。"]},{"t":"十贤祠用唐人韵","f":"七言律诗","c":["千年祠宇此重开，独为诸贤酹一杯。","涧石不随龙化去，岭云还与鹤归来。","春风谷远嘤嘤鸟，夜雨庭深点点苔。","听罢雅歌宾客醉，共教童子汲泉回。"]},{"t":"又用唐人韵","f":"七言律诗","c":["九峰回处石泉幽，逝者应知感旧游。","万里风烟吾白首，千年林壑此清流。","松筠无恙时方晚，黍稷惟馨岁有秋。","却忆匡庐歌啸地，几回春草鹿呦呦。"]},{"t":"除夜雨","f":"七言律诗","c":["爆竹声中破积阴，东风庭院晚沈沈。","閒评经世何人手，老惜流年此夜心。","宸极有临香几近，慈闱无恙酒杯深。","呼童起听南轩雨，却报梅花已满林。"]},{"t":"寄秦提学国声","f":"七言律诗","c":["宪学名官愧我曾，得君相继价逾增。","镕金有制元随可，璞玉无形已付能。","河广正誇杭一苇，崧高还爱驻双藤。","许州品士亭如在，校罢诸生请试登。"]},{"t":"李惟正燕予通州漕府感旧有述追怀张中丞邦镇","f":"七言律诗","c":["旧馆苔荒郭外坡，故人相约又来过。","昔年盟有莺声在，它夜诗如树影何。","东道意勤三设燕，南风调远一赓歌。","却怀襄野经行地，沙草茫茫隔潞河。"]},{"t":"送吴方伯献之赴山西","f":"七言律诗","c":["三月行旌度太行，和风甘雨百花香。","吴公旧政曾于汉，晋国馀民本自唐。","双阙每瞻星北极，诸邦兼领甸西方。","不须久作江湖念，回首从容是庙堂。"]},{"t":"雨坐有怀","f":"七言律诗","c":["萧萧风雨不知春，独坐东亭感慨频。","四海有怀非我力，百年无愧是谁身。","翠留竹节心期远，红入梅花眼界新。","尚觉平生诗兴在，短吟须寄社中人。"]},{"t":"晓发南浦","f":"七言律诗","c":["西山南浦隔江流，又作新春第一游。","舟趁微风斜渡水，舆穿宿雾漫经邱。","此行更切真才望，何处还多丽景收。","东向匡庐兴无限，五峰青点白云头。"]},{"t":"得钱希翁诗简","f":"七言律诗","c":["云厓传得步虚歌，回首苍生奈尔何。","觞酒谁家延北海，瓣香它日谢东坡。","江湖秋水瞳兼碧，花鸟春风鬓独皤。","共说陶潜能避俗，却将心事托荆轲。"]},{"t":"赠周作之","f":"七言律诗","c":["别来风彘转深微，雨雪青灯坐掩扉。","江晚不堪滕阁眺，春初应及楚帆归。","寻常未必钟期少，五十何妨伯玉非。","它夜南沙重下榻，匡山云尚在征衣。"]},{"t":"次作之","f":"七言律诗","c":["鄱湖木落天雨霜，故人西来故意长。","剧谈今古每半夜，漫阅乾坤还一阳。","也知白鹿昔年梦，却忆紫阳何处乡。","劝君且束旧诗卷，回首春风踏去航。"]},{"t":"奉次少傅徐公内阁赏芍药","f":"七言律诗","c":["五云轻阁凤楼阴，春入雕阑故故深。","培植敢忘明主力，调和真见老臣心。","彭城谱绝看新续，魏国盟寒许重寻。","却与长安添纸价，词林传和赏花吟。"]},{"t":"谢少傅公惠梅子","f":"七言律诗","c":["谁将碧玉鍊成丸，寒逼人间玛瑙盘。","数颗忽分元老赐，十年如在故山看。","清含晓露真消渴，老向春风常带酸。","嘉实秖应金鼎内，调和功在颂皆难。"]},{"t":"叫岩次陈户部嘉言","f":"七言律诗","c":["师子逾江漫作奇，此山真有物司之。","悬藤不与云俱化，浮石应随鸟共驰。","郡将游来曾易榜，民曹别去肯留诗。","山僧莫讶登临晚，日落高天为我迟。"]},{"t":"闻吴宁庵转南京学士二首 其一","f":"七言律诗","c":["山水江南是旧游，公来谁不拟仙舟。","高陵云护钟山晓，清禁星连阁道秋。","新制有词全逼汉，旧章无恙正从周。","封君老向荆溪上，十日三书慰白头。"]},{"t":"闻吴宁庵转南京学士二首 其二","f":"七言律诗","c":["清风每有江东兴，此地我知公欲来。","天上灵槎连震泽，人间嘉树近蓬莱。","风云长护宣麻署，日月遥临视草台。","闻道老槐当卧阁，北扉回首是三台。"]},{"t":"张家湾东遇王参政德华","f":"七言律诗","c":["晋溪北上我南游，潞水东头半日留。","何处可忘君父念，此行须为庙堂谋。","百年雅颂知能夏，千里歌讴望有秋。","指日王师收战绩，勿言江左旧风流。"]},{"t":"释菜濂溪书院贻王佥宪景昭","f":"七言律诗","c":["一脉濂溪万古天，江州名自道州传。","有神真与泉俱活，无象还留月自圆。","将济晚舟犹滞在，未成春服已悠然。","东风昨报新消息，许我重栽玉井莲。"]},{"t":"谒东汇泽陈先生祠","f":"七言律诗","c":["团山坳里奠公堂，何意重来致瓣香。","史及阙文怜误豕，礼将求野幸存羊。","心精已与经行世，德义元堪社在乡。","尚欠新碑书岁月，祠官称秩有封章。"]},{"t":"陈方伯晋庵挽词","f":"七言律诗","c":["归云堂下雨毵毵，哭寄长歌为晋庵。","诗律独追唐逸响，史评常陋晋清谈。","入参台鼎阶无几，退谢藩垣疏有三。","百岁高名碑石在，松阴十里锡山南。"]},{"t":"过南康","f":"七言律诗","c":["突尔匡庐又眼前，白笼云气碧笼烟。","天留风景都无恙，我与山灵故有缘。","晴雨漫须询五老，寒暄忽已计三年。","独怜渴思今如许，为汲开先寺里泉。"]},{"t":"见五老峰","f":"七言律诗","c":["倚棹看山卯到辰，白云何意不随人。","久要未恨相逢晚，远望还输独对真。","坐客眼青高踞榻，飞仙鬟碧浅笼巾。","它年问答应多事，一笑而今共出尘。"]},{"t":"读成布衣祭忠文","f":"七言律诗","c":["万古兴亡泪满笺，一坛遥忆祭忠年。","大书笔在凭谁执，高调歌沈待我传。","无地可投湘水裔，有天应照越山颠。","布衣闵世尤堪吊，何处松楸是墓田。"]},{"t":"括王勃诗","f":"七言律诗","c":["高台迢遰绝浮埃，俯瞰长安四望开。","绿树摇风春澹荡，赤城映日晓崔嵬。","倡家今夜银鞍去，戚里它年翠盖来。","不用哀歌对明月，柏梁铜柏总莓苔。"]},{"t":"送杨衢州磐","f":"七言律诗","c":["秋晚山城别驾临，水清石净万峰深。","风回祥凤轻千仞，日转甘棠爱寸阴。","吾道百年皆此地，斯民三代复何心。","赵公祠下瞻趋地，共讶今来又一琴。"]},{"t":"忆东林精舍寄示华生云","f":"七言律诗","c":["东林寺里旧书堂，三十年来野草荒。","百啭未忘初鸟韵，一株犹剩晚柑香。","山怀龙阜神俱远，水问梅村脉故长。","寄语云生为磨石，客中新记已成章。"]},{"t":"舟中有见忆老母","f":"七言律诗","c":["老梅花吐北堂前，春酒初成妇荐筵。","事与志违频易地，心为形役几经年。","天恩于物真能厚，子道如臣敢自偏。","检罢计书方静坐，不堪乡语过吴船。"]},{"t":"两过德州未谒董子祠诗以志过","f":"七言律诗","c":["地产醇儒郡有光，两来犹未谒祠堂。","春秋义已传迁史，谊利心曾辨粤王。","拜位定依庭柏影，荐仪空托沚蘋香。","孤城回首风尘里，读罢遗书送夕阳。"]},{"t":"再至德州","f":"七言律诗","c":["奉使南来又德州，僧堂还记旧淹留。","星明北极天初霁，风扫中原雾已收。","野旷尚馀千里水，漕荒应负一年秋。","咨询未尽皇华体，赋罢䍧羊独倚楼。"]},{"t":"沧州闻官军之捷寄兵侍陆公","f":"七言律诗","c":["露檄传来捷是真，沧州南望正劳神。","功成鲁国追戎地，断许唐年入蔡人。","有梦维鱼应得水，此风何草不回春。","北辰瞻仰朝廷近，欲拟韩诗献紫宸。"]},{"t":"再过清献祠","f":"七言律诗","c":["江回春水没荒矶，石上看诗记旧题。","吾道百年开白日，公心千古映清溪。","鹤留古貌何妨瘦，松长新枝尚恨低。","却忆昔游如昨日，楚云遥接越东西。"]},{"t":"次吴太史雪中见寄","f":"七言律诗","c":["玉河东下似山阴，骑马如船雪满襟。","吏散偶忘前日约，诗来真见故人心。","寒侵松骨知多少，春入梅腮定浅深。","欲赋琼瑶报佳贶，独怜才短负知音。"]},{"t":"吊李憩庵公墓次庄定山","f":"七言律诗","c":["萧萧宰木昼呼风，旧垄新阡北又东。","防墓未须修孔氏，泷冈真合表崇公。","两朝一德功何自，五岁三封眷未终。","更爱颂声金石在，碧天无际水无穷。"]},{"t":"闻陈行之讣","f":"七言律诗","c":["俗学如俳到十分，玉溪高兴漫超群。","著书笔自何时阁，曳杖歌从昨夜闻。","绝壁倚云青未了，落花带雪白还纷。","哀吟一曲无人和，拟向西山更哭君。"]},{"t":"赠祝惟贞致仕南还次陈一夔","f":"七言律诗","c":["鹤骨棱棱苦为诗，年来此癖已成奇。","与君抚卷俱陈迹，及我登坛竟后期。","听鸟有情嗟反哺，折花无语赠将离。","文星夜夜天南极，千里长吟寄所思。"]},{"t":"通州留别李都宪惟正","f":"七言律诗","c":["潞河堤上望浑河，诸老追随几度过。","春兴有馀三月小，夕谈无数十年多。","东郊正尔歌灵雨，南浦何须赋渌波。","边马不嘶青草阔，中丞问俗意如何。"]},{"t":"白鹿洞三首 其一","f":"七言律诗","c":["五老峰前数亩宫，坐凭云水镇南东。","山人骨相千年外，洞主心期一赋中。","题壁定知谁不朽，望洋真觉我难穷。","太山顶上蓬莱近，何处青鸾欲御风。"]},{"t":"白鹿洞三首 其二","f":"七言律诗","c":["青山坐我对青衫，吊古情多漫与谈。","眠鹿已无人主洞，卧龙空有地名庵。","百年讲坐惭虚左，万里驱车愿指南。","吹醒清风天未晚，共谁长笑破烟岚。"]},{"t":"白鹿洞三首 其三","f":"七言律诗","c":["风雨崇朝洗宿岚，古坛高倚五峰南。","坐看云气秋生壁，卧听泉声夜绕庵。","杖履正堪成雅集，弦歌犹恐落清谈。","殷勤好语来游客，莫遣飞尘上旧衫。"]},{"t":"送邵佥宪用之复任山东","f":"七言律诗","c":["滇海归来老使君，东行还共泰山云。","州兼青兖双旌去，天近沧瀛一道分。","何处秦碑犹可识，它年汉诏漫曾闻。","须公高揽澄清辔，马首西风日未曛。"]},{"t":"送周工部元弼","f":"七言律诗","c":["水部官怜初拜日，金陵地忆旧游时。","未应岁月閒供吏，最是江山巧索诗。","秋色催人移棹急，客怀逢雨出郊迟。","静中经济堪料理，笑把清樽有所期。"]},{"t":"雨坐漫述是日郭仁宏寄小像至","f":"七言律诗","c":["镜中愁鬓欲成皤，新画应惭郭泰和。","花谢晓风方恨急，麦收春雨竟嫌多。","曲房辟湿频烧术，单裌生寒重易罗。","满院青枝飞燕子，扣门时有客相过。"]},{"t":"凤阳谒陵","f":"七言律诗","c":["郁葱佳气接邱坛，真向乾坤得大观。","岁举留都周册祝，月游原庙汉衣冠。","九重陟降天应近，万世栽培地本宽。","瞻仰不胜心颂在，无疆休与泰山安。"]},{"t":"雪中赏红梅奉次涯翁先生时邃翁携酒共饮怀麓堂二首 其二","f":"七言律诗","c":["江南春色渺无涯，借得芳枝似酒赊。","点染已经元老手，品题还许大方家。","丹心独对年年树，玉貌空传处处花。","雪夜门深清梦远，敢将桃李向人誇。"]},{"t":"又叠前韵荅邃翁先生二首 其一","f":"七言律诗","c":["谁寄江南第一枝，岁寒如有物司之。","天于北道留馀地，人为东君惜后时。","太素风流难入画，半酣颜色最禁诗。","平生鼎鼐心知在，且共西堂雪夜卮。"]},{"t":"又叠前韵荅邃翁先生二首 其二","f":"七言律诗","c":["金鼍山畔洞庭涯，咫尺寒香道路赊。","雪夜不回仙客棹，春风元在相君家。","地应有律能生黍，天亦多情为雨花。","投我琼瑶何以报，拟将归向北堂誇。"]},{"t":"得见素公书","f":"七言律诗","c":["素老书来蜀道长，洞庭春水正茫茫。","出群才本安危寄，习隐心应去住忘。","夔府孤城看落日，杜陵野客梦沧浪。","远人欲挽难为计，共指方平像在堂。"]},{"t":"寄李提学献吉","f":"七言律诗","c":["铁柱宫前春水深，几回清梦忆登临。","新亭有客还题壁，旧曲何年为入琴。","高士榻虚人似玉，此君堂小地如金。","近来又读宗儒记，回首匡庐万古心。"]},{"t":"文庙陪祀次柳方伯拱之","f":"七言律诗","c":["惠风入夜细吹衣，坐爱宫墙咫尺违。","星破密云看渐朗，尘消冻雨恨犹微。","梦馀真睹殷楹奠，语次空传点瑟希。","此意欲从何处道，东堂灯火两冠巍。"]},{"t":"登滕王阁","f":"七言律诗","c":["望尽江湖极目天，滕王楼阁尚巍然。","云中帆影寒流外，雪后帘光夕照前。","它日赋曾倾客坐，何人游更挟飞仙。","庙堂远念诸公在，回首层霄北斗悬。"]},{"t":"次白洲公","f":"七言律诗","c":["且临岘首吊羊公，回首台阶近九重。","千丈厓堪供巨笔，一杯酒为庆奇逢。","谢安山卧曾江左，召伯风行又陜东。","麟阁峥嵘它日地，丹青能写汉臣功。"]},{"t":"奉次东山公在广元夕观灯韵","f":"七言律诗","c":["寻常诗句亦黎元，垂老丹心照海门。","且以数杯酬客兴，何曾一饭忘君恩。","漏声入夜风全静，灯影乘春月半昏。","闻说总戎多解事，漫将歌吹过江村。"]},{"t":"别庐山","f":"七言律诗","c":["山北山南几度游，春风到处得相留。","鹿听李渤祠前晓，菊采陶潜宅畔秋。","星落半湖苍岛出，泉分双涧白云流。","五峰明月新亭兴，它夜江天独倚楼。"]},{"t":"归兴六首 其一","f":"七言律诗","c":["曾从渡口赋桃花，客路风光几岁华。","州郡十年还入省，漕渠数月竟思家。","星辰近听趋朝履，河汉虚随奉使槎。","斜日倚楼沧海上，云山回首一长嗟。"]},{"t":"归兴六首 其六","f":"七言律诗","c":["湖上飞云小作阴，龙神祠下水流深。","河渠未预千年计，阙里徒勤万古心。","驿报正愁闻鲁警，棹歌初喜听吴音。","顺流东下三千里，一笑清风忽满襟。"]},{"t":"分司夜阅卷","f":"七言律诗","c":["肯信行台是隐居，手寒中夜尚披书。","冰霜气逼庭初静，星斗光临户正虚。","漫道相人如相马，极知观理似观鱼。","九重方切真才念，独对青灯意有馀。"]},{"t":"青云峰用元人韵","f":"七言律诗","c":["眼中感慨几千秋，第一峰春翠欲流。","迹为古人须下马，兴当今日可登楼。","冰霜以后花兼鸟，山水之间县复州。","采得寒梅香满袖，更从江上问横舟。"]},{"t":"建昌道中见杏花","f":"七言律诗","c":["临川梅花尚在眼，旴江忽复杏花红。","山行远近百里外，春色浅深三日中。","有力已能知夜雨，无心那复问东风。","明朝又向南丰路，却听莺声处处同。"]},{"t":"小溪道中","f":"七言律诗","c":["春云收雨寂无功，诗景依稀在眼中。","南去驿连分水䫈，北来船趁上江风。","细泉落涧深成碧，幽径垂花浅著红。","玉枕有名何处是，令人却忆白沙翁。"]},{"t":"送金潮","f":"七言律诗","c":["万壑清冰贮玉壶，相逢却讶是尘途。","颖师妙已传琴操，米老奇还托画图。","白马五陵初入蓟，绿杨三月又归吴。","凭谁为赋行吟地，云满青山月满湖。"]},{"t":"寄姚都水秀夫","f":"七言律诗","c":["疏浚功成数十州，东南应免九重忧。","奈何水部称多病，却向鹅湖访旧游。","燕䫈暄凉凭候雁，楚江晴雨问鸣鸠。","草玄闻有平生意，须及扬雄未白头。"]},{"t":"答潘维本","f":"七言律诗","c":["官忙十日九在省，客邸劳君过几回。","片纸漫投今世刺，千金曾吊旧时台。","江长云外鸿还去，秋老山中菊正开。","却忆湖南湖北地，和君诗罢一徘徊。"]},{"t":"闻三原公讣二首 其一","f":"七言律诗","c":["五朝进退盛明时，四海瞻依百辟师。","散地尚堪栖老凤，格人真合拟元龟。","紫宸陛远星辰切，绿野堂深日月迟。","韩富勋劳司马望，大书谁作墓前碑。"]},{"t":"闻三原公讣二首 其二","f":"七言律诗","c":["载起登廷七十馀，两童疋马老生如。","四夷相问相司马，千载独知师敬舆。","咫尺天回书侃侃，万间人庇屋渠渠。","典刑已矣遗文在，西望三原泪满裾。"]},{"t":"还自长沙未有述作谢沈休翁","f":"七言律诗","c":["谓我南行大有诗，鄙人何敢与闻之。","潇湘尚忆虞巡地，云梦宁知楚猎时。","木落洞庭秋复尔，鹤来赤壁夜何其。","登高坐待浮云尽，回首青天见九疑。"]},{"t":"过长沙不得谒贾祠","f":"七言律诗","c":["巨笔谁修汉一经，治安策已动天听。","奠无可藉茅空白，采不堪纫草正青。","旧井定通瀍北水，新祠真应斗南星。","独怜鵩鸟翻为瑞，万古清风满石亭。"]},{"t":"生日和答王河南公济","f":"七言律诗","c":["新植甘棠未作阴，生辰忽向冗时临。","人间乐事还莱綵，天上佳音有传霖。","近不可亲鸥似玉，淡犹堪赏菊如金。","岳楼记在何能读，惭愧希文万古心。"]},{"t":"答魏宪使士华用公济韵二首 其一","f":"七言律诗","c":["三礼周旋起一经，凤皇鸣动九重听。","爱云曾袖匡庐白，题石还磨剑阁青。","范记读馀心耿耿，楚骚歌罢鬓星星。","长沙回首相思极，路隔湘东几驿亭。"]},{"t":"答魏宪使士华用公济韵二首 其二","f":"七言律诗","c":["閒倚船窗看水经，沧浪歌起隔江听。","霜台简自它年白，雨寺灯犹昨夜青。","秋水南湖千万顷，晚云北斗四三星。","重阳己负登高约，何处寻盟更有亭。"]},{"t":"新祥宫漫述亦用前韵","f":"七言律诗","c":["懒听道士诵仙经，却爱吹笙隔院听。","江上云应无数白，雨中山亦有时青。","囊琴正迓来今雨，匣剑还将拭旧星。","莫道深秋佳趣少，菊边修竹故亭亭。"]},{"t":"邃庵先生约登金山","f":"七言律诗","c":["世间谁信有瀛洲，奇冠江南第一州。","龙窟不知何事露，星槎真向几时浮。","石分砥柱还孤注，水入沧溟正急流。","更上留云穷望眼，海风吹浪晚飕飕。"]},{"t":"留别沈休翁","f":"七言律诗","c":["湖南会本自江东，二十馀年气味同。","此去春违丰采外，向来心在简书中。","杜陵门径还今雨，司马衣冠更古风。","西望武昌江汉表，云连黄鹤倚晴空。"]},{"t":"追悼匏庵公","f":"七言律诗","c":["天寿斯文为国华，枯藤瘦树著新葩。","无书谢客门长静，有梦怀人室未遐。","十字谁题君子墓，一编自许大方家。","梧桐高倚庵前月，鸣鸟寥寥噪暮鸦。"]},{"t":"采石登谪仙楼","f":"七言律诗","c":["济上登楼已十年，兹楼兴在未登前。","何人不道诗能圣，昔日空传酒解仙。","舟楫心期风乍起，屋梁颜色月犹悬。","留题讵敢轻磨石，万古江山一慨然。"]},{"t":"望庐山用旧韵","f":"七言律诗","c":["曾从王守问山庵，神思飞驰不自堪。","有意一亭携客赏，无言五老拟禅参。","朝宗江汉心初北，梦寐烟霞眼正南。","我忆旧游多述作，凭谁刻向卧龙龛。"]},{"t":"舟中望九华山用李韵","f":"七言律诗","c":["微雨初收草似茵，九华山色欲迎人。","援琴正怪知音少，倾盖何妨识面新。","溪汎绿波才隔夜，树垂青子又馀春。","风涛宦海今如许，何处寻仙问出尘。"]},{"t":"龙兴寺述事","f":"七言律诗","c":["佛殿庄严似法宫，圣恩偏注此山中。","南朝寺在俱凡界，西竺僧来自祖风。","画栋本连陵树碧，绮疏曾映苑花红。","题名幸与司徒后，怪得行旌懒向东。"]},{"t":"舟中读匏翁诗","f":"七言律诗","c":["不见此翁还此诗，读诗真想对翁时。","峰回深谷树重叠，渚漾轻波草陆离。","载道弦歌邹鲁国，旅庭彝鼎孔周祠。","平生海月庵中兴，应许藤床竹几知。"]},{"t":"齐安晚泊时荣藩初之国偕二司迎之","f":"七言律诗","c":["漫向东坡问雪堂，雪残寒日正荒荒。","地名自是因人重，客思那胜为国忙。","万古江流从禹贡，一时风力有周郎。","召南曾赋甘棠树，谁遣春阴遍楚乡。"]},{"t":"谒苏祠用前韵","f":"七言律诗","c":["去公千载我登堂，春草离离若与荒。","雨露不知天地阔，江山应笑古今忙。","官衔漫逐三司使，民瘼愁闻百里郎。","何处有灵还可吊，旧游随地是吾乡。"]},{"t":"望东莱墓","f":"七言律诗","c":["内白亭边墓道开，瓣香深拟拜东莱。","风雩有象公何在，棠树无歌我却来。","两月近思真定本，千年大事未终裁。","白云回首山中寺，寒日荒荒径满苔。"]},{"t":"观诚意伯像于处州","f":"七言律诗","c":["一代元功百世豪，遗容瞻处丽阳高。","天留汤沐田无税，人效明禋涧有毛。","莘野不妨初就桀，草庐犹恨未诛曹。","万峰指点青田路，断石枯松望眼劳。"]},{"t":"山中梦希翁","f":"七言律诗","c":["江涛夜寒公不来，公来入梦亦奇哉。","百年知己惟心在，万事随人可力回。","望久更无谁下榻，兴多惟有独登台。","欲将五老峰头树，移向西湖崦里栽。"]},{"t":"山中怀杨仪部","f":"七言律诗","c":["未得登君野兴堂，两年清梦独难忘。","笑谈每怪逢僧健，文字犹嫌应客忙。","山月挂松真洒落，海云迎鹤更昂藏。","吴天楚地同秋水，老尽蒹葭一夜霜。"]},{"t":"读钓台集用陈白沙韵二首 其一","f":"七言律诗","c":["莫将身世较行藏，钓石能增处士光。","青眼屡烦真主顾，白头端为故人昂。","云归故䫈龙应懒，蘋委空江水亦香。","九鼎一丝形迹外，尽教俗客笑荒唐。"]},{"t":"读钓台集用陈白沙韵二首 其二","f":"七言律诗","c":["从来自信任人疑，一寸丹心付所知。","白石有情依古庙，青苔无赖上残碑。","芝从商䫈犹知主，鱼向磻溪已得师。","未到桐江空仰止，数章新和白沙诗。"]},{"t":"石钟山","f":"七言律诗","c":["九江怒逼蠡涛东，独受舂撞万窍空。","人籁总输天与地，石声还藉水兼风。","数椽僧结云厓上，一舸仙乘夜月中。","何处别寻吴季子，只留馀地待铭功。"]},{"t":"九江靖忠书院","f":"七言律诗","c":["岁时江郡荐江蘋，异代衣冠略近真。","九死竟还唐社稷，一生惟识晋君臣。","菊松尚拟它年晚，桃李聊增此地春。","莫道近来公论少，庙门题额是何人。"]},{"t":"广信遇庞大参元化","f":"七言律诗","c":["两省分司偶此同，不堪信宿又西东。","衣冠元重藩臣体，议论犹多国士风。","春殿香烟趋北阙，夜堂灯火坐南宫。","它年更有相逢地，又引鹅湖入话中。"]},{"t":"吉水遇王敬止用送盛斯徵韵","f":"七言律诗","c":["江声初静晚风轻，千里关山可计程。","独立已为它日重，相逢真使故人荣。","望穷螮蝀云犹密，歌罢沧浪水正清。","笑折梅花对摇落，不须杨柳管离情。"]},{"t":"送喻祁阳时","f":"七言律诗","c":["永州南隔洞庭深，令尹之官动楚吟。","展骥谁怜庞氏足，捕蛇偏感柳侯心。","行春驾远歌盈路，帘昼庭閒政在琴。","何日徵书君莫问，东风郊野看棠阴。"]},{"t":"高梁寺次赵栗夫韵","f":"七言律诗","c":["春晴方喜入山深，古寺高梁故故寻。","江上诗囊连日兴，雨中禅榻隔年心。","竹藏幽径云初合，松倚高坛月正临。","指点匡庐何处是，万峰回首问东林。"]},{"t":"谒关公庙","f":"七言律诗","c":["本来报效非心事，死后英魂肯再游。","白日在天书一纸，清风如水庙千秋。","伏桥有志宁臣赵，左袒无期独为刘。","半部邱明真得力，儿曹空解颂君侯。"]},{"t":"谒子产祠","f":"七言律诗","c":["一上高台万古情，相君何在但留名。","论经孔孟真褒贬，世到春秋有战争。","西北封疆犹接晋，东南形势直吞荆。","如今想像驰词地，庐井荒茫画不成。"]},{"t":"大忠祠","f":"七言律诗","c":["慈元殿上朔风侵，讲罢孤臣泪雨深。","行在更无南去路，中兴犹有北来心。","一言竟免青衣辱，万古终悲白壁沈。","世乱经纶亦何济，大忠祠下柏森森。"]},{"t":"哭天瑞","f":"七言律诗","c":["百年豪气未消磨，北骑南航苦更多。","恋阙有怀随口是，乞祠无计奈身何。","山连巴蜀云层瘴，春入潇湘水漫波。","最是游魂招不得，隔江愁听楚人歌。"]},{"t":"送万晦之","f":"七言律诗","c":["南阳有约欲相寻，回首清风别颍阴。","鲁望江湖从故态，少陵花鸟负初心。","诗邀佳境云随杖，梦破残更月在琴。","歇马烦君问诸葛，草庐无径落华深。"]},{"t":"登九江郡城楼","f":"七言律诗","c":["浔阳之东东城楼，秋日喜陪诸老游。","水深已失江九派，云远还容山一头。","西风爽气自荆益，南极清光当斗牛。","有怀晚在莲峰下，千古美人周道州。"]},{"t":"馀干东冈咏怀一首用虞邵庵韵","f":"七言律诗","c":["东冈正在行台东，我登其巅西日红。","宋人冠冕竟谁作，吴地舟航元自通。","康山战罢蛟无穴，鄱水祷回龙有宫。","千秋莫问注骚事，宿莽洲边云接空。"]},{"t":"挽娄一斋","f":"七言律诗","c":["它年曾读一斋书，梦入云山问起居。","前辈风流犹有此，古人门户竟何如。","鹅湖绝笔留真迹，洛社深衣复故袪。","哭罢莲塘还再恸，玉峰高冢两渠渠。"]},{"t":"次杨邃庵先生留别二首 其一","f":"七言律诗","c":["百尺高台傍寺门，杜陵秋兴此犹存。","赠行独愧清风句，留坐还依古树根。","星共北辰双阙近，山连西岳一峰尊。","明朝旌节投何处，望断秦云眼欲昏。"]},{"t":"次杨邃庵先生留别二首 其二","f":"七言律诗","c":["雨馀风叶飞长林，使君别去愁难任。","也知鸣铎自天意，肯谓乘轺非我心。","燕山青连北极近，渭水东入黄河深。","请看祖席半门下，它日被褐今朝簪。"]},{"t":"次王朝言","f":"七言律诗","c":["有怀自遣坐新凉，昼漏沈沈静里长。","千里乡关频入望，两年朝省漫随行。","云迷晚渚花犹隐，风入秋林树亦狂。","我忆美人元不远，蒹葭空赋露为霜。"]},{"t":"武宁分司次见素公韵","f":"七言律诗","c":["万山旌节破风烟，细草承舆软似绵。","莳稻有歌春鸟和，采桑无侣晚蚕眠。","两旬庐岳仍回眼，百里洪厓漫拍肩。","读罢妙词清不寐，夜深犹忆对莆田。"]},{"t":"闻李兵备讣","f":"七言律诗","c":["郁孤台下鸮夜啼，白日惨惨愁云低。","三年戎幕庾岭北，万里旅榇巫峰西。","江湖落落岁复月，风雨萧萧山更溪。","平生勤事数行墨，回首教场秋草迷。"]},{"t":"阻风用杜韵","f":"七言律诗","c":["画舫乘春满载书，阻风聊傍野洲居。","此时独坐爱骑鹤，何处老翁来卖鱼。","飞云漫逐海鸥远，鸣雨渐敲江树疏。","莫言散局有底急，湖上草深方待锄。"]},{"t":"次韵答万晦之","f":"七言律诗","c":["逢君在许复京师，几向天涯叹别离。","南客讵无庄鴳适，北人那有召棠思。","江湖兴远新居定，风月情多旧榻知。","野寺梅花堪折未，欲凭尊酒侑临岐。"]},{"t":"别白鹿","f":"七言律诗","c":["五老峰前双涧流，洞门草长鹿呦呦。","深云似与春长住，细雨何妨午未收。","千里客怀频出使，数年吏事半藏修。","明朝我放东风棹，分付山灵管素秋。"]},{"t":"吊林和靖墓","f":"七言律诗","c":["赋得梅花万古传，水滨孤冢却萧然。","閒云于我心俱隐，老鹤如人骨半仙。","朝市尚馀观物地，儿童不省入城年。","小桥东去今成路，回首中洲但暮烟。"]},{"t":"谒于肃悯祠","f":"七言律诗","c":["祠前春雾隐绯袍，隔岭松声应海涛。","伯纪空勤恢复计，子仪还重廓清劳。","我将薄奠成三献，谁作长歌寄一号。","西望岳坟才数里，白云湖上两峰高。"]},{"t":"五老峰","f":"七言律诗","c":["匡庐山头五老人，晚岁才见羲皇民。","雪蒙绿发不改色，云映苍颜真入神。","岂无北海未须避，自有南极堪为邻。","吾亭拟结白鹿上，独对一杯公莫嗔。"]},{"t":"重阳答钱户部","f":"七言律诗","c":["晴日重阳冗里过，百年佳节几蹉跎。","山当对面愁登远，客有知心恨别多。","白发此僧聊尔耳，黄花明日又如何。","沧浪濯足非吾敢，敢谓春湖胜王珂。"]},{"t":"松风阁赠方昆山用顾与成韵","f":"七言律诗","c":["石鼎诗成向我歌，听松楼外竹为窝。","风烟逸望三江远，湖海清谈一夜多。","云近不知山是否，雨深还问月如何。","相逢莫讶辞官蚤，鬓发萧萧短更皤。"]},{"t":"寄题邵宪副东邱娱晚亭","f":"七言律诗","c":["荆南溪水水东头，宪使归来访故邱。","绿野竟忘裴晋国，香山真识白江州。","风尘迹远新图画，山水情深旧钓游。","我有一尊思共醉，扁舟将趁菊花秋。"]},{"t":"山中答黄明甫","f":"七言律诗","c":["谩乞新诗续旧诗，小江高兴老僧知。","旌驰岭外观风地，榻寄山中听雨时。","泉近不劳将石子，云深惟许偃松枝。","浩歌一曲沧浪月，万古心期酒在卮。"]},{"t":"夜泊邬子闻雷有感","f":"七言律诗","c":["鸣雨乍过江茫然，龙津驿前还泊船。","柝声欲罢鸡且叫，乡信未来吾独眠。","沙边白鸥手可掣，湖上碧草梦相牵。","明星照水看渐隐，春阴冉冉生云烟。"]},{"t":"谒严先生祠","f":"七言律诗","c":["碧石离离草色新，富春山下几回春。","漫将卖菜辞求益，本为观鱼得任真。","三代道亡还此有，两生心在更何人。","客星亭倚浮云外，未许渔翁来卜邻。"]},{"t":"夜赠陈都司","f":"七言绝句","c":["卫水东流起白波，楼船灯火听渔歌。","仙翁本是乘槎客，风雨其如此夜何。"]},{"t":"观东山草堂赋墨本","f":"七言绝句","c":["湖南刘是江东谢，千古清风两草堂。","归去有词涯老在，人间漫许晋文章。"]},{"t":"天台图","f":"七言绝句","c":["东南佳胜是天台，刘阮当年亦偶来。","仙药有无君莫问，山中桃似世间开。"]},{"t":"白莲小画","f":"七言绝句","c":["新雨池塘透晚凉，蜻蜓飞处白莲香。","江南风景堪图画，怪得龙皋欲断肠。"]},{"t":"画蟾","f":"七言绝句","c":["山鬼一脚臧三耳，物幻人诬或有之。","刚道老蟆能蚀月，玉川吟后到今疑。"]},{"t":"西溪书屋为张邦谷题","f":"七言绝句","c":["西溪又是太湖西，东望龙峰路不迷。","我有草堂泉石畔，十年云月梦栖栖。"]},{"t":"赠王翁","f":"七言绝句","c":["惇史曾闻古有之，风流犹在汉文时。","圣朝恩典还三代，笑对峨冠咏寿诗。"]},{"t":"赠徐东之","f":"七言绝句","c":["姓名已上古灵章，却忆江南水竹乡。","忧似唐衢无涕泪，古松阴里啸声长。"]},{"t":"答周作之","f":"七言绝句","c":["禅心闻说定多年，却问东巡御史船。","我正厌听西北事，涣然亭上对鸥眠。"]},{"t":"宿梅洲","f":"七言绝句","c":["秋水清如雪下船，黄花半委月犹悬。","枕当星剑看牛斗，鹤下云汀流石泉。"]},{"t":"琵琶亭二首 其一","f":"七言绝句","c":["世间夫妇似君臣，门外天涯语是真。","一曲琵琶皆掩涕，无人传与买茶人。"]},{"t":"琵琶亭二首 其二","f":"七言绝句","c":["草堂卜筑傍东林，老去寻山恐未深。","江上琵琶自秋月，如何却有世间心。"]},{"t":"圆通寺","f":"七言绝句","c":["石乳峰前雷雨来，圆通寺里咏茶杯。","明朝又向东林去，山路新晴花正开。"]},{"t":"留别娄诚善","f":"七言绝句","c":["新诗赠我胜千金，病阁青灯字字心。","正在溪冰山玉处，月明还听老龙吟。"]},{"t":"喜晴二首 其一","f":"七言绝句","c":["山行愁雨水愁风，两月风中更雨中。","今日一帆天送我，晴湖如鉴夕阳红。"]},{"t":"喜晴二首 其二","f":"七言绝句","c":["万山深处古宁州，五日真成十载游。","千古濂翁招不返，翠云亭上看江流。"]},{"t":"拜石图","f":"七言绝句","c":["风骚回首一茫然，漫浪如公亦可怜。","懒是拜人偏拜石，至今犹说米家颠。"]},{"t":"画鸠","f":"七言绝句","c":["鹊巢何处树深深，苇有新丛水有浔。","乍雨忽晴天未定，恐将消息误知音。"]},{"t":"南康寄陈分巡希冉时希冉之九江一日矣","f":"七言绝句","c":["江上春风酒一壶，南来拟共对鄱湖。","夜深独听庐山雨，却放诗人赋小孤。"]},{"t":"题画","f":"七言绝句","c":["扁舟风水弄残春，画里江南恐未真。","不见当年何竹鹤，山青云白正愁人。"]},{"t":"辛丒下第还重过开利寺","f":"七言绝句","c":["奔走尘途已半年，扁舟重系寺门前。","分明记得离家日，古殿寒灯月满天。"]},{"t":"哭亡儿德孙","f":"七言绝句","c":["哭儿泪尽眼将枯，忽忆儿名又误呼。","灯影隔帘明月落，断肠愁杀树头乌。"]},{"t":"和储静夫","f":"七言绝句","c":["宦途回首各风烟，浪说春江有渡船。","珍重寄书千里意，高秋一雁落云边。"]},{"t":"食角黍怀古","f":"七言绝句","c":["湘江千里碧连天，绿遍芳洲草似烟。","餐尽落英人不见，青芦包黍自年年。"]},{"t":"过湖","f":"七言绝句","c":["两洲相对五丈许，十里湾湾下湖水。","借问舟人谁所为，年年水落长如此。"]},{"t":"谢巡按使来问疾且惠米","f":"七言绝句","c":["藜杖无如病足何，山中书枕两旬多。","廪人忽致霜台贶，饭罢鱼羹一放歌。"]},{"t":"观松雪书渊明饮酒诗","f":"七言绝句","c":["墨花春洒水晶宫，漫写陶诗岂醉中。","莫道柴桑非我地，笔端真有晋人风。"]},{"t":"奉次涯翁老师惠内法酒","f":"七言绝句","c":["黄封瓮上又加封，珍赐由来出上供。","我愿慈颜如此酒，一番春色一番浓。"]},{"t":"寄莫如山二首 其一","f":"七言绝句","c":["八月风吹汉水槎，江东回首更思家。","南沙亭上人如玉，赋罢清秋菊有华。"]},{"t":"寄莫如山二首 其二","f":"七言绝句","c":["亭倚南沙石作山，凤凰巢处竹斑斑。","执经时有门人到，万卷楼中不闭关。"]},{"t":"小舟","f":"七言绝句","c":["东海西陲震泽东，杏花雨过藕花风。","世间多少江湖险，不到蓬窗午梦中。"]},{"t":"与客谈竹茶炉二首 其一","f":"七言绝句","c":["松下煎茶试古垆，涛声隐隐起风湖。","老僧妙思禅机外，烧尽山泉竹未枯。"]},{"t":"与客谈竹茶炉二首 其二","f":"七言绝句","c":["彭泽无弦浪抚琴，琅琊山水醉翁心。","漫将垆火论茶味，云隐松庵午梦深。"]},{"t":"谢浦文玉送黄雀及蟹","f":"七言绝句","c":["芦花风送稻花香，湖上秋来味故长。","黄雀能黄蟹能紫，不知何地更鲈乡。"]},{"t":"雨中偶成","f":"七言绝句","c":["午听浪浪晚未休，萧然六月忽如秋。","东曹吏散文书静，閒对阶除看水流。"]},{"t":"为华汝德题画二首 其一","f":"七言绝句","c":["小桥南北总春风，多少诗情杖屦中。","高阁卷帘还坐我，天涯芳草更无穷。"]},{"t":"为华汝德题画二首 其二","f":"七言绝句","c":["山中云起不知山，坐听流泉尽日閒。","短壑青松凉似水，却疑天上在人间。"]},{"t":"奉和西涯先生春日书怀二绝 其一","f":"七言绝句","c":["游人竞逐赏花辰，却有西堂独卧身。","江草江花春梦外，题诗聊遣梦中春。"]},{"t":"奉和西涯先生春日书怀二绝 其二","f":"七言绝句","c":["江南春雨慰田家，夏雨如春免踏车。","梦到江南心亦到，不知春在紫薇花。"]},{"t":"云溪卷","f":"七言绝句","c":["半为溪水半为云，元是山中一气分。","莫道无心时出岫，沧浪歌似有心闻。"]},{"t":"过冯公岭","f":"七言绝句","c":["衣湿才知马入云，隔峰人语半相闻。","前行共指桃花砦，巨石如碑不见文。"]},{"t":"将至安仁秦择之来迓","f":"七言绝句","c":["沧浪水清濯我缨，隔江如听棹歌声。","故人相见笑相问，一夜月明三载情。"]},{"t":"将至广信寄娄诚善 其一","f":"七言绝句","c":["二月书来自蔡登，南楼病榻几青灯。","灵山雨后明如许，渴思令人一夜增。"]},{"t":"将至广信寄娄诚善 其二","f":"七言绝句","c":["溪晴数日觉滩多，坐听潺湲和棹歌。","却到安流山有月，独吟如此晚凉何。"]},{"t":"都昌瞻陶母像","f":"七言绝句","c":["穷巷欣来长者车，淹留深愧食无鱼。","青丝一缕并刀下，挽得中原九鼎馀。"]},{"t":"泊储潭","f":"七言绝句","c":["储潭庙前春水深，春云带雨昼阴阴。","撞钟击鼓礼神去，一十八滩行路心。"]},{"t":"花石潭阻雨","f":"七言绝句","c":["南方多雨北多风，风雨多时各恼公。","二十年来南北路，几回风雨忆江东。"]},{"t":"明妃辞","f":"古风","c":["妾行入毡帐，宠爱非汉宫。","妾心有恨，千古无终穷。","妾生汉宫人，妾死汉陵土。","君王不知妾，妾心良独苦。","去有路，还无期。","君命妾，焉逃之。","我思古人非我时。","我恨娄奉春，不恨毛画师。"]},{"t":"铜槃谣","f":"楚辞体","c":["铜槃古色如碧石，泉水清清石子白。","我方苦热坐南风，童子持来置前席。","手弄石子兮水生波，击铜槃兮发清歌，炎威焚如如我何。"]},{"t":"伊葛叹","f":"古风","c":["汉鼎三分，汤七十里。","莘野辍耕，卧龙亦起。","夫何为乎，殷兴刘圮。","有臣无君，犹君无臣。","玄德非天，锡彼禅乎复何人。","出师二表徒为陈。","伊邪葛邪，伯仲皆天民。"]},{"t":"采芝曲","f":"五言古诗","c":["采芝复采芝，避秦不避刘。","山中壮且老，幸见兵戈休。","亦闻张子房，苦为天下谋。","垂死得一见，况从仁者游。","归欤返吾所，已矣吾何求。","行过首阳岭，下有两荒邱。","再拜谢夷齐，吾道非公俦。"]},{"t":"以梅溪集赠浦文玉","f":"五言律诗","c":["赠君一编书，作者古君子。","书中何所云，君行自知此。","雪寒冰载涂，依依别桑梓。","高天望羽仪，一日千万里。"]},{"t":"双松图","f":"五言律诗","c":["托根共山谷，贞德元不孤。","天声自相和，泠然觉迷涂。","烟云日往来，映此古貌臞。","尚友千载人，贤哉二大夫。"]},{"t":"赠顾少参与成","f":"五言古诗","c":["病馀羡人健，如人视神仙。","焚香坐长日，帘阁薰风前。","闻君钱塘行，想望潮海天。","湖船弄烟水，旧事今几年。","君行吴山重，壮观归新篇。","秋清力当健，我亦观吾泉。"]},{"t":"谢人送菊","f":"五言古诗","c":["北风晚飕飕，寒香入我屋。","问渠何方来，嘉园慧山麓。","山人为华谋，如邻意先卜。","谓我城中居，萧然数竿竹。","主人抱秋怀，须尔媚幽独。","尔华烂如金，我竹森如玉。","微醉和陶吟，临风有馀馥。"]},{"t":"芟笋于园","f":"古风","c":["戒仆成章长怀采，伏灵灯夜及松霁。","山中无经纶，幽事亦可意。","雨馀竹有萌，头角日以锐。","佳报得山人，玉汝勤我计。","芟繁载筠笼，两童不胜舁。","新稍复何如，双松与兄弟。"]},{"t":"赠吴山人","f":"五言古诗","c":["渊明酒以逃，陆羽乃茶癖。","千载两高人，同心不同迹。","山人鸿渐流，有具随我适。","采新试名泉，吾山屡为客。","水火自成功，居然得真液。","细啜对山僧，永此风月夕。","山人竹为垆，曾赏王友石。","九原谁起之，邀君共坛席。","泉流茗复春，山人眼长碧。","我歌柴桑词，把酒一浮白。"]},{"t":"鹤饥","f":"五言古诗","c":["鹤饥不啄溷，长鸣振林柯。","主人自谋道，粟贵如尔何。","野老馈麰麦，升斗云已多。","呼鹤就庭沼，饮之以清波。","汝寿未易量，无为叹蹉跎。"]},{"t":"观荷永言 其一","f":"五言绝句","c":["凿池种荷花，东引冉泾水。","辟如筑堂坛，于焉待君子。"]},{"t":"观荷永言 其二","f":"五言绝句","c":["南风动清漪，正好看花时。","君子有难进，花开故迟迟。"]},{"t":"观荷永言 其三","f":"五言绝句","c":["花开淡有姿，有香亦清远。","可望不可亲，时舒复时卷。"]},{"t":"观荷永言 其四","f":"五言绝句","c":["夕坐当花前，怀人思悠然。","玉井起作者，诗成已千年。"]},{"t":"种蒲于稿菌之上","f":"五言古诗","c":["山中有野人，故出三秀族。","胡然朝暮姿，乃梦长生箓。","涧边有仙灵，九节碧如玉。","偶就山人居，清贞两无歇。","久要见平生，虚心愿为谷。","匪石良自知，馀子真碌碌。","薰风梅雨馀，仙衣动新绿。","浮游水中央，千春隔尘俗。"]},{"t":"咏铜槃水石","f":"五言古诗","c":["东坡得怪石，远寄僧供佛。","我石乃不然，作我斋中物。","我有古铜槃，俗事久相屈。","以石贮其中，载挹泉滭沸。","朱碧照清波，古色一何蔚。","吾斋本幽贞，复此为除祓。","弄丸思古人，敢谓能髣髴。","白日生高寒，长夏破烦郁。","我心非佛心，万事惟四勿。","水止石无为，匀圆亦强倔。","歌罢一掀髯，南风正披拂。"]},{"t":"夏日书事 其一","f":"五言绝句","c":["清泉浸白石，瑩在古铜槃。","铜槃照眼碧，赤日生高寒。"]},{"t":"夏日书事 其二","f":"五言绝句","c":["铜槃色朱绿，石子白如玉。","客从山中来，挹我泉一掬。"]},{"t":"为杨元平题画","f":"五言律诗","c":["秋华澹有姿，有香亦堪佩。","若当春风时，为兰复为蕙。","悠然山泽间，金紫岂不贵。","石丈有新盟，南山正相对。"]},{"t":"寄寿秦一诚","f":"五言古诗","c":["昔年有奇士，遇子金陵中。","授子长生诀，玄谈入洪濛。","相期以无期，有地还相逢。","尔来四十年，閒居仰遐风。","大耋忽复届，绿发双青瞳。","可望不可即，渺如湖上峰。","我生晚习隐，谢病东山东。","静虚拙乃逸，梦见濂溪翁。","遥将惠泉水，从子巢云松。"]},{"t":"赠刘衢州","f":"五言古诗","c":["数里衢东郭，望望清献祠。","愿言舣君棹，载诵东坡碑。","赵子不可作，江水清涟漪。","焚香伫清夜，矢心亦陈词。","琴亡古调存，鹤去归何时。","吊古有馀感，吾心自吾师。"]},{"t":"三一亭诗为俞吏科作","f":"五言古诗","c":["暇登西冈亭，我怀栾共子。","有言感予衷，千载犹仰止。","生三事之一，谁能不由此。","出为升堂由，入为趋庭鲤。","廊庙复江湖，苍生共忧喜。","俯仰天地间，念念何时已。","所不尽吾心，有如此溪水。"]},{"t":"送顾台州","f":"五言古诗","c":["君从西南来，复向东南去。","会稽望九疑，愁云蔽江渚。","禹穴阒无声，欲与神灵语。","台州海冥冥，金城独高据。","双旌动文星，共识君来处。","君来何所将，东风共时雨。","寄语台州人，君归愿无遽。"]},{"t":"见松子","f":"五言古诗","c":["手种双松树，直我庭前楹。","一年松花开，三年松子生。","松子初辞花，青青复青青。","日看日渐长，匀圆自天生。","一粒成一树，森然遍郊坰。"]},{"t":"和浦文玉观水 其二","f":"五言律诗","c":["仁人解忧时，智者爱观水。","具区接三江，云涛故如此。","浩荡千古怀，长啸江湖里。","载酌山下泉，从吾者谁子。"]},{"t":"和浦文玉观水 其三","f":"五言律诗","c":["篝灯照伏灵，明月淡如水。","风从松顶来，古乐安置此。","山空夜气清，僧龛白云里。","稍伺秋雨馀，还期采松子。"]},{"t":"荅顾与成","f":"五言古诗","c":["九日缺登山，南郊我行独。","缅怀谪仙人，秋声北窗竹。","世事吾不闻，吾道卷堪匊。","碌碌朝市间，他年亦干禄。","风帽倚斜晖，霜钟应虚谷。","千古沧洲情，江天起群鹜。","白酒本无情，偏许陶巾漉。"]},{"t":"与成过我论诗再用前韵","f":"五言古诗","c":["南山多白云，日我媚幽独。","杖藜或西山，凉阴梦风竹。","渴思山下泉，迤逦手自匊。","原田黍稷馨，饥鹤如得禄。","行歌聃史篇，我亦愿为谷。","湖天明晚霞，何心共飞鹜。","有客似醇醪，饮我不须漉。"]},{"t":"与成与与新复至","f":"五言古诗","c":["今辰复何辰，二妙来不独。","短刺方在门，清风已深竹。","袖中有珠玑，投我忽盈匊。","伯仲皆文星，胡不照天禄。","城居自山林，足音喜空谷。","相送冉泾涯，云洲起双鹜。","回首见游鱼，寒潭净如漉。"]},{"t":"荅浦文玉惠莲房","f":"五言古诗","c":["盈盈水上华，垂垂露中实。","数应经天星，不止摽梅七。","虚传周董饴，真尝楚萍蜜。","置之萱草间，吾亲何固必。","珍重泛清泠，荐以雕盘漆。"]},{"t":"又荅文玉 其一","f":"五言古诗","c":["君子哉若人，千古此声实。","玉如丸复丸，初筮得阳七。","苦心中自藏，有房不营蜜。","尚友濂溪翁，泛交亦何必。","坐我小耶溪，相看眼如漆。"]},{"t":"又荅文玉 其二","f":"五言古诗","c":["根拨幸知花，自谓将食实。","高才迥绝尘，名先建安七。","清甘入人脾，霜馀啖新蜜。","袖然首王廷，天定真可必。","礼乐三千言，纵横墨如漆。"]},{"t":"又荅文玉 其三","f":"五言古诗","c":["无才甘退藏，观颐自求实。","吾道负苍生，敢拟作者七。","月夜照松苓，霜秋割崖蜜。","莲房自君投，知味我应必。","报君此山泉，无劳问胶漆。"]},{"t":"晚坐有怀","f":"古风","c":["新雨晴，新月明，道人移坐临前庭。","东邻偶有琅璈声，墙西双鹤相和鸣。","欣然起步春衣轻，石子阶边莎草生。","松花欲黄蒲叶青，可人不来空复情。"]},{"t":"题画","f":"七言律诗","c":["江上春潮晚来恶，水气冥冥接篱落。","忽看此景如此图，却怪当年何竹鹤。","天风吹云山雨收，明日焉知不如昨。","蓉湖望眼尽鄱湖，几向东冈坐高阁。"]},{"t":"我冠","f":"古风","c":["生我冠，死我冠，我冠不毁我璧完。","于嗟乎公乃盖棺，给孤寺中白骨寒。","蜀道难于天，臣心有如铁。","生前未致尉陀书，死后空还苏武节。","于嗟兹游亦奇绝，万古清风一秦越。"]},{"t":"志孝诗","f":"古风","c":["人谓坟可迁，我无买山钱。","水不可虞，涧道可易。","我有只手，不可转石。","石可转，知何时。","我弗是图，安用我为。","我自钳，矢山鬼。","我图不能有如水。","生无期，死有子。","钳不释生终释死。"]},{"t":"有客赠传神张泽民","f":"古风","c":["有客来从东海湄，笔弄丹青自得师。","囊中二像示我亦草草，我于斯人如见之。","溪翁本丰颔，匏翁故多髭。","有神乃在髭颔外，予尝得之朝省委蛇时，客之此艺何太奇。","客言我先祖，曾荷文皇知。","百年貌得几名士，至今海内声犹驰，不才方愧裘与箕。","今予为亲归，早卧江南野。","有形未能图，有影何须写。","君今传我神，谁谓非我者。","君归海上超世尘，应将此纸持示人。","寻常倘有知我者，谓我今吾真未真。"]},{"t":"寄题黄鹤楼","f":"七言古诗","c":["片云不向琴台泊，鹗渚飞来共黄鹤。","黄鹤千年尚未归，惟见高楼倚寥廓。","有矶巀嵲非人凿，矶上临观何绎络。","长史杯缘庾老停，谪仙笔为崔郎阁。","内方迤逦大别峰，远树中开夏后宫。","朝宗江汉直趋海，天津地脉应流通。","登高能赋亦馀事，天子有使将观风。","西涯老作动千古，白首载歌还沈翁。","都台驻节吾乡彦，五十功名犹未半。","不转常持匪石心，无涯每出如流翰。","匡庐云隐具区涛，我放扁舟君不见。","清秋贻我洞庭歌，手墨新题溢缄面。","君诗原是杜中人，吏在汉廷称老练。","冯君莫向栋边悬，恐露精光射星汉。"]},{"t":"七曲湾足旧句","f":"古风","c":["七曲湾，七曲湾，邵家亭子面西山。","亭荒久矣山长在，一百馀年俯仰间。","吾亭今复此，不见鹤飞还。","见山如见古人颜，青青千万古，来往白云閒。","策杖临流水，重歌七曲湾。"]},{"t":"思萱为吴太学辂作","f":"七言古诗","c":["伊昔母在萱正华，儿呼母应春满家。","而今见花不见母，家道犹春儿独苦。","苦心对花花亦愁，恸哭披图春复秋。"]},{"t":"潘氏两寿歌","f":"古风","c":["伯翁九十常登山，城中策杖犹等閒。","仲翁七十不觉老，笑谈出口人绝倒。","两翁本是神仙流，青囊传世真箕裘。","二十年前古稀酒，伯翁杯落仲翁手。","小山雨露年年春，庭前已有折桂人。","先人种德如种树，蜡梅花放春佳处。","从今准拟开寿筵，千二百年如一年。","君不见兄酬弟劝歌且祝，玉林季弟诗如玉。","九峰书院歌涯翁，先生为孙司徒作。"]},{"t":"九峰书院歌","f":"七言古诗","c":["司徒归欤秋月九，江上寻山历厖糺。","九峰何在郢城西，此景更无他处有。","谁将群物名飞走，取类应出前人口。","为鸡为马为象狮，指点相呼故非偶。","乌岭焦山自色形，远为神仙近慈母。","方床若为野人悬，断舸不劳津吏守。","公心好静复好奇，孰谓伤廉本无取。","书堂清敞据中区，曲径烟萝舒复纽。","云开画障当南荣，泉送琴声入西牖。","别来想像三十年，清梦几回诗几首。","鉴湖不用乞新恩，故物今还落公手。","九峰髣髴在壶中，一笑春风共醇酒。","谢安卧不负东山，杜甫望常依北斗。","携满青囊采药多，坐温白石观棋久。","香山老者复何人，此老此峰皆寿耇。","涯翁大作合磨崖，为问山灵汝知否。"]},{"t":"谢徐员外送石子歌","f":"古风","c":["秋官西来自三衢，赠我石子舁十夫。","问渠安所收拾此，急水滩头激浪馀。","君何太劳我太迂，谁知古意皆可书。","世间奇货玉与珠，我独爱此珠玉如。","君看磊磊复落落，长短圆方不须凿。","万壑千岩雨送来，沙与揩磨波与濯。","皎然洁素蔚然青，夏造殷因亦惟错。","寻常碌碌未足论，顾我一卷方华岳。","我行两浙西复东，布帆几飏严滩风。","一罂置此二三子，澄清激浊胶无功。","而今万辈皆我润，润泽不与他山同。","便将罗列阶左右，朝夕相看作良友，坦然函丈坚且久。","君不见一番雨洗一番明，中涵云气上应星。"]},{"t":"宝萱堂歌为华文远作","f":"古风","c":["宝萱堂前春酒香，东风吹花初日长。","诸郎将儿寿寿母，宾阶有客森成行。","具区西来入海去，流到鹅湖未能遽。","乾坤汇泽同馀波，正似君家庆钟处。","君不见宜男有种春无涯，一年一觞如此花。"]},{"t":"焦山歌","f":"楚辞体","c":["焦山古称浮玉山，乃在南徐东北江波之间。","长江西来万馀里，地将到海天为关。","金山古金鳌，与此相伯仲。","高通鸟道两崔嵬，深入龙宫一空洞。","壮哉大观乾坤中，沧溟有际天无穷。","吐吞兮星日，呼吸兮风云，有时变怪起雷雨，满盈之动成晦蒙。","上观北斗定天极，下指地势惟兹水上之双峰。","吾尝济瓜州、弭京口，鼓楫中流屡回首。","仙翁招我上金山，指点焦山引杯酒。","君不见百川四渎先江河，安流争似惊涛多。","中河底柱复碣石，江山非此如此逝者何。","子登台，我歌此，吾道茫茫正如水。"]},{"t":"青山歌","f":"古风","c":["吾闻太湖之上郡山丛，参差一碧皆摩空。","兹山乃独擅名字，两洞庭北夫椒东。","南条西来几经络，东将到海还盘薄。","左旋右引真有情，古色疑从天上落。","望湖亭如一巢小，万顷烟涛连树杪。","七十二峰名者谁，今古兴亡云杳杳。","援琴曾和桓山歌，断碑破冢如予何。","振衣独上最高处，沧浪调远清风多。","旧诏归来病新起，拭目江湖千万里。","丹邱信有在人间，兹山兹山无乃是。","老僧报我山花春，题诗为报山中人。","它日歌词已陈迹，谓君再拂湖边石。","吾尝一题少室三匡庐，不知山灵谓我今何如。"]},{"t":"谢莫如山惠菖蒲歌","f":"古风","c":["我有二奇石，来自上下钟。","是时我行自南复之东，二物真相从。","楼船习习生清风，迩来数年委置庭草丛。","新春有客赠我石，其数与物皆相同，问之云来自蜀中。","殊形异状不可以模写，大抵荒崖绝壁自天生质非一日，复有长江之水朝夕相撞舂。","其间岁月不知几千百，乃成造化之神功。","东坡雪浪何似者，吾此四物无乃堪弟兄。","有客谓予言，此石置之盆，可种九节仙灵草。","南沙偶来观，谓客言诚好，我将致之时尚早。","早闻扣门声，一童手持抱。","即令童子洗石分种之，如送仙人上蓬岛。","走笔谢南沙，清贞愿相保。","世上琼瑶何足宝。"]},{"t":"中秋客歌东庐至邀南沙","f":"古风","c":["今夕中秋月有华，古奇石下有幽花。","惠山泉水荆溪茶，酒名且出仙坛麻。","客皆能赋无喧哗。","南沙未来东庐去，抗手掉头不肯住。","兴在王猷放舟处，雪月皆堪入诗句。","东庐去后南沙来，草堂独对秋星开。","晚云冉冉生苍苔，我行中庭往复回。","鹤声报客慰我怀，海月东生酒在杯。","亦有澜庵在我斋，今夕不乐何为哉。","我题诗，如作史。","明日挥毫二三纸，东报东庐公，南报南沙子。"]},{"t":"天趣园十景歌","f":"七言古诗","c":["石壁巉岩天斲成，一屏万古长青青。","萧园卜邻得正直，谁谓与立天无情。","磐石坦然在平地，四望烟霞以为际。","数人共坐尚有馀，下布莓苔作文罽。","原泉混混何处来，白虹委地声鸣雷。","水哉有本故如是，清泠未受人间埃。","曲水流随石渠曲，曲曲春风动新渌，觞泛兰亭客如玉。","方池水亦潴为方，汪洋数顷涵天光。","昔人曾赋半亩塘，今也有客歌沧浪。","水碓有机非作巧，终古周旋曾未了。","寻常成物不言劳，更复何心较多少。","钓矶垂钓者何人，千秋再睹磻溪春。","水清见石鱼可数，旁有閒地堪经纶。","丹穴于今亦何有，有窟如屋大于斗。","垆鼎已亡存杵臼，应是山灵为诃守。","漱清轩外水涟漪，仰高亭前山崛奇。","丹青尽物不尽意，意在地官南望时。"]},{"t":"蓉溪书屋歌","f":"古风","c":["绵州城东结书屋，秋晚芙蓉花簇簇。","主人他日一归来，手检牙签三万轴。","花谢花开清梦遥，主人执法立中朝。","门前不植渊明柳，观里曾歌禹锡桃。","主人怀思客赋诗，此是诸郎擢第时。","西曹法吏春秋笔，东阁儒臣雅颂词。","君不见剑阁巉岩去天近，左右峰峦相控引，回首蓉溪云隐隐。"]},{"t":"松棚歌奉次涯翁先生","f":"楚辞体","c":["涯翁壮游尽南东，品题到处皆留踪。","老閒逸事情亦钟，笔底云气成巃嵷。","乾坤奇观此卷中，有歌落落称棚松。","眼前烟雾如郁葱，野无夏屋胡为幪。","胡不梁柱明光宫，君子若人能固穷。","周旋地占五十弓，脱去尘土将腾空。","上辞鹳鹤下蛇虫，天留奇崛当严冬。","实看纠结虚玲珑，蟠根定与东海通。","不然何以游群龙，在渊在陆天机同。","多言莫如图画工，神品妙得吟哦功。","使君骢马缨垂红，偶入野寺披蒙茸。","閒将手剔古苔封，行遍天涯亡是公。","几回世上儿成翁，青云后拥风前冲。","工师过眼徒憧憧，岂复斤斧遭樵童。","松兮如鸟已出笼，时来贵客僧鸣钟。","寻常曲直嗟麻蓬，谁将此物惊盲聋。","涯翁诗成五色虹，突然平地起危峰。","南来吏牍兼诗筒，知音千里如相逢，雅哉淇澳非卫风。"]},{"t":"水北山庄图歌","f":"七言古诗","c":["近来善学孟端画，眼中吾许张临湘。","临湘病后作此幅，树色惨淡山苍苍。","水北山人好事者，要我题诗惠泉下。","秋林逝矣不可招，临湘临湘亦其亚。","菊有黄华夜榻深，长吟偶坐吾玉林。","樽前击节与未已，谁能和以无弦琴。","听松庵里庐山壁，少日相看眼双碧。","酒酣且作山人歌，莫向山僧问畴昔。"]},{"t":"金山行送林提学之山西","f":"楚辞体","c":["大江之中，有峰崔嵬。","屹然独立不可动，百川到此皆萦回。","乾坤风气，与水相移推。","来今往古无断续，中间有阖复有开。","顺流直泻忽此突然者，俨如玄圭锡禹戴履参三才。","吾闻岷山导江，东沱北汇，茫然两涯。","瞿塘谁为峡，滟滪谁为堆。","洞庭东去小孤小，又东千里行绕凤凰之高台。","南徐望海只尺是青天，如宇置此坳堂杯。","兹峰非柱亦非碣，清泠隔绝人间埃。","神宫佛刹半参倚，唐镌宋刻剥落生莓苔。","蛟龙隐盘窟，鸾鹄栖悬崖。","上摩苍茫下临空洞兮，不可以测度，但见海有西户江有东南隈。","一山二水理应尔，嗟此卷石直从何地天将来。","水神夜戒百灵护，万骑驱逐疾走如衔枚。","吁嗟乎，尾闾去终日，昆崙几时回。","振陵风雨潮汐争喧豗。","大哉吾道一逝者，夫何为乎有澜日倒波今颓。","若非藉此作孤障，彼狂且悍将谁与之裁。","吾人定力如此石，沧桑不变此石无倾隤。","送君须上最高处，商声击石开君怀。","太行绝顶更回首，一航东海何如哉。"]},{"t":"貘皮行","f":"古风","c":["客从巴东至，遗我一兽皮。","观之非虎非熊罴，三十年前尝见之。","貘哉貘哉古白泽，蜀中诸山多窟宅。","嚼铁复吞铜，他物更何择。","独出不知云雾深，狂奔但恨林原窄。","辟邪亦袪湿，此语自古闻，今夕何夕来吾门。","貘乎貘乎汝诚武，吾将高坐论斯文。"]},{"t":"容春轩六咏 其一 瞻尼坛","f":"五言绝句","c":["画里瞻尼父，庭前即杏坛。","春风吹绿树，真作泗滨看。"]},{"t":"容春轩六咏 其二 拟渠井","f":"五言绝句","c":["横渠复古心，纸上聊云尔。","我画我中庭，亦复横渠纸。"]},{"t":"容春轩六咏 其三 先春台","f":"五言绝句","c":["两树分红白，同然见复心。","开花还结子，吾道古犹今。"]},{"t":"容春轩六咏 其四 晚秋圃","f":"五言绝句","c":["秋菊有黄花，有朱亦有素。","靖节醉东篱，为识花心故。"]},{"t":"容春轩六咏 其五 鼋峰庭","f":"五言绝句","c":["万古水中山，一峰山下石。","古貌独苍然，不受风涛蚀。"]},{"t":"容春轩六咏 其六 钟石沼","f":"五言绝句","c":["石钟以声名，无声安取此。","风水月明中，我忆东坡子。"]},{"t":"题扇赠赵宅之","f":"五言绝句","c":["苦热思高眺，王孙胜有楼。","城阴连塔影，山月入溪流。"]},{"t":"显上人送茶题扇荅之","f":"五言绝句","c":["祛暑方静坐，茶来清我心。","铜槃小泉石，绿树一堂深。"]},{"t":"闻歌 其一","f":"五言绝句","c":["久不闻山歌，南风五月多。","牧童呼伴侣，吹笛下西坡。"]},{"t":"闻歌 其二","f":"五言绝句","c":["久不闻水歌，溪上夜如何。","一声长复短，隐隐度烟波。"]},{"t":"书国臣扇","f":"五言绝句","c":["有物能生风，如云起太空。","飒然凉似水，人在玉堂中。"]},{"t":"题国英扇","f":"五言绝句","c":["看竹不问主，听松还对僧。","山中春欲暮，此兴复谁曾。"]},{"t":"得月为星士作","f":"五言绝句","c":["与客讲虚中，明月照我怀。","怀中亦有月，元从天上来。"]},{"t":"题琴泉","f":"五言绝句","c":["手弄朱丝弦，音从太古传。","山中无和者，幽涧落寒泉。"]},{"t":"伯川以生日诗来口占代柬","f":"五言绝句","c":["谢客不谢诗，谢诗应太俗。","笑舞老莱衣，高歌对慈竹。"]},{"t":"中秋日许东庐过我至晚乃固辞去口占一绝","f":"五言绝句","c":["君因赏月来，赏心不赏月。","一夜冉泾船，千古王猷雪。"]},{"t":"为张云邱题画用其韵","f":"五言绝句","c":["梦里诗情远，閒中笔力长。","云邱本孤绝，更爱竹风凉。"]},{"t":"知微病口占问之","f":"五言绝句","c":["秋雨山僧病，经旬我不来。","夜来来老圃，报我桂花开。"]},{"t":"赠吴鹰扬","f":"五言绝句","c":["湖上初逢地，城中再会年。","白头今老矣，青眼故依然。"]},{"t":"寒日斋居次见素公韵","f":"五言律诗","c":["供茶须地栗，和药谢天麻。","山鸟投风树，江鸥避雪沙。","近招醪饮薄，远劄绢封斜。","深巷临泾曲，弦歌自一家。"]},{"t":"送李白夫","f":"五言律诗","c":["他日兰溪上，相知尚未深。","东山千里梦，南国两年心。","长路看孤剑，高枝待上林。","朱弦寥落久，三叹对希音。"]},{"t":"祠山庙火诗以吊之兼慰孔道士","f":"五言律诗","c":["古庙前朝建，咸淳纪在碑。","千金未足惜，一火竟堪悲。","回禄增邻戒，嘉平罢里祠。","羽人愁且病，风雨夜何其。"]},{"t":"送浦文玉会试","f":"五言律诗","c":["雪色照行李，江帆影碧空。","壮怀离别外，长策对扬中。","风转扶摇上，星回斗柄东。","济时公等在，吾道付冥鸿。"]},{"t":"送刘介夫四川提学","f":"五言律诗","c":["蜀道兵戈后，君行为作人。","冬深方度腊，江远故从岷。","钟鼓堂坛曙，旌旗道路春。","锦川明似镜，天与照风神。"]},{"t":"慈寿为林镇江赋","f":"五言律诗","c":["名郡临江表，思归未得归。","遥持扬子水，剧舞老莱衣。","秋壁寒逾峻，春阳远更晖。","徵黄仍汉典，重诰到慈闱。"]},{"t":"元日试笔荅浦文玉","f":"五言律诗","c":["轻著风吹柳，深将雨裛花。","诗筒春有草，砚滴海无涯。","历纪还元日，车书正一家。","晴洲堪共眺，新水荻生芽。"]},{"t":"明日叠前韵","f":"五言律诗","c":["秀句传新岁，应知笔梦花。","昏初回斗柄，春已遍天涯。","有客真徐孺，多书岂邺家。","朝来看草色，隐隐在根芽。"]},{"t":"东庐见过","f":"五言律诗","c":["客从寒日至，下榻对梅花。","它夜月千里，伊人水一涯。","病怀违酒社，老兴托诗家。","再过须为约，春茶渐有芽。"]},{"t":"又用韵柬南沙","f":"五言律诗","c":["有风门独掩，寒径久无花。","客舫维城角，吾庐傍水涯。","閒将寻奕者，静复谢禅家。","茗碗何堪供，山童掘笋芽。"]},{"t":"送陈严州嘉言","f":"五言律诗","c":["旧守持新节，江边问睦州。","春星观雨驾，秋水济川舟。","风濑迎驺骑，云山带驿楼。","范公公所慕，到处得追游。"]},{"t":"赠余鸿宾","f":"五言律诗","c":["晚领儒官檄，真成阙里游。","诸生今复鲁，吾道故从周。","冻雨随春作，凉云接海浮。","古松看挺拔，应待栋梁求。"]},{"t":"文玉送双莲有诗将之次韵为荅 其一","f":"五言律诗","c":["水国秋风早，双莲若为携。","对时占举首，观物兴思齐。","茹苦辞熊胆，行空信马蹄。","相看清露溢，仙掌不须梯。"]},{"t":"文玉送双莲有诗将之次韵为荅 其二","f":"五言律诗","c":["投我清心物，筠笼故故携。","如闻歌和越，真解味忘齐。","甘露分松顶，香风逐骏蹄。","高登餐沆瀣，从此是阶梯。"]},{"t":"秋莲走笔荅文玉","f":"五言律诗","c":["秋莲如晚子，应有物持携。","双玉价难并，群珠数已齐。","色鲜浮露羽，香远逐风蹄。","太液九天上，朝来何处梯。"]},{"t":"谢生荔次友人","f":"五言律诗","c":["有客传闽荔，怀君我更携。","时和成地胜，物论待人齐。","蜜荐连龙眼，尘封谢马蹄。","因思南极贡，航海复山梯。"]},{"t":"闻东所讣","f":"五言律诗","c":["东所不可作，其如海月何。","百年清静坐，一日激昂歌。","夜雨梅山道，春风赣水波。","白沙遗像在，老泪欲滂沱。"]},{"t":"送李司训","f":"五言律诗","c":["九载成贤日，超迁在此行。","飞龙重睹象，鸣鹿屡闻声。","雨露春方早，江湖晚更晴。","东山读书处，回首有馀情。"]},{"t":"菊花庄一首寄吴宪使","f":"五言律诗","c":["东篱千古意，今在野桥东。","乘兴者何客，忘机有此翁。","关河雄镇后，风雨醉吟中。","我亦开吾径，秋来得几丛。"]},{"t":"述事用澹成韵","f":"五言律诗","c":["世事弦歌外，吾庐揖让中。","竹深云冉冉，苔滑径重重。","我独观生理，人徒问坐功。","秋深苦多雨，真欲讼云龙。"]},{"t":"再用韵荅文玉兼赏佳句 其一","f":"五言律诗","c":["秋月将弦夜，林居自老身。","社无邀酒地，里有和诗人。","照隐看悬鉴，穷玄拟驾轮。","一明千里共，爱子笔如神。"]},{"t":"再用韵荅文玉兼赏佳句 其二","f":"五言律诗","c":["诏侍宁亲日，弦歌报主身。","静中真乐地，病后有閒人。","月水双涵镜，风天一转轮。","达观无不可，碌碌恐劳神。"]},{"t":"见新月用前韵","f":"五言律诗","c":["独恨中秋月，年年照病身。","星边槎有客，江上笛何人。","兔影还双杵，蟾光欲半轮。","万峰天柱顶，愁坐正驰神。"]},{"t":"遣夜用前韵","f":"五言律诗","c":["吟遣初长夜，愁将久病身。","地宽吾爱我，天远此怀人。","北共星从极，西生月在轮。","披衣还起坐，无汨是存神。"]},{"t":"荅文玉","f":"五言律诗","c":["诗到谣还步，秋庭落细花。","百年双老眼，一代几名家。","烟径兼疏雨，风溪带浅沙。","不知城郭外，何处更清华。"]},{"t":"再荅文玉","f":"五言律诗","c":["有客题新句，吴笺动墨花。","市桥南北巷，邻屋两三家。","江水初辞峡，溪金故出沙。","病夫饶古意，极力谢浮华。"]},{"t":"分胙馈东庐","f":"五言律诗","c":["病起乾坤大，秋分日夜中。","山花还我径，露草更天风。","膰俎分清庙，诗筒寄野翁。","南楼明月夕，谁与一樽同。"]},{"t":"赠针医罗某","f":"五言律诗","c":["百年江海兴，南粤又东吴。","陈榻还曾否，骞槎信有无。","神功人掷杖，隐计市悬壶。","归到仙岩下，重看五岳图。"]},{"t":"次韵荅顾与成","f":"五言律诗","c":["寺忆重游处，僧房古涧阴。","诗坛曾有意，禅榻本无心。","未敢忘周梦，焉能和越吟。","思君时极目，湖上两云岑。"]},{"t":"次杨支硎题惠山泉韵","f":"五言律诗","c":["公来多逸兴，胜赏独于斯。","水德元无滓，山灵故有知。","泠深方汲绠，瀑远自降旗。","古调谁能和，风湍下石池。"]},{"t":"以云南芥菜送文玉文玉有诗用韵荅之","f":"五言律诗","c":["病起亲畦菜，常怀饭我恩。","有方能入药，无和未成飧。","迹比䲭蹲野，心忘鴳适樊。","慈闱亦知味，吾不愧曾元。"]},{"t":"再荅文玉","f":"五言律诗","c":["殊方传美种，雨露共天恩。","菹已供时荐，羹还劝客飧。","梦基君亦蔡，学圃我应樊。","莫道冰霜地，微阳复起元。"]},{"t":"夜宿华甥夕话斋与许东庐叙旧","f":"五言律诗","c":["坐共青灯榻，真成夕话哉。","暄凉才问昨，晴雨未知来。","腊放诗人笔，春分野老杯。","梅花应识我，相对一徘徊。"]},{"t":"送徐提学","f":"五言律诗","c":["两浙多才地，三年化雨深。","何人悲枥马，有客赋镕金。","歌向胥潮听，书从禹穴寻。","旧游吾所愧，棠树未成阴。"]},{"t":"题扇赠侯刑部用姚少师泉上韵","f":"五言律诗","c":["三日金陵道，江船趁晓开。","泉甘容我住，山重为公来。","石愧元章拜，桑怜著作栽。","冬深初雨雪，春色已盈杯。"]},{"t":"泉上次姚少师","f":"五言律诗","c":["江左此亭古，原泉若为开。","龙嘘山雨动，鱼跃水风来。","菉竹曾闻赋，金莲不见栽。","晋人如可作，此地复流杯。"]},{"t":"宁庵少宗伯见过","f":"五言律诗","c":["病后相逢处，犹疑十载前。","君行当要路，吾道在寒泉。","轩坐风初静，城居地偶偏。","麻姑坛可到，谁共赋游仙。"]},{"t":"送谢景州","f":"五言律诗","c":["财赋南畿郡，文章太学官。","清为舆论重，老觉仕途难。","台斗天何近，沧瀛地本宽。","董祠千载后，再拜肃衣冠。"]},{"t":"元夕过南沙南沙有诗用韵奉荅","f":"五言律诗","c":["月比昨宵昏，阶墀尚有痕。","主人将就榻，童子正敲门。","市上灯初静，斋中席旧温。","阿咸能从我，病力独乘轩。"]},{"t":"以泉寄宁庵将之以诗","f":"五言律诗","c":["星汉孤槎畔，风涛二月前。","不来今雨客，聊寄此山泉。","使出乡关便，家从驿道偏。","曾闻路人语，尘世有登仙。"]},{"t":"薏苡粥次涯翁韵荅张提学","f":"五言律诗","c":["旧是南方物，新从北塞传。","两封何郑重，万颗自匀圆。","入剂堪充使，加餐漫拟仙。","无心成故事，涯老赋诗年。"]},{"t":"雨中怀侯世卿","f":"五言律诗","c":["半月黄梅雨，怀人意独深。","吟长唐省漏，梦远宓堂琴。","活水通泾曲，甘棠散野阴。","泉亭千古胜，留眼共登临。"]},{"t":"叠前韵","f":"五言律诗","c":["不枉河阳驾，东亭草径深。","雨馀方策杖，风至自鸣琴。","病榻忘周梦，郎曹惜禹阴。","未须嗟室远，时有简书临。"]},{"t":"次浦文玉对池荷 其一","f":"五言律诗","c":["超然不见埃，池上见花开。","华岳诗中望，庐峰梦里回。","江湖吾道在，坛席若人来。","逸调难为和，天工自剪裁。"]},{"t":"次浦文玉对池荷 其二","f":"五言律诗","c":["朝露洒炎埃，红渠相映开。","色深从水出，香远遂风回。","华国将移去，怀人幸折来。","江南多旧曲，知是女郎裁。"]},{"t":"读陆民望墓铭","f":"五言律诗","c":["爱君不能荐，深负百年知。","吴越观风地，秦淮步月时。","清脩堪立传，敦厚称为诗。","读罢南沙诔，悽然泪欲垂。"]},{"t":"寿徐封官","f":"五言律诗","c":["老拜封官命，归来发未皤。","巷深尘事少，园小野情多。","久视天终定，初生日又过。","寿君无长语，击节远游歌。"]},{"t":"夜坐怀东庐子","f":"五言律诗","c":["有客经梅里，东庐兴若何。","万寻青壁远，一径绿阴多。","白日羲皇梦，沧浪孺子歌。","新凉且明月，下榻候相过。"]},{"t":"文玉咏吾石次韵荅之","f":"五言律诗","c":["有物元如此，无材柰尔何。","云高千仞小，山静一拳多。","新刻磨崖字，遗声击磬歌。","不须袍与笏，意到即相过。"]},{"t":"春日怀史敏甫","f":"五言律诗","c":["灯夕何须卜，阴晴月在天。","怀君将缩地，别我又经年。","泾上晚独立，梅花春可怜。","惠然如在即，重咏惠山泉。"]},{"t":"慰秦国英哭子","f":"五言律诗","c":["哭子情无极，慰君伤我心。","幽魂青嶂远，老泪碧潭深。","麟趾空占梦，椿庭正惜阴。","荒亭重延伫，天道竟难寻。"]},{"t":"宿知微山房","f":"五言律诗","c":["一宿山中寺，王郎两月情。","榻云春坐煖，窗月夜看晴。","茗供新分水，钟声远隔城。","知微请题画，政及我诗成。"]},{"t":"发文正公吊书后有作 其一","f":"五言律诗","c":["子在心常北，吾归道未南。","书从春后绝，恸岂病馀堪。","诗兴江山老，忧怀岁月酣。","百年函杖地，犹许梦中参。"]},{"t":"发文正公吊书后有作 其二","f":"五言律诗","c":["平生一瓣香，今日托人将。","鸿雁南来少，风尘北望长。","回天曾有笔，济海竟无航。","留得遗文在，星辰夜夜光。"]},{"t":"发文正公吊书后有作 其三","f":"五言律诗","c":["漫识金山酒，公因赏识人。","忧为天下地，笑返雪中春。","山色言增重，泉评意出新。","北行人渐远，愁见水粼粼。"]},{"t":"卢侍御师邵言文正公除夕之梦","f":"五言律诗","c":["梦里题诗处，悠悠万古心。","凤衰吴岳远，竹老楚江深。","南极星方照，西涯月竟沈。","绣衣能语我，歌苦不成音。"]},{"t":"闻钱伯川讣","f":"五言律诗","c":["伯川俄大病，哀甚哭无辞。","未毕慈亲养，空勤圣主期。","湖山春正尔，风雨夜何其。","更忆新亭上，高文记两知。"]},{"t":"雨中写野景","f":"五言律诗","c":["雪应初春少，龙分昨夜灵。","瀑长疑落汉，槎远欲浮星。","沙鸟兼云白，风萍泊岸青。","渔船投酒市，吹笛过前汀。"]},{"t":"雨霁和文玉 其一","f":"五言律诗","c":["雨霁诗初至，朝来鹊有灵。","老农频望岁，野史亦占星。","风水萦新碧，云天露少青。","五湖堪一望，高阁瞰鸥汀。"]},{"t":"雨霁和文玉 其二","f":"五言律诗","c":["霁景还天道，吾诗亦性灵。","槛浮少陵水，堂倚太邱星。","城日低仍白，村烟远更青。","客愁殊未已，云隐隔溪汀。"]},{"t":"雨霁和文玉 其三","f":"五言律诗","c":["连日愁多雨，还谁歌雨灵。","已看船入市，安用驾冲星。","葵掩庭中赤，蒲添石上青。","何时步新月，策杖过沙汀。"]},{"t":"送王同知之处州","f":"五言律诗","c":["伊昔曾游地，今还送故人。","舟横吴浦晚，驾转丽阳春。","山静南无粤，星明北有辰。","不须论展骥，天子重臣邻。"]},{"t":"送杨学正之安陆","f":"五言律诗","c":["老臆吞云梦，于今在眼中。","楚材元有望，湖教故多功。","山色连平野，江流入半空。","谁为三鳣颂，夫子又关东。"]},{"t":"送伍御史汝真之广东","f":"五言律诗","c":["煌煌岭南节，迤逦过江东。","岁月驰驱里，山川感慨中。","有天还北斗，何草不秋风。","如见王宜学，相思道病翁。"]},{"t":"与王子春夜坐","f":"五言律诗","c":["君来下我榻，大热得清风。","夜色高低树，秋声远近蛩。","诗曾惊鹤老，数已动枫翁。","万卷吾堂在，烦君校异同。"]},{"t":"湛空为僧作","f":"五言律诗","c":["京尘如海水，明眼本来空。","折苇流沙北，扶桑断石东。","百年无梦后，万象不言中。","瓜步还西上，庐山问远公。"]},{"t":"夜坐有怀浦文玉","f":"五言律诗","c":["哭子身仍病，怀君我亦伤。","江湖秋欲老，风雨夜初长。","鹤梦芜汀远，蛩声草砌凉。","兼葭空独赋，愁寂不成章。"]},{"t":"寄薛石泉","f":"五言律诗","c":["此叟何如者，山中有石泉。","润生晴谷雨，光动夜潭天。","鉴影空坡老，题名重羽仙。","岁寒吾道在，须记定交年。"]},{"t":"九月一日同诸友行山中 其一","f":"五言律诗","c":["晚秋逢霁景，山寺恣幽寻。","霜树丹犹浅，寒潭碧正深。","竹垆鸿渐茗，松榻颖师琴。","亭上还高眺，悠然万古心。"]},{"t":"九月一日同诸友行山中 其二","f":"五言律诗","c":["龙阜秋云外，微茫径可寻。","鸥情沧渚远，松影白云深。","风逼重阳帽，泉流太古琴。","草亭春色远，犹是浴沂心。"]},{"t":"为潘复轩题画","f":"五言律诗","c":["两山藏古寺，一道泻清泉。","老衲偏知路，高松不计年。","桥通采蘋涧，林起煮茶烟。","更爱王中舍，长谣庐岳篇。"]},{"t":"海洲菊花庄小燕","f":"五言律诗","c":["黄花方对酒，有客复鸣琴。","此老归来兴，今吾病起心。","落英曾物色，疏越自声音。","久熟江头路，桥东更可寻。"]},{"t":"汪司成器之燕二泉精舍器之为予作精舍记先是三日寄至","f":"五言律诗","c":["一杯山馆酒，十载岁寒心。","病起怀君切，文成望我深。","江湖方远历，丘壑且幽寻。","已办题名石，公来始自今。"]},{"t":"除夕感怀","f":"五言律诗","c":["病后逢除夕，灯前感壮心。","梅花万古色，云树一庭阴。","客去仍悬榻，歌成复听琴。","蘧瑗思寡过，千载有知音。"]},{"t":"送秦国瞻赴应天判","f":"五言古诗","c":["南国今丰镐，东郊旧毕陈。","保釐资一德，相恊赖诸臣。","城险瞻维石，江深渡有津。","谒陵真对越，适野极咨询。","汉史闻书凤，周风想赋麟。","转输民力竭，湔涤圣恩新。","牧苑曾归地，乘舆亦济人。","羽仪看筮渐，棠憩听歌豳。","日月光偏近，山川气孔神。","吾贤应妙简，尹伯况同寅。","此日栖鸾地，他年燕鹿宾。","省台虚席在，珍重报君身。"]},{"t":"题余立夫扇次企斋","f":"七言绝句","c":["乞得尘途未老閒，却因多病负看山。","春来拟作吟诗社，一月同君十往还。"]},{"t":"次见素翁送子 其一","f":"七言绝句","c":["雪馀诗到病夫惊，素老丰姿纸上盈。","笑折梅花伴孤咏，海风吹月不胜清。"]},{"t":"次见素翁送子 其二","f":"七言绝句","c":["爱才成癖谓公偏，吐握曾闻古下贤。","嗟我怀人无所报，一罂将汲惠山泉。"]},{"t":"次见素翁送子 其三","f":"七言绝句","c":["劝驾南来雪满山，到吴先慰病中閒。","而翁爱我时飞劄，更有清言在梦间。"]},{"t":"次见素翁送子 其四","f":"七言绝句","c":["庭训看来字字真，老于吟咏转精神。","沧洲吾道平生语，不道苍生望在身。"]},{"t":"次见素翁送子 其五","f":"七言绝句","c":["策名方际风云会，问道须从水陆宜。","山下出泉庭训在，百回千折定东之。"]},{"t":"次见素翁送子 其六","f":"七言绝句","c":["久矣闻君一见之，雪消东渚晚舟移。","百年家学重敷对，臣子孤忠天地知。"]},{"t":"次见素翁送子 其七","f":"七言绝句","c":["用世无能且病身，却劳长者寄书频。","慈闱春酒堪时献，岁有山田亦未贫。"]},{"t":"除夕知微馈泉先是有怀因附之","f":"七言绝句","c":["两罂泉水一童来，向日茅堂午正开。","谩谓清风无可报，雪中诗为寄僧裁。"]},{"t":"睡起偶书 其一","f":"七言绝句","c":["虚堂午热睡不得，听客高吟公甫诗。","诗当好处却恐睡，正是隔帘风动时。"]},{"t":"睡起偶书 其二","f":"七言绝句","c":["人言心静不愁热，凉风不来凉意来。","从今夜夜有月色，更爱草堂南向开。"]},{"t":"春日奉次涯翁老师 其一","f":"七言绝句","c":["独坐心情病后长，已教童子任耕桑。","采新时为高堂献，西自山乡东水乡。"]},{"t":"春日奉次涯翁老师 其二","f":"七言绝句","c":["一枕羲皇午梦长，有诗不敢和柴桑。","燕山青绕今京洛，却指程门望帝乡。"]},{"t":"为华文远题画次顾东江","f":"七言绝句","c":["松枝落落骨栾栾，风动寒泉更好看。","湖上幽居故相近，他年曾此赋斯干。"]},{"t":"即席题扇","f":"七言绝句","c":["同向山中试茗来，松风高阁倚崔嵬。","兴酣别院寻僧去，却爱幽花满路开。"]},{"t":"扑蝶图","f":"七言绝句","c":["花雨初晴日正东，游虫各自领春风。","狂童不识庄生意，漫把閒情逐梦中。"]},{"t":"题竹送李司训","f":"七言绝句","c":["送客将归歌复歌，诸生攀挽欲如何。","竹枝把作松枝赠，岁晚相看思更多。"]},{"t":"灯市追和钱希翁","f":"七言绝句","c":["独向三桥静处行，松棚落落带春星。","城中月是山中月，一有灯光分外清。"]},{"t":"为葛元兆题扇","f":"七言绝句","c":["青藜为杖葛为巾，采采山中百草春。","歌罢紫芝还自和，九峰残日未逢人。"]},{"t":"吴心远惠新茗重以盆蕙走笔谢之","f":"七言绝句","c":["题书正为山翁问，忽报山翁使者来。","坐有香风起何处，山中花在盎中开。"]},{"t":"戏荅许东庐 其一","f":"七言绝句","c":["春晚天涯有所思，诗来刚值落花时。","青青竹笋真如玉，珍重还教棘护篱。"]},{"t":"戏荅许东庐 其二","f":"七言绝句","c":["主人心远客来稀，剥啄声知是也非。","问讯何如还道甫，数行书与一童归。"]},{"t":"夏夜足成春日之句","f":"七言绝句","c":["春风门巷冉泾西，兴到新诗漫自题。","鹏翼顺风沧海梦，桃花流水碧山栖。"]},{"t":"棕蒲 其一","f":"七言绝句","c":["棕榈根老久应捐，漫托昌阳为引年。","露下高天秋涧冷，山中人作水中仙。"]},{"t":"棕蒲 其二","f":"七言绝句","c":["棕本栽蒲故有之，水边石畔斗新奇。","相逢若问通仙否，直待形容变尽时。"]},{"t":"再韵 其一","f":"七言绝句","c":["老朽判为世所捐，定交今喜得青年。","清泉白石非君事，行作蓬莱顶上仙。"]},{"t":"再韵 其二","f":"七言绝句","c":["蓬莱路远未能之，水上枯槎也自奇。","剑佩森森人似玉，群仙初谒太清时。"]},{"t":"次南沙谢菜","f":"七言绝句","c":["敢誇异种出云南，老圃新畦也自堪。","击节有谁知此味，介君能辣白能甘。"]},{"t":"赠周含山","f":"七言绝句","c":["五年佐邑平如水，更有馀功及我泉。","何地含山君莫问，两般疆宇一般天。"]},{"t":"奉次涯翁先生写真 其一","f":"七言绝句","c":["万古勋名百岁身，古人风采在今人。","丹青纵有如神笔，难写胸中一点春。"]},{"t":"奉次涯翁先生写真 其二","f":"七言绝句","c":["后天不老是公身，今作人间野服人。","若问向来黄阁地，东阑芍药有馀春。"]},{"t":"题景娄翁寿藏追次张东海韵","f":"七言绝句","c":["乾坤随处是行窝，漫听人间哭且歌。","莫问向来登啸地，太湖秋晚水增波。"]},{"t":"奉次涯翁先生漫兴 其一","f":"七言绝句","c":["新为邻人短筑墙，竹边小径旧升堂。","病馀谢客浑无事，童子犹嫌洗砚忙。"]},{"t":"奉次涯翁先生漫兴 其二","f":"七言绝句","c":["水调山中不用符，老僧仍挟古茶垆。","晚来送客前泾去，问道前泾月有无。"]},{"t":"戴文进春山叠翠图","f":"七言绝句","c":["戴翁笔底有春山，万叠风烟尺素间。","好似西湖新雨后，两峰回首六桥湾。"]},{"t":"王友石枯木竹石","f":"七言绝句","c":["何处萧萧玉数竿，树边石畔晚风寒。","王郎标致元如此，每向人家画里看。"]},{"t":"邹就閒见访","f":"七言绝句","c":["三十年前见此翁，青春标格旧家风。","而今白发垂双鬓，秋水依然是碧瞳。"]},{"t":"米老拜石图","f":"七言绝句","c":["眼底巉岩万古珍，乾坤回首几风尘。","公来一拜还袍笏，不道天涯有美人。"]},{"t":"王友石渭川烟雨图为施克文题","f":"七言绝句","c":["此老胸中有渭川，笔端能雨复能烟。","休论画法如书法，曾向松庵读史迁。"]},{"t":"施克咨友石竹枝扇面","f":"七言绝句","c":["石庵画竹人争赏，尺素流传知几家。","偶见平山亭子上，长吟落尽晚春花。"]},{"t":"谢张提学惠薏苡仁","f":"七言绝句","c":["辟湿初闻薏苡仁，涯翁诗里见来真。","东风吹送台端贶，活火山泉共作春。"]},{"t":"赠邹光懋","f":"七言绝句","c":["五月蠡溪新水生，菰蒲出水与堤平。","望亭南望太湖白，溪上诗人无限情。"]},{"t":"谢张巡抚惠廪米","f":"七言绝句","c":["廪人珠玉辱多分，南浦犹怀共水云。","作粥便将和薏苡，涯翁诗自学台闻。"]},{"t":"为邹文谟题画赠刘古田","f":"七言绝句","c":["黄鹤楼前江汉流，十年乡梦在中洲。","而今木铎翻琴操，又向闽南望楚州。"]},{"t":"咏史","f":"七言绝句","c":["麻衣力尽泣孤臣，回首江南草色新。","独恨乾坤如许大，首阳无地可埋身。"]},{"t":"春庭八绝句 其一","f":"七言绝句","c":["三年种松五尺彊，松枝盘桓松叶长。","岁寒节操久应见，春日开花清更香。"]},{"t":"春庭八绝句 其二","f":"七言绝句","c":["偶栽梅树是红花，每岁花开对客誇。","知己相看心自白，尽将颜色付诗家。"]},{"t":"春庭八绝句 其三","f":"七言绝句","c":["菖蒲本是仙灵物，却为冰霜穴底藏。","过尽东风更梅雨，水中央看婉清扬。"]},{"t":"春庭八绝句 其四","f":"七言绝句","c":["西园移来两丛竹，千古湘皋宛旧斑。","莫道吴天非楚地，主人眼底有江山。"]},{"t":"春庭八绝句 其五","f":"七言绝句","c":["新梧树傍旧桐栽，俱自青山寺里来。","几见霜黄春又绿，有诗空和凤凰台。"]},{"t":"春庭八绝句 其六","f":"七言绝句","c":["买裁金橘短婆娑，向来洞庭风雨多。","分付苍头好浇灌，莫教人力负天和。"]},{"t":"春庭八绝句 其七","f":"七言绝句","c":["燕居亭前石子台，两株银杏一时栽。","莫言未得弦歌地，画里尼山许见来。"]},{"t":"春庭八绝句 其八","f":"七言绝句","c":["九畹新成古井田，滋兰又似赋骚年。","不如无界还无数，雨露茫然太古天。"]},{"t":"题画送胡仁夫 其一","f":"七言绝句","c":["酌泉饮君君莫疑，此泉德本与君宜。","烦君持向开河去，宋老祠前奠一卮。"]},{"t":"题画送胡仁夫 其二","f":"七言绝句","c":["东山寺里相逢地，陆子泉头再会年。","震泽烟波彭蠡月，乾坤回首一茫然。"]},{"t":"望云庵为林提学题用素翁韵 其一","f":"七言绝句","c":["白石山前云气深，有时飞起有时沈。","太行顶上南回首，千里慈闱隔岁心。"]},{"t":"望云庵为林提学题用素翁韵 其二","f":"七言绝句","c":["黄河东绕太行深，云薄西峰日未沈。","万里乾坤同一慨，北南行止两无心。"]},{"t":"雨中柬文玉 其一","f":"七言绝句","c":["雨中闭阁自焚香，门外诗来故故忙。","梦里风骚犹远在，却教白日破羲皇。"]},{"t":"雨中柬文玉 其二","f":"七言绝句","c":["梅天散帙动芸香，谁信閒人尽日忙。","不见青藜照清夜，欲将遗事问东皇。"]},{"t":"题石庵画竹","f":"七言绝句","c":["萧萧数叶不胜看，到此方知画竹难。","谁信中书曾放笔，片时行尽楚江干。"]},{"t":"为俞立夫题秦务本小画","f":"七言绝句","c":["诗兴逢秋日渐深，相知独寄画中琴。","青山影照斜桥水，时往时来共赏音。"]},{"t":"成汝从惠鲈鱼口占荅之","f":"七言绝句","c":["溪边渔艇日相寻，谁遣鲈鱼动我吟。","我脍我羹人莫易，当年张翰亦劳心。"]},{"t":"寿涯翁老师用癸酉守岁韵","f":"七言律诗","c":["濯缨歌罢水无尘，静里乾坤太古春。","藜杖有情随兴远，綵毫无象与时新。","星辰又值初生日，山斗同瞻未老身。","白发门生江海上，捧觞真羡在庭人。"]},{"t":"閒居用旧韵","f":"七言律诗","c":["短墙隔断市桥尘，地为容春早得春。","春雨却扶嘉树老，草堂方舞綵衣新。","经纶不入间边梦，笔砚长随病后身。","刚爱绿阴帘阁坐，抱琴惊见扣门人。"]},{"t":"秋夜与东泉澜庵坐月","f":"七言律诗","c":["病起寻诗此夜多，隔帘月竹弄婆娑。","灯光相对知人否，酒戒未开如夜何。","它日更期天淡荡，去年犹忆雨滂沱。","西风吹绽东篱菊，须向花前一浩歌。"]},{"t":"甲戌正月三日山行次史敏甫","f":"七言律诗","c":["万壑春姿一夜还，画船载酒共看山。","泉经古寺自双涧，亭倚危峰还几间。","真乐竟须同客醉，浮生何必羡僧閒。","南岩更得和风早，笑索梅花不作悭。"]},{"t":"徐用中寓松风阁诗以为问","f":"七言律诗","c":["舞雩何处问高坛，松阁春风晚带寒。","病起不须操几杖，诗成刚在凭阑干。","榻缘徐孺初教下，垆为王郎试索看。","我欲坐君听古调，隔墙还有玉千竿。"]},{"t":"雨中漫成","f":"七言律诗","c":["阳春门外水田田，野老歌声远近连。","雨应雪来曾计日，月从星在故占天。","漫看东渚横孤艇，久拟南风振五弦。","更爱亭前新种竹，一番沾洒一森然。"]},{"t":"寄许东庐","f":"七言律诗","c":["老去诗篇兴若何，一春城郭少经过。","阴怜绿树风偏好，湿怪黄梅雨太多。","静力更凭閒打整，狂心都逐病消磨。","劳君问讯无堪报，微醉亭前独放歌。"]},{"t":"荅桂子朴","f":"七言律诗","c":["南行将母底须悲，浙水滩高恐到迟。","秋月春花皆我梦，海风江雨此何时。","孟郊心苦吟游子，韩老情多赋别知。","尽把新怀对难弟，玉峰回首思冥迷。"]},{"t":"闻李四顺讣","f":"七言律诗","c":["百年家学有箕裘，晚擢高科仕亦优。","北斗望中心凤阙，西山归处首狐丘。","一封诰尚虚新墓，万卷书还满旧楼。","最是渠南亭子在，黄梅细雨不胜秋。"]},{"t":"次杨淡成","f":"七言律诗","c":["去年雁早曾闻赋，今赋还闻雁晚来。","信入上林云有路，居空彭蠡水无陔。","独看黄菊疑秦令，未猎长杨愧汉才。","莫道喘牛非我问，饭牛歌罢自生哀。"]},{"t":"赠边伯山教授","f":"七言律诗","c":["看尽长安一日花，还从八月返星槎。","儒官故冷师模重，宦路虽迂国体华。","地接苏湖风有自，天空蓬阆海无涯。","栋梁榱桷皆时用，歌向先生不是誇。"]},{"t":"送费鹅湖先生归铅山","f":"七言律诗","c":["归兴乘秋度玉山，始知佳境在人间。","云鸿影外江湖远，皋鹤声中日月间。","秘阁文章天下手，都门图画老臣颜。","感公相问无能荅，病客江南正掩关。"]},{"t":"寿贾封君","f":"七言律诗","c":["上寿人膺太史封，白头林下庆遭逢。","清时恩典隆冠冕，令子文章重鼎钟。","鸠杖晚扶閒处立，兕觥春映醉时容。","仁源不在南阳水，莫问今生菊几丛。"]},{"t":"屋舟为京口钱宗玉赋","f":"七言律诗","c":["风波懒逐世浮沈，小阁凭虚敞素襟。","采药每牵浮海梦，乘槎聊遣济川心。","水能载覆旁观久，天与周旋独坐深。","闻道江南船似屋，中泠何地觅帆阴。"]},{"t":"自和幽居四咏 其一","f":"七言律诗","c":["晚晴无物不含晖，此树天将悦我非。","一碧故涵秋水净，半黄初着晓霜微。","吟随望远长凭几，情忆阴多坐解衣。","莫道寂寥谁与共，天风时引白云归。"]},{"t":"自和幽居四咏 其二","f":"七言律诗","c":["忽有幽香共午风，小春庭院菊篱东。","一丝何处来应远，百和无端界本空。","漫道芝兰随物化，真闻黍稷与神通。","麓堂地隔四千里，三叹馀情数纸中。"]},{"t":"自和幽居四咏 其三","f":"七言律诗","c":["绿树春声正自怜，秋深幽鸟复庭前。","谷中音似闻人语，池上书应为客传。","短调自须风静听，多情谁起日高眠。","閒来漫拟成新曲，长啸临流付一弦。"]},{"t":"自和幽居四咏 其四","f":"七言律诗","c":["饶州遣鹤剩风流，小圃新开竹径幽。","见影浅将于水监，闻声高欲自天求。","图中恨识青田晚，梦里疑看赤壁秋。","莫向主人撩醉眼，病馀如我且须休。"]},{"t":"寄吴宪使","f":"七言律诗","c":["濂泾草堂清可怜，幽期已在立秋前。","社中诗自无新什，方外书应有别传。","野旷正堪乘月步，日高犹为避风眠。","伯牙山水钟期耳，万古知音不在弦。"]},{"t":"寿涯翁老师","f":"七言律诗","c":["缄诗到已过弧辰，十月书回墨尚新。","独乐园成身未老，静观心在物皆春。","千钧笔试三杯酒，数仞墙趋四海人。","古华山泉深更远，年年持此庆生申。"]},{"t":"寿吴宪使","f":"七言律诗","c":["东藩回首兴飘然，须信吾儒有列仙。","湖海正当初返地，星辰还值始生年。","南山静对陶潜菊，春酒香分陆羽泉。","笑问丹丘何处是，为君重赋远游篇。"]},{"t":"观红梅次玉林韵 其一","f":"七言律诗","c":["两树新从浙上来，一株先向槛前开。","春回老干经三月，酒入酡颜定几杯。","画笔词锋争胜负，花情人意两徘徊。","玉林高唱南沙和，月上东山客始回。"]},{"t":"观红梅次玉林韵 其二","f":"七言律诗","c":["清兴逢春似水来，红梅花下小筵开。","尽将颜色降诗律，独引风情入酒杯。","积雪不知香逗遛，落霞还与影徘徊。","海棠更有西轩在，赏事真须第二回。"]},{"t":"雪中红梅","f":"七言律诗","c":["红入梅花淡更妍，一株曾向麓堂前。","为春独步还今日，与雪相违又几年。","素质已参丹鼎客，朱颜应作羽衣仙。","凭谁唤醒罗浮梦，不信瑶池别有天。"]},{"t":"得莫如山浦文玉和章复用韵一首禁体物语","f":"七言律诗","c":["初阳一点便成妍，占断容春小阁前。","犀浦有招须避地，海棠相见定忘年。","姿容漫倚云边客，香影空传海上仙。","寄语诗人休物色，已知描画不如天。"]},{"t":"送梅","f":"七言律诗","c":["吹残玉笛有馀妍，愁向东风问雨前。","共矢心情如白日，长留颜色似青年。","看过春陌且从客，餐尽朝霞还访仙。","何处江皋可遗玦，罗浮回首海南天。"]},{"t":"再咏红梅","f":"七言律诗","c":["江头两株来越人，却依旧树争鲜新。","竹松相与可偕老，桃杏不知应妒春。","特书方将补月令，殊色乃复烦花神。","倚阑独对东风语，万古清香真绝尘。"]},{"t":"送秦中丞国声之湖南兼呈东山先生","f":"七言律诗","c":["中丞旌节自东来，黄鹤楼高倚宪台。","江汉朝宗千古地，风霆鼓舞一时才。","洞庭水阔春初渡，衡岳云深晚正开。","老矣东山烦问讯，苍生回首柰何哉。"]},{"t":"送华大参文光 其一","f":"七言律诗","c":["老鹤风清蜀道寒，使君直节动朝端。","峨眉月小天非远，滟滪春深水正宽。","今雨客怀还对榻，平生交谊自胜冠。","益州画像闻犹在，石本凭君一寄看。"]},{"t":"送华大参文光 其二","f":"七言律诗","c":["兵戈销尽蜀江深，甘雨和风使者临。","宽得一分非小惠，远从三殿是佳音。","他年鸣凤曾为瑞，何处甘棠不作阴。","提学分司如我问，古梅花下忆论心。"]},{"t":"雨坐","f":"七言律诗","c":["桃花水来花正飞，鸣雨既过还烟霏。","道人多情自晚阁，童子好事空春衣。","溪上芳洲白鸥剧，城边野塘青草肥。","山园竹萌未盈尺，有仆修篱乘棹归。"]},{"t":"陈嘉言送双鹤以诗遣之次韵为谢","f":"七言律诗","c":["病后身轻欲御风，羽人谁遣过墙东。","乾坤有地云随驭，日月多情鸟出笼。","诗社几人时野服，使君五马古侯封。","天机动我鸣还舞，更爱新巢在老松。"]},{"t":"馈笋于侯明府明府有诗用韵荅之","f":"七言律诗","c":["玉在山中敢自珍，令君诗到便成春。","坡翁他日言何剧，石老此庵看已真。","巢凤欲来先振羽，箨龙方卧渐生鳞。","筠笼落落惭为政，只馈清馋不馈贫。"]},{"t":"以梅实樱桃赠文玉文玉索诗用前馈笋韵","f":"七言律诗","c":["人有相知果有珍，盘中朱绿眼中春。","休论金鼎调还未，且道筠笼赠是真。","试熟漫凭犀浦鸟，荐新兼侑锦江鳞。","无端生意诗囊在，报尽璚瑶正不贫。"]},{"t":"得乾笋法于文玉用前韵为谢","f":"七言律诗","c":["待聘多君久席珍，等閒熏炙亦成春。","相知岂谓新时好，不厌曾闻淡里真。","煮石每教寻活火，屠龙谁解斸生鳞。","庭前更有双梅实，古鼎无劳笑我贫。"]},{"t":"再荅文玉用前韵","f":"七言律诗","c":["市桥樱笋竞相珍，四月风光未尽春。","病欲自医须此静，才难时用是吾真。","南山地近无丛桂，沧海波深有一鳞。","数亩小园千挺竹，野人家事不曾贫。"]},{"t":"三荅文玉 其一","f":"七言律诗","c":["十载胸藏万古珍，挥毫应待殿前春。","群龙变化知非幻，二鸟遭逢恐未真。","独夜坐醒云鹤梦，长风歌动石鲸鳞。","古人青眼如犹在，肥马宁教笑士贫。"]},{"t":"三荅文玉 其二","f":"七言律诗","c":["蕨芽未许殿山珍，孤竹根回地底春。","歌菉千年风故好，闻韶三月味应真。","沧江雷雨龙无种，深谷霞烟玉有鳞。","漫咏杜诗还自笑，数株桃树济谁贫。"]},{"t":"追挽庄定山","f":"七言律诗","c":["尺疏曾闻奏玉皇，上元灯火谢词章。","百年不起燕台马，万古犹存鲁庙羊。","剑委烟霞还岳气，笔参星斗动江光。","长歌滴尽东堂雨，祗缺青山一瓣香。"]},{"t":"次浦文玉夏日遣怀","f":"七言律诗","c":["午风清爱葛为袍，销尽炉薰政寂寥。","愁里得诗如客到，梦中观物笑僧骄。","三年病合投閒计，十里游辞避暑招。","有曲和君还自已，古琴疏越未堪调。"]},{"t":"待曙楼为俞司谏国昌赋次涯翁老师韵","f":"七言律诗","c":["高栋层轩带宿霏，明星耿耿见依稀。","天回北斗还何指，地向东方渐有晖。","寺下云林僧未出，城边野水鸟初飞。","主人听彻金门漏，五凤楼前候衮衣。"]},{"t":"热中和杜自遣","f":"七言律诗","c":["时行风咳十人九，而我欲逃还不能。","漫扣苏槃弄白石，且诵欧赋憎苍蝇。","万里楼台正隐隐，三年几格何仍仍。","所思宛宛隔秋水，墨汁飞来字字冰。"]},{"t":"次侯明府登湿云亭","f":"七言律诗","c":["两载忧民太瘦生，偶乘秋兴试山晴。","路过野寺云初湿，人在危厓鹤共清。","有石尽堪他日颂，此泉真与我心盟。","大夫能事登高赋，莫讶天风起旆旌。"]},{"t":"次侯明府九日游惠泉","f":"七言律诗","c":["病不登高数负秋，却怜令尹此閒游。","清知流水山中出，远见云飞海上浮。","僧具袈裟惟茗供，客过方丈有诗留。","秪应稼穑关心在，莫话忘机欲对鸥。"]},{"t":"十四夜小酌","f":"七言律诗","c":["将圆未圆天上月，似老非老人间人。","醉时歌调几年复，病起酒杯今夜新。","多情不啻共千里，何地更堪容一尘。","明日南楼独清咏，风吹星汉欲粼粼。"]},{"t":"秋日侯明府见过","f":"七言律诗","c":["病中三度见秋风，车骑时时枉县公。","野服岂堪迎上客，清谈真可慰深衷。","地从泰伯风流在，人与中牟惠爱同。","帘阁不知移日影，薰炉茗盌有双童。"]},{"t":"送赵立之应贡","f":"七言律诗","c":["君门北望政如天，有志元从鼓箧年。","岁赋远追三代典，命题亲御九重筵。","诗成行卷如携岳，酒尽离觞更酌泉。","莫向秋风逐车骑，新春须上渡江船。"]},{"t":"西郊观稼奉次涯翁先生","f":"七言律诗","c":["诏许明农值此年，西郊垂稼正田田。","一时偶出游还赋，四海方询食与眠。","溪水多鱼供有馔，野人皆酒飨无筵。","寿村风景谁堪拟，韦杜同归尺五天。"]},{"t":"谢侯明府遣医视老母用壬申岁闻侍养命韵","f":"七言律诗","c":["偶于文檄见都俞，多少忧怀为扫除。","父母歌传千载上，君臣药在一言馀。","三春寸草慈亲德，片纸千金令尹书。","医国有人吾岂敢，秪从花径导潘舆。"]},{"t":"丙子元日试笔","f":"七言律诗","c":["栽得野松苍色多，隔墙菉竹亦猗猗。","焚香扫地自我是，投刺到门如客何。","亭上高登移晚岫，溪边徐步起新波。","去年今日曾题句，和者盈屏皆可歌。"]},{"t":"十四日观灯","f":"七言律诗","c":["前日方愁月负灯，夜来灯月兴还增。","桥通碧水湾湾路，街覆青松处处棚。","海上不知蓬岛隔，春来漫拟广寒登。","少年乐事今如梦，驻马长安几度曾。"]},{"t":"十九日漫述用元夕韵柬坐客","f":"七言律诗","c":["满城风雨夜收灯，草色阶前看渐增。","三载病躯才入市，一时诗兴敢题棚。","绕门水可容舟泊，负郭山须借屐登。","燕九有名何必问，匏翁诗向蓟门曾。"]},{"t":"春日寄玉林","f":"七言律诗","c":["春日题诗问玉林，山中春色浅还深。","初鸣谷鸟乘风煖，半吐岩花坐野阴。","画舫壶觞游客兴，竹垆泉水老僧心。","凭君为约新晴后，绣岭堂前共一吟。"]},{"t":"次韵荅如山","f":"七言律诗","c":["读书曾共借东林，竹上题诗岁月深。","千仞羽仪看晚霁，几番花信作春阴。","而今诸老多明眼，自古良工独苦心。","我有一杯非浪致，为君先唱鹿鸣吟。"]},{"t":"沈方伯良臣雨中见访以归田数诗索和和其一以荅之","f":"七言律诗","c":["归计休论负郭田，险途曾讶璧能全。","故人今雨非他客，吾道沧洲共此年。","秋兴剩添三径菊，春潮不到五湖船。","凭君再拟相寻地，数点閒鸥野水边。"]},{"t":"哭喻子乾","f":"七言律诗","c":["数口西悲蜀道难，一骢五马旧相看。","风传天上春光近，月堕云间海气寒。","事志已脩千里郡，功名俄盖百年棺。","惟馀南省相知意，独取焦桐忍泪弹。"]},{"t":"上巳之明日登锡山顶一首","f":"七言律诗","c":["閒上东峰望五湖，旧时亭榭半荒芜。","山中石刻曾传汉，水上䲭夷独吊吴。","南涧袈裟僧迓客，西岩尊榼仆争途。","五年再起登高兴，问道山花识我无。"]},{"t":"用登山韵送尹吉士舜弼","f":"七言律诗","c":["几年踪迹隔江湖，冉冉春愁寄绿芜。","北望京华常傍斗，东来舟楫又经吴。","鹅湖鹿洞今何梦，瀛水蓬山旧有途。","我忆麓堂心更切，临书翻愧一言无。"]},{"t":"舜弼去张提学汝立至复用韵一首","f":"七言律诗","c":["旧游回首几鄱湖，白鹿堂坛半欲芜。","周氏图书元自孔，楚邦风壤尚连吴。","壮观独泛三江水，正学先驱万里途。","闻道春来多雨露，山城桃李已开无。"]},{"t":"春日访莫如山不遇","f":"七言律诗","c":["南郭沙边一系舟，山亭步转更登楼。","仆知旧事问能荅，客有馀情行复留。","背谷且看花独放，隔林曾听鸟相求。","主人试屐今何处，应在龙峰最上头。"]},{"t":"华藏寺和玉林","f":"七言律诗","c":["涌金亭倚水云高，三月馀寒尚绮袍。","古寺客来敲柳瘿，老僧门外扫松毛。","天风欲定还舟楫，春色无端漫酒醪。","独立苍茫思何限，吴山烟树越江涛。"]},{"t":"送潘侍御起溟","f":"七言律诗","c":["柱史新从两浙还，清风随鹢过吴山。","南方郡国巡行后，北极朝廷仰望间。","八月秋涛虚谷震，六桥春雨落花斑。","朝来暂舣蓉湖棹，却爱沙鸥水际閒。"]},{"t":"吹笛","f":"七言律诗","c":["吹笛禅堂夏日长，月明还忆玉河觞。","弟兄于我交能世，山水而今会在乡。","兴逐微波生绿酒，梦将幻景出黄粱。","清秋更拟酬君地，高阁松风坐夕阳。"]},{"t":"午热书事用西涯公韵公用杜韵 其一","f":"七言律诗","c":["矮矮床如席地然，十分昼漏七分眠。","铜槃水石自手弄，山阁风松犹梦牵。","故人馈酒江浙上，童子诵书秦汉边。","东街铃声冰水过，时向慈闱须买钱。"]},{"t":"午热书事用西涯公韵公用杜韵 其二","f":"七言律诗","c":["古涧泉如为我然，松阴有石更堪眠。","仰高长对山灵在，习静将胜尘务牵。","大孤小孤汇泽畔，南高北高潮海边。","人间山水即风月，清兴到时那用钱。"]},{"t":"喜得精舍地有作用杜韵","f":"七言律诗","c":["寺门东北径悠然，小洞阴多鹿惯眠。","出地泉声无石碍，倚天松骨有萝牵。","病馀杖几三年后，梦里堂坛五老边。","莲社在邻吾不入，门人今助买山钱。"]},{"t":"苦热用虞邵庵韵","f":"七言律诗","c":["酷暑凌人未肯休，深居谢客汗还流。","月星影照此堂夜，风雨梦回何处秋。","吾道江湖应久病，谁歌云汉不深忧。","长松古涧新精舍，愿与诸君裹茗游。"]},{"t":"怡閒翁七十寿诗","f":"七言律诗","c":["不须开燕却须诗，七十年来两好儿。","晨策杖时无地碍，夜焚香处有天知。","中书宅畔云连合，罗汉祠前水满池。","莫向人间问蓬岛，人间人以百为期。"]},{"t":"正月三日小饯施克和于惠山酒间克和诵刘后村元日诗为令因用其韵再致别意是日予奉老母观新精舍故别设于知微山房云","f":"七言律诗","c":["精舍初成近惠泉，几回辰至起僧眠。","新正屈指今三日，旧约惊心又一年。","慈母板舆应偶尔，佳宾草饭乃居然。","凭君莫问山中事，万里青云彩鹢前。"]},{"t":"精舍成荅徐侍御侍御拟复命还日来观故结语云","f":"七言律诗","c":["宪台檄至筑书台，野寺东头辟草莱。","新水槛前看正脉，古松坛下赏遗材。","诗传涯老能千纸，酒酹山灵又一杯。","刚道暮春吾兴在，绣衣天上亦朝回。"]},{"t":"春日怀僧知微","f":"七言律诗","c":["今雨山中未煮茶，僧房岑寂闭梅花。","云心逐我俱无迹，草色逢春渐有涯。","林径几时松叶满，洞门何处竹枝斜。","野人持赠青藜杖，欲向吟诗社里誇。"]},{"t":"寄题宜兴李宗源双桐用吴宁庵韵","f":"七言律诗","c":["双桐自比双南金，地得宽閒谢斧寻。","吴老诗题从始植，文郎图画已成阴。","霜黄碧叶秋将及，月白青枝夜不禁。","吾树在庭须客赋，为君还作短长吟。"]},{"t":"秦氏山庄用慰国英韵","f":"七言律诗","c":["五峰东下见平林，中老当年卜隐心。","龙尾白云看不远，水心明月坐曾深。","谁家桃李春无色，此地松筠晚有阴。","欲过荒亭桥板断，几时香茗更相寻。"]},{"t":"和荅乔司马","f":"七言律诗","c":["参赞堂高倚碧天，旧章新贺又今年。","野情不问山深浅，春色争看雨后前。","梅柳云霞俱物候，江湖廊庙各诗篇。","江南二月多游兴，独放清溪爱我船。"]},{"t":"观梅","f":"七言律诗","c":["病起逢春意渐宽，梅花又向槛前看。","色如桃李无尘俗，心与冰霜共岁寒。","素后也知施采易，黄时才觉作酸难。","东风吹雨花朝近，对酒题诗政未阑。"]},{"t":"寄复张提学用旧韵","f":"七言律诗","c":["两月东巡历四州，几多诗景待君收。","节从海上应遄返，题为泉头合再留。","湖上晚风云未定，山中春水鸟相求。","濯缨别有沧浪调，何处兰亭水曲流。"]},{"t":"荅南沙用前韵","f":"七言律诗","c":["红梅又发旧年枝，多事相寻酒与诗。","草木欲蕃先喜色，冰霜虽老独贞姿。","君歌已到能言地，我赏偏于半醉时。","谁道忘忧但萱草，北堂移此亦应宜。"]},{"t":"次韵荅见素先生","f":"七言律诗","c":["一别金溪十载馀，郊斋犹忆识荆初。","吟诗坛远旗频偃，执法台高席屡虚。","闽峤衣冠千里梦，蜀川兵革几封书。","花篱竹径寻常地，惭愧先生问卜居。"]},{"t":"寄夏德树用素翁见寄韵","f":"七言律诗","c":["赤城别我十年馀，犹忆麻城语我初。","夜月江南鸿雁少，春风海上翠屏虚。","佳人空谷长劳梦，远道平生未尽书。","闻道草玄多暇日，杖藜时过野翁居。"]},{"t":"闻庞方伯元化讣","f":"七言律诗","c":["激昂意气欲凌云，他日同朝仅见君。","国论是非谁史笔，谏垣轻重几弹文。","山连吴楚三台近，水出江河两纪分。","信宿信州成永诀，旧诗凄楚不堪闻。"]},{"t":"山中访王校书 其一","f":"七言律诗","c":["閒看书法到山中，骑从多烦两县公。","茶鼎润生移竹雨，墨池清起落梅风。","闭门谢客精庐右，扫榻劳僧丈室东。","只恐春深游客到，青松林外万花红。"]},{"t":"红梅一首用涯翁壬申岁韵","f":"七言律诗","c":["红梅阑畔兴无涯，颇觉诗从去岁赊。","贞白心肠元绝物，寻常颜色自成家。","品题合著孤山月，行辈休论二月花。","剩取馀情与来岁，只今谁逊复谁誇。"]},{"t":"上巳日私试诸生于二泉精舍","f":"七言律诗","c":["一从脩禊起流觞，千载高风尚未忘。","此日閒来非此客，吾山佳处复吾堂。","卧龙庵外寻黄石，活水源头见紫阳。","沂上是非人莫问，草亭真对海天长。"]},{"t":"观锡山塔基寄顾少参与成","f":"七言律诗","c":["东峰石塔对西峰，云去云来俯仰中。","万古不磨铭地语，百年谁试补天功。","雷将化雨春回蛰，斗避文星夜起虹。","何日落成须我报，望湖亭上一樽同。"]},{"t":"夜坐复用韵寄与成","f":"七言律诗","c":["夜闻雷雨过前峰，忽见浮图在眼中。","最喜江城增胜槩，却愁山鬼妒成功。","白云影护无声瀑，碧海光摇不霁虹。","东望怡亭西剑井，路人传谶定应同。"]},{"t":"龚守诚为山于水北庄诗以讯之用玉林韵","f":"七言律诗","c":["却对真山作假山，白云来往隔松关。","屐从一径委蛇处，亭在双峰掩映间。","地僻有人能散逸，时清何物不幽閒。","二泉精舍长邻近，日见林翁杖屦还。"]},{"t":"连日在听松冗未有诗雨中补之","f":"七言律诗","c":["谁将第一扁西神，竹径新开及晚春。","劫火不烧无屋地，海鸥如避有机人。","池边水脉通时活，阁上松声听后真。","闻道观音经卷在，欲从老衲话来因。"]},{"t":"再用前韵","f":"七言律诗","c":["休将冥漠问山神，绣岭花开别样春。","竹少千竿分两径，松高百尺抱三人。","茶垆欲试新泉在，画壁曾看老衲真。","内翰中书前辈行，閒来衰劣愧相因。"]},{"t":"又用前韵专咏松风","f":"七言律诗","c":["高阁松风似有神，骤如秋雨细如春。","病馀每爱同游客，静里偏宜独听人。","已向陶庐誇地远，更于庄籁认天真。","眼前一片虚空界，童子何知问起因。"]},{"t":"雨中次文玉","f":"七言律诗","c":["庭下双松相对清，东风吹花松子生。","四檐飞雨葛衣薄，一径带云藜杖轻。","课诗未足销多暇，戒酒非关爱独醒。","何处沧洲堪一眺，已知吾道负冠缨。"]},{"t":"送潘平阳","f":"七言律诗","c":["东归匝月复南游，百里封疆旧是州。","雁荡峰高连两越，钱塘潮长及中秋。","琴横昼日随鸣鹤，冕露春风起卧牛。","更喜老亲迎养便，冯公舆接少微舟。"]},{"t":"登华甥西楼用唐人韵","f":"七言律诗","c":["满天风雨独登楼，林杪清烟淡欲收。","云重不知今日午，月明还忆去年秋。","道经南郭蒲帆近，望入东庐草径幽。","何处新晴堪试屐，溪桥北去有高邱。"]},{"t":"雨中在堠阳闻徐东之讣垂涕对客情见乎辞","f":"七言律诗","c":["老来方恨少知音，忽报斯人又陆沈。","万里枯槎空一水，百年敝帚独千金。","唐衢泪尽江湖远，李渤盟寒岁月深。","头白门生君自道，晋陵回首重伤心。"]},{"t":"雨中自堠阳还冉泾","f":"七言律诗","c":["雨斋正喜故人来，兴尽将归雨又催。","溪上船如春水坐，云中帆似楚江回。","傍沙白鸟时双下，隔浦红蕖已半开。","回首东庐休惜别，月明曾约共登台。"]},{"t":"一室","f":"七言律诗","c":["郁蒸今两异他年，一室焚香坐且眠。","门外刺常愁客入，社中诗却喜人传。","古盘水石堪时弄，高阁风松亦梦牵。","短壑层冰何处所，杜陵歌罢兴悠然。"]},{"t":"两精舍","f":"七言律诗","c":["两精舍共二泉名，惠麓清风似冉泾。","松倚一峰元有径，草迷七曲已无亭。","渠通活水门前碧，岭出浮云屋上青。","刚道病馀多谢客，小舟时复过西汀。"]},{"t":"松风阁追次秦中斋韵","f":"七言律诗","c":["一木还将古殿支，真公五叶又逢师。","閒云锡远心初定，净水瓶深手自持。","南涧浚泉寻石窦，西林望月倚松枝。","旧庵更有新楼阁，淮海先生为作碑。"]},{"t":"松风阁追次莫东川韵二首 其二","f":"七言律诗","c":["石畔青梧正有华，白云深处问僧家。","壁葭梦远犹疑画，垆竹盟寒不为茶。","绣岭峰回松起籁，黄梅时尽雨如花。","流泉东入蓉湖去，遥听滩声走碧沙。"]},{"t":"松风阁坐圆金方益二僧和莫东川诗来呈用韵赏之","f":"七言律诗","c":["母怪侏㒧语杂华，静中禅却自成家。","石庵故有诗题竹，雪老曾闻榜说茶。","三日天能留阁雨，一杯吾亦对山花。","秪应便放中秋棹，黄阜墩边倚月沙。"]},{"t":"寄周都宪文化","f":"七言律诗","c":["病馀思见故人难，东浙山川入画看。","风雨百年多幻景，江湖万里几惊湍。","尊前每进新鸠杖，箧里还看旧豸冠。","尚忆虔州同驻节，郁孤台上望长安。"]},{"t":"送朱推官","f":"七言律诗","c":["曾从天际望苍梧，西向浔州莫问途。","狱讼岂应轻郡国，经纶未必负江湖。","文书散后诗还有，车服临时牒并无。","指日听宣风宪召，郁林船石又东吴。"]},{"t":"侯职方书问我冉泾听松二精舍诗以为荅","f":"七言律诗","c":["远问容春及九峰，北湖于我意偏浓。","幽怀自许长如石，晚岁相看有此松。","江上书回乡国骑，山中梦醒县楼钟。","何时更是思君地，活水源头一短筇。"]},{"t":"再荅王郡公","f":"七言律诗","c":["太守诗来老衲收，清风长满听松楼。","为山坐雨谁三日，嗟我怀人又一秋。","对酒且须诸客赋，省耕还及早春游。","最怜多稼亭前月，夜夜光明照远洲。"]},{"t":"过舍弟小庄复用前韵","f":"七言律诗","c":["溪深竹密两三家，树柳为墙近北涯。","浅水渐容新渚出，疏林犹作远山遮。","路回贾客帆初转，风急行人帽欲斜。","日暮相看兴无尽，漫从舟畔采蘋花。"]},{"t":"送葛泉州","f":"七言律诗","c":["老称汉吏尚青年，路指南闽上越船。","何郡独非盘错地，吾山元有洌寒泉。","田田麻麦东风雨，夜夜星辰北极天。","行过莆阳烦问讯，素翁庄在野云边。"]},{"t":"观冯廷伯园池湖石","f":"七言律诗","c":["石丈新从湖上来，君家方筑水中台。","百年风力谁能挽，万古云根我更培。","袍笏有时真合取，斧寻何处尚须裁。","题名未敢轻拈笔，恐露精光逼斗台。"]},{"t":"得罗建宁和篇复用韵","f":"七言律诗","c":["君向江郎看石来，冯家池上复登台。","奇踪漫谓星辰陨，秀色还从雨露培。","杖者几须梧竹制，仙家衣是薜萝裁。","若教移置钟山下，何处金声更赋台。"]},{"t":"精舍奉安忠定祠","f":"七言律诗","c":["七载蘋蘩也自脩，听松庵外竹林幽。","高山仰止今祠宇，旧事荒凉某水邱。","诸葛表中空汉贼，考亭笔下有春秋。","共看箫鼓迎神地，一道清泉万古流。"]},{"t":"又明日作","f":"七言律诗","c":["十年论道坐黄扉，多少文章上衮衣。","绿野堂成才少息，碧山居在竟何归。","昌黎山斗名方著，君实儿童事已非。","愁绝两知亭外竹，声声萧瑟倚斜晖。"]},{"t":"又明日作","f":"七言律诗","c":["明农疏入兴超然，刚道艰危已济川。","晚岁乐无司马独，盛时忧有范公先。","三朝天为留平格，一语民曾解倒悬。","纵是门人脩谱录，隐功阴德恐难传。"]},{"t":"又明日作","f":"七言律诗","c":["方石东山各远行，朱弦还对老门生。","酒边梅雪五年梦，诗里云山千里情。","节击和歌声响应，囊留删稿字纵横。","独怀他日抠趋地，欲向南屏问旧盟。"]},{"t":"又明日作","f":"七言律诗","c":["病久无书问起居，有书还复索亲书。","但能数字何须楷，从此三年遂不虚。","湖海却忘魂梦外，亭台犹想笑谈馀。","静探月窟诗中意，舞罢莱衣每愧予。"]},{"t":"得俞吏科国昌报","f":"七言律诗","c":["吏科报至倍伤神，说病论医字字真。","千字尚留秦篆石，一时真泣孔经麟。","新亭东望虚秋月，别墅西惊迫塞尘。","天路茫茫灵爽在，先皇应慰见师臣。"]},{"t":"见素公寄和公惠山泉歌至","f":"七言律诗","c":["素老书来手独开，涯翁书复几时来。","百年倡和空金玉，千丈光华自斗台。","震泽云山愁独对，重阳风雨梦初回。","坛帷更拟龙峰下，一勺清泉万古哀。"]},{"t":"宋文杰以通天笔至","f":"七言律诗","c":["忍复通天问笔人，涯翁手墨已无真。","路长不惮频封驳，价重真怜一笑嚬。","韩愈传馀还品藻，公权谏后复经纶。","中山未族将军老，恸哭秋原不为麟。"]},{"t":"闻太师公谥文正","f":"七言律诗","c":["哀音到后又而今，节惠初闻出翰林。","千载特操迁史笔，百年如见范公心。","东川有障龙门在，南斗无光壁宿沈。","何地可追尼父诔，在天真若敬皇临。"]},{"t":"李尚宝寄文正公遗书至","f":"七言律诗","c":["死后谁知尚有书，符台缄至益沾裾。","曾知此意吾多负，敢谓今人我不如。","春服从游诸子在，夜堂歌咏几年馀。","篝灯再检平生藁，秋雨江南叹索居。"]},{"t":"邃翁寄文正公志铭藁至","f":"七言律诗","c":["铭公谁秉笔如椽，邃叟知公自蚤年。","曾谓中郎碑可愧，也知裴老画堪传。","遗书数卷真垂世，阴德三朝已格天。","西直门西埋玉地，大书还见表新阡。"]},{"t":"上文正公诗不及见而返用前韵","f":"七言律诗","c":["短歌无和不成音，手牍重开泪雨深。","云隔长安空注目，雁回湘浦独伤心。","迹留篆籀须铭鼎，调绝风骚莫谱琴。","此后秪应江阁梦，西涯云水昼阴阴。"]},{"t":"不寐思文正公","f":"七言律诗","c":["寒听钟清倚枕频，麓堂音断正愁人。","书中未尽言中妙，画里争如梦里真。","九制立挥忙秉笔，三朝坐论缓垂绅。","秪应退食从容地，得与光风几月春。"]},{"t":"送行人喻汉宗之","f":"七言律诗","c":["苍梧云接楚江西，万里南行岭复溪。","使者节从天子所，解元名自省闱题。","家音正值三秋雁，朝报初违五夜鸡。","尚忆宪台冰玉地，独将文字诵昌黎。"]},{"t":"燕冯氏山亭","f":"七言律诗","c":["病后青山似病前，山中流水亦年年。","渊明不饮终辞社，坡老多言漫入禅。","人结晚盟惟竹最，物将春报有梅先。","却怜亭榭邻吾馆，胜日相过共煮泉。"]},{"t":"董感恩道卿自兰溪来访致枫山章公手书诗以谢之","f":"七言律诗","c":["枫山老矣兰溪上，犹为人间抱隐忧。","萸菊年年彭泽酒，江湖处处范公楼。","眼看仪羽翔天表，心送狂澜到海头。","再见未能徒怅怅，道卿十日定须留。"]},{"t":"送道卿","f":"七言律诗","c":["道卿南来登我堂，西风飒飒吹衣裳。","十年话远寒宵短，一瓣香清新月光。","操椠当年曾白鹿，濯缨何处不沧浪。","烦君为吊诸贤墓，朱吕风流在此乡。"]},{"t":"闻秦豫斋讣诗以哭之","f":"七言律诗","c":["辛苦吟诗半世忙，山林朝市两茫茫。","冷官才释穷时褐，壮节还登达者堂。","北野何人收骏骨，东林他日委书香。","清江风雨重阳卷，一读令人一感伤。"]},{"t":"与道卿夜坐","f":"七言律诗","c":["病后相逢似梦中，君归海外我江东。","幽居门径松兼竹，寒日湖山雾且风。","与客登临频有约，著书打坐两无功。","从来吴越邻封地，岁晚寻盟正未穷。"]},{"t":"送道卿","f":"七言律诗","c":["十日留君未尽情，懒从南郭送君行。","千年琴在朱弦老，万里人归白发生。","陆羽祠前泉水活，严陵滩上桂舟轻。","风山问我笺书事，随笔时时不敢程。"]},{"t":"南沙宿知微房奉忆","f":"七言律诗","c":["信宿山中未得陪，老僧独为供茶杯。","一时欠事庭无月，五里馀情野有梅。","文会又从今日起，书评还待后人来。","卧云字在南岩石，好谓知微莫遣苔。"]},{"t":"碑成再赠南沙","f":"七言律诗","c":["三日山中两日陪，病馀犹恨不胜杯。","诗成陆羽千峰茗，梦醒卢仝一夜梅。","汲水客应将石去，看花人只待春来。","大书更有磨厓地，半是云封半是苔。"]},{"t":"数欲叙别于文玉文玉适适鹅湖未果也至是一叙则行期迫矣情见乎辞","f":"七言律诗","c":["新相知自旧相知，近别离成远别离。","拟策已为苏子地，上书还忆汉文时。","律吹和气回燕谷，旌引文星动海涯。","我爱梅花思折赠，江边一树正垂垂。"]},{"t":"予以大魁望文玉久矣久屈而伸其在兹乎诗以志别","f":"七言律诗","c":["春风不负岁寒心，行见莺花满上林。","日下望京千里近，云中叩阙九重深。","良工竟识陵阳玉，清世宁论郭隗金。","瀛水蓬山天只尺，江湖回首忆知音。"]},{"t":"送施子羽","f":"七言律诗","c":["青年文苑恣游观，慈母堂前日问安。","春服试来坛雨霁，夜灯悬处砚冰寒。","琴边山水知应少，药里君臣效亦难。","此去京华须问讯，上林何树可栖翰。"]},{"t":"岁暮遣怀","f":"七言律诗","c":["门前馈岁野人来，手折梅花已半开。","观为江山留晚阁，兴将旬日动春杯。","年占方怪冬无雪，世计还惊夜有雷。","聊托閒情到诗社，两童东去复西回。"]},{"t":"江上瞻云为夏少参赋次涯翁先生韵","f":"七言古诗","c":["洞庭东望海云飞，一棹凌风省使归。","渭北漫愁江树远，衡阳真恨塞鸿稀。","金山寺近连秋浦，黄鹤楼高倚夕霏。","已贵复看颁锦诰，未衰何用著斑衣。","鸟回西极千峰碧，花发东郊十里绯。","寸草有心何日报，高堂无恙几时违。","天涯踪迹散还聚，客路怀思渴更饥。","明到湖南重回首，君山如画带春晖。"]},{"t":"为龚时亨题王中书春流出峡图追次王耐轩学士韵","f":"七言古诗","c":["三峡诸峰画里开，登高不见杜陵台。","一湾水带银河下，千里人从剑阁来。","忽怪乘风遒似马，惯看撇漩小于杯。","冥冥不断楚天雨，濯濯新除蜀道埃。","他日曾悲羁旅客，此图还见出群才。","低悬星斗云边栈，深著烟霞石上苔。","纵使险途经滟滪，也胜弱水隔蓬莱。","百年再和天游句，两绝一时真异哉。"]},{"t":"钓鱼词","f":"古风","c":["芦花秋水浅，不用系扁舟。","便是被风飘去，不到海东头。","莫问蓬莱何处，莫问瀛洲何处，适意是真游。","乾坤千万古，遗下这风流。","一竿三尺线，轻飏钓鱼钩。","更爱相亲相近水中鸥。","不看溪风山月，即看渚蒲汀草，自识春秋。","沧洲吾道在，江汉日悠悠。"]},{"t":"蝶恋花 其一","f":"古风","c":["三年卧病今年好。","二月春寒，又被东风恼。","古人诗语今人道。","傍柳随花方未了。","閒学少年还叹老。","击节长歌，不恨知音少。","流水桥边亭子小。","古琴时有幽人抱。"]},{"t":"蝶恋花 其二","f":"古风","c":["相逢谁谓吟诗瘦。","闻道春来，筋力全胜旧。","曾将春酒遥称寿。","今年准拟明年又。","梦里周公应不复。","笔底春秋，莫问何时就。","老眼摩挲凌宇宙。","一声啼鸟西堂昼。"]},{"t":"蝶恋花 其三","f":"古风","c":["故人千里书中意。","前日江山，今日还增气。","呼童为扫门前地。","观风使者春将至。","行空天马非凡骑。","第二泉头，酌水能心醉。","漫道荐贤名已遂。","桃李笑东风多事。"]},{"t":"蝶恋花 其四","f":"古风","c":["屈指一阳今九九。","绿起郊原，草色无还有。","燕子归来应不久。","主人病后初开酒。","次第春光诗管取。","论清景刚，道是才黄柳。","半醒半醉花开后。","几多人等閒白首。"]},{"t":"思山翁辞二首 其一","f":"楚辞体","c":["山中人兮踰上寿。","饮石泉兮卧岩窦。","女萝衣兮薜荔裳，朝飧霞兮夕白云以为覆。","百草纷兮与邻，予独友兮三秀。","世莫知兮已哉，孰姓予兮何首。"]},{"t":"思山翁辞二首 其二","f":"楚辞体","c":["山中人兮予所求。","梦悠悠兮繇昭昭。","操予锸兮登高邱。","聊尽日兮延伫，招松乔兮千秋。","山中人兮盍从我游。"]},{"t":"水仙","f":"楚辞体","c":["若有人兮江之中，委翠带兮含天风。","敛玉颜兮掩春露，婉清扬兮谁容。","汉之北兮湘之东，将帝子兮吾从。","汀有兰兮岸有芷，恨千古兮如水。"]},{"t":"云庄十石辞 其一 仰高","f":"楚辞体","c":["有石兮山巅，咫尺兮青天。","日延企兮愁予，何星辰兮渺然。"]},{"t":"云庄十石辞 其二 一快","f":"楚辞体","c":["左予顾兮骋怀，下方忽兮云开。","坐商谣兮击石，见双鹤兮飞来。"]},{"t":"云庄十石辞 其三 临沧","f":"楚辞体","c":["山北顾兮又东，云冥冥兮海濛濛。","扶桑眷兮安在，空叹息兮桴翁。"]},{"t":"云庄十石辞 其四 云庄","f":"楚辞体","c":["山苍苍兮白云，白杨风兮夕曛。","怀伊人兮终古，秋吾黍兮春芹。"]},{"t":"云庄十石辞 其五 见素洞","f":"楚辞体","c":["夫何为兮此峰，中砑然兮有容。","云纷纷兮在下，欲跻攀兮焉从。"]},{"t":"云庄十石辞 其六 青野","f":"楚辞体","c":["云际兮山麓，原离离兮芳菉。","天风起兮樵歌，思幽人兮在谷。"]},{"t":"云庄十石辞 其七 碧山","f":"楚辞体","c":["目窅窅兮天涯，岑遥碧兮参差。","望重华兮未极，渺何方兮九疑。"]},{"t":"云庄十石辞 其八 后乐","f":"楚辞体","c":["夙游兮四方，江湖兮庙堂。","眷兹洞兮吾老，何忧心兮可忘。"]},{"t":"云庄十石辞 其九 隐屏","f":"楚辞体","c":["晨彗兮墓前，夕次兮墓左。","有石兮如屏，栖栖兮隐我。"]},{"t":"云庄十石辞 其十 拱北","f":"楚辞体","c":["有石兮应星，万古兮北向。","夕下拜兮老臣，有天临兮在上。"]},{"t":"徐太史薜荔园辞 其一 思乐堂","f":"楚辞体","c":["为山兮既仞，为池兮亦寻。","宛水石兮斯在，昔之人兮此心。","水汪汪兮石磊磊，嗟伊人兮不待。","堂既构兮像悬我，山岳兮池海。"]},{"t":"徐太史薜荔园辞 其二 水鉴楼","f":"楚辞体","c":["楼吾俯兮清流，流之汇兮幽幽。","日徘徊兮延伫，将舍此兮焉求。"]},{"t":"徐太史薜荔园辞 其三 风竹轩","f":"楚辞体","c":["庭翛翛兮疏竹，回岩风兮鸣玉。","轩吾倚兮无言，羌独歌兮淇澳。"]},{"t":"徐太史薜荔园辞 其四 蕉石亭","f":"楚辞体","c":["蕉被被兮石矗矗，纷满亭兮芳菉。","芳菉兮柰何，怀佳人兮蹉跎。"]},{"t":"徐太史薜荔园辞 其五 观耕台","f":"楚辞体","c":["台登登兮山上田，畇畇兮山下。","穑日力兮君欣，君复闵兮农之苦。"]},{"t":"徐太史薜荔园辞 其六 蔷薇洞","f":"楚辞体","c":["菉叶兮朱英，洞窈窕兮若房。","怅青春兮迟暮，犹有寄兮馀芳。"]},{"t":"徐太史薜荔园辞 其七 荷池","f":"楚辞体","c":["采采兮荷华，西之渚兮东涯。","水天风兮香远，淹中洲兮日斜。"]},{"t":"徐太史薜荔园辞 其八 留月峰","f":"楚辞体","c":["月明兮峰景，既东兮复西指。","佳期兮夕骋，扣环窦兮栖栖。"]},{"t":"徐太史薜荔园辞 其九 通泠桥","f":"楚辞体","c":["涧将断兮有石，下潺湲兮玉声。","步既度兮返顾，予焉知兮何情。"]},{"t":"徐太史薜荔园辞 其十 花源","f":"楚辞体","c":["武陵胡然兮震泽隈，花与水兮沿复洄。","怅寻源兮不见，见水流兮花开。"]},{"t":"徐太史薜荔园辞 其十一 石假山","f":"楚辞体","c":["屹有峰兮湖之中。","石际水兮丛丛。","彼日夕兮浪以风。","于我石兮撞舂。","猗兹望兮南东。","谁此池兮此峰。","峰之下兮湖通。","盍观兮焉从。","善齐物兮若翁。"]},{"t":"徐太史薜荔园辞 其十二 柏屏","f":"楚辞体","c":["结琼枝兮若屏，岁云暮兮青青。","春风起兮烟雾，翠为雨兮载零。"]},{"t":"徐太史薜荔园辞 其十三 钓矶","f":"楚辞体","c":["有矶兮水滨，俯幽藻兮青蘋。","鱼鳞鳞兮迎予，梦烟月兮千春。"]},{"t":"天齐渊","f":"七言律诗","c":["东方有渊名天齐，一气下上降复跻。","乾坤生意从东肇，何处山川非地窍。","汉家八神宗者渊，有祠称天今几年。","巍巍惟天山岳岳，巫史纷纷不知错。"]},{"t":"轩辕冢","f":"七言律诗","c":["黄帝已仙今有冢，武皇一语群臣愯。","衣冠葬者对谓谁，千载似为方士俑。","谀臣诞谩不足非，有冢岂徒冠与衣。","董生汲直乃安在，牖纳空嗟失此机。"]},{"t":"嵩呼曲","f":"古风","c":["何处声声万岁，帝升中神灵会。","谷中人或有呼，新垣平何代无。","万岁声尝屡见，楚东城汉前殿。","帝方信臣敢疑，啸也歌樵牧知。"]},{"t":"二马篇","f":"古风","c":["生马铜铸像，死马金买骨。","生像未置门，死骨终埋窟。","国当冀野君知马，一心真，一心假。","一称骥德一招贤，异事流传今几年。","但闻当时有郭隗，焉知后世无优旃。"]},{"t":"明妃怨","f":"古风","c":["无金赂画师，幸免入宫妒。","谁知出塞愁，却以无金故。","望望紫台沙万里，妾无一生有二死。","一死绝呼韩，一死谢天子。","谋身不易谋国难，只尺眼迷青与丹，琵琶合向娄生弹。"]},{"t":"卧龙起","f":"楚辞体","c":["鼎三兮，卧龙起。","表两陈，卧龙死。","老龙跃，方未遐。","少龙变，乃为蛇。","卧龙嘘，已成云。","云不雨，天昏昏。","万古恨，臣无君。"]},{"t":"饮酒","f":"古风","c":["归来归来，饮酒饮酒。","东风吹绿门前柳，春光媚人我何有。","梦中境，醉中身，百年自作羲皇人。"]},{"t":"山人归","f":"七言古诗","c":["白衣山人入山去，黄衣山人留不住。","临别无言还有心，有言不似无言深。","山深人远心只尺，云去云来本无迹，相见无期两相忆。"]},{"t":"饶娥哭","f":"古风","c":["父溺死，女死哭。","丑类从尸浮，应有神为戮。","人心诚，水神灵。","溺者今何限，不闻号恸声。","水怪水怪方纵横。"]},{"t":"读元史","f":"古风","c":["大都图籍帝使收。","群儒秉笔谁春秋。","仲尼可作史可修。","如不可作，迁固之例吾当求。","不然吾将为夏游。"]},{"t":"蜂冢叹","f":"古风","c":["一蜂存，众蜂止。","一蜂亡，众蜂死。","冢累然，胡有此。","一蜂君，众蜂臣。","谁谓蜂，不如人。"]},{"t":"弃儿叹","f":"古风","c":["弃儿水中儿不沈。","挥篙指水恨不深。","妻骂夫忍心。","饿死死明日，溺死死在今。","妻骂夫，真忍心。"]},{"t":"绣岭寿藏四景 其一 左石","f":"七言古诗","c":["有石有石其形厖，厖且偃蹇名宜床。","篆题者冰刻自唐，介我双松左寿宫。","风来松间如鼓簧，客抚斯坐长苍苍。"]},{"t":"绣岭寿藏四景 其二 右松","f":"楚辞体","c":["松兮离立，兄及弟矣。","二龙乘云，独未离乎地也。","古亦有言，维德不孤。","贤哉大夫，我作寿域，宜有此夫。"]},{"t":"绣岭寿藏四景 其三 前泉","f":"古风","c":["我泉我池，源源其来。","我池我泉，不绝涓涓。","既清且涟，汇于我前，何千百年。"]},{"t":"绣岭寿藏四景 其四 后岭","f":"楚辞体","c":["岭兮如屏，孰为之绣。","彼桃万株，厥亦惟旧。","山之苍苍，朝烟夕霞。","千载武陵，非仙家邪。"]},{"t":"寄题湖南汲福井","f":"古风","c":["昔之日，此井竭。","今之日，此井渫。","水由地中，功上出叶。","往来汲汲寒泉洌，六月焚如道无渴。","君不见朝宗江汉在此州，水哉能止还能流，召棠蔽芾今歌周。"]},{"t":"观水谣","f":"古风","c":["东南风，湖水生，西北风，湖水落。","昨日今日皆天风，不见水往来，但见郊原成一壑。","海深如，不容洪流横复纵，都水使者难施功。","三江不为江，震泽不为泽。","岳阳何处楼，长啸洞庭窄。","君不见山东不雨夏接春，赤地千里还愁人。"]},{"t":"秋日谒张中丞庙有感","f":"古风","c":["睢阳令，锡阴庙，唐室功宗我明诏。","公神如水行地中，掘井得泉本无窍，万古丹心天日照。","君不见毗陵在宋唐，睢阳岿然保障东海傍。","至今遗恨国不吊，忠义祠前一瓣香。"]},{"t":"题买糕陈孝子卷","f":"古风","c":["昨日一糕，今日一糕，明日又一糕。","三年不为久，卅里不为遥。","仙人不在杨泾桥，灵药不在葫芦瓢。","苦哉孝子心，一念通神霄。"]},{"t":"代风答","f":"五言古诗","c":["风风无不公。","高堂若无夏，破屋元有冬。"]},{"t":"荆葵叹","f":"古风","c":["麦萎太半荆葵多，不独稂莠妨嘉禾。","荆葵作粉堪食饿，稂莠稂莠无一可。","嗟彼小人无才为稂莠，有才为荆葵。","大都害君子，观物兴予悲。","荆葵多，勿复道，四虫恣食三秋老。"]},{"t":"周文襄公颂","f":"古风","c":["我怀文襄，古之遗爱。","去公百年，典型犹在。","惟遗爱一言，寔自仲尼。","称郑之侨，今千载馀。","继者何少，子产初政。","人欲杀之，歌者如水。","及再歌也，又恐其死。","公之始至，白地有谣。","经营宣力，二纪三朝。","苟利于民，遑恤在已。","我思古人，子产哉是。","儗名山嘉树，孰非甘棠。","勿剪勿代，公貌在堂。","我门于题，于戏不忘。"]},{"t":"修庙学诗九章","f":"古风","c":["翼翼庙学，维邑于教。","弦斯诵斯，自昔斯肇。","有宫有墙，有坛有堂。","孰今斯荒，乃或不蘉。","御史来视，盍修曰亟。","彼淫是驱，亦维我职。","我其敢解，我材孰资。","其萃有丘，孰其我釐。","维范侯是咨。","烨烨范侯，维秦之彦。","既左京尹，徵文考献，乃躬克践。","矧是政先，侯不是共。","侯曰尔吏，尔徒尔工。","曰斯斯石，曰斯斯木。","乃楹乃桷，枉矫端复。","乃髹乃涂，乃朱乃绿。","祭有丽牲，射有栖鹄。","古人有言，勿亟日成。","侯旬侯月，亦莫我愆程。","源源泮水，下通于溪。","我庙维东，我学维西。","有峨者阁，登登其阶。","共维圣谟，式崇于丌。","是训是稽。","既考乃毕，有酒芬苾。","有礼秩秩，有碑纪功，惟长御史之笔。","御史崇正，诏有德音。","我侯承只，式如其心。","庶士向风。","维我衣冠，其观继继。","就不侯绳，而未克既。","小子作诗，敢曰能雅。","是篆是歌，以告来者。"]},{"t":"春思集古四首 其一","f":"五言律诗","c":["感物多情思，借问此何时。","朝霞开宿雾，高杨拂地垂。","日华川上动，流莺复在兹。","上山采琼蕊，君在天一涯。"]},{"t":"春思集古四首 其二","f":"五言律诗","c":["丹霞蔽阳景，白水满春塘。","庭中有奇树，含英扬辉光。","逍遥独延伫，仰视浮云翔。","东风摇百草，渥露沾我裳。"]},{"t":"春思集古四首 其三","f":"五言古诗","c":["维昔逢休明，朝游登凤阁。","端饰相招携，未尝废丘壑。","且还读我书，极望无崖崿。","遥心逐奔龙，双阙百馀尺。","幽缄候君开，晦明如岁隔。","盈盈一水间，勤思终遥夕。"]},{"t":"春思集古四首 其四","f":"五言律诗","c":["青春速天机，时与赏心遇。","闺草含碧滋，开花已匝树。","风帘入双燕，缅映石壁素。","物我俱忘怀，愧无古人度。"]},{"t":"集古寄浦文玉","f":"五言古诗","c":["十载朝云陛，长安游上才。","犹忆严冬月，萧条江上来。","暮春和气应，献策抒中怀。","阿阁丽朝日，凤鸟方翔回。","岂不念良友，远在天一涯。","我亦疲我梦，登登九成台。"]},{"t":"春晚独步","f":"五言古诗","c":["萋萋春草繁，夕阴结空幕。","升月照帘栊，旷野增寥索。","纤纤如玉钩，夜移河汉落。","众星环北辰，悠悠方仪廓。","安得恒逍遥，游原采萧藿。"]},{"t":"春日独坐","f":"五言古诗","c":["暮春和气应，养痾亦园中。","心迹双寂寞，启扉面江南。","一觞虽独进，情深意弥重。","桃李成蹊径，青林结冥濛。","爱而不可见，永怀求羊踪。"]},{"t":"斸笋","f":"五言古诗","c":["一斸复一斸，山中笋如玉。","箨龙有嘉名，头角方簇簇。","朝露晞午风，清磬旁纷郁。","纳之紫筠笼，琼茅以为束。","持归献慈亲，一笑不知肉。"]},{"t":"答盛汉臣","f":"五言古诗","c":["不见希斋翁，门人见水石。","别我十年馀，新诗慰春夕。","高空蔼晴云，君才似张籍。","又如帆风江，千里指南极。","山中有流泉，曲处堪布席。","一杯欲共君，古风久寥寂。"]},{"t":"新泉效李白体","f":"五言古诗","c":["閒人有幽赏，乃在山下泉。","水声六月冷，白石净娟娟。","倚杖对青壁，上有瑶柯悬。","海天三百里，一勺方流涓。","仙人陆鸿渐，遗世已千年。","芳骨如可起，裹茗谈烹煎。"]},{"t":"怀五老峰寄赵博士立之","f":"五言古诗","c":["落落复落落，泛舟蓉湖西。","安得五綵虹，架天作长梯。","南望瀑布水，舒卷青云齐。","上有五老者，翱翔紫云霓。","具寄一书札，浩思极冥栖。","楚谣对芳草，苍然夕烟迷。"]},{"t":"观泉巾","f":"五言古诗","c":["织騣复织騣，制此头上巾。","有名合从我，我是观泉人。","无缨不须濯，山中况无尘。","百坡既已夥，一角亦非真。","萧萧九峰雨，秋风送凉新。","吾自爱吾物，悠然梦千春。"]},{"t":"静怀","f":"五言古诗","c":["人讥不能休，我患不能仕。","仕岂簿领间，所执谅有以。","古人复何人，渠耻予亦耻。","老恨幼学疏，病怪虚名起。","圣明无遐遗，只尺千万里。","傥念将母艰，綵衣又兹始。"]},{"t":"秋夜","f":"五言古诗","c":["青天一片月，万古中秋期。","我生自能视，六十一遇之。","孩童不足论，弱冠始有知。","有酒不能饮，而况能吟诗。","天道有阴晴，世途多别离。","高思华峰顶，旷忆沧江湄。","幽居未成往，对影空嗟而。","今逢圣明运，适我病起时。","东亭海云散，寒光益轩墀。","邀我平生友，清尊复在斯。","今夕如不乐，问君欲奚为。"]},{"t":"题邹氏恒贞卷","f":"五言律诗","c":["恒贞有吉占，易为妇人告。","从一亦何占，我心匪陵谷。","五十被旌书，六十受多福。","之母古硕人，百年洁如玉。"]},{"t":"熊女诗","f":"五言古诗","c":["古人重挂剑，为不负初心。","妾身非剑比，一诺千黄金。","谁谓妾无言，有言出母口。","谁谓妾无书，有书出父手。","未见悲益深，空房甘独守。","白日一何迟，黄泉一何远。","妾岂不爱生，所恨从姑晚。","卫女先我心，适齐不中返。"]},{"t":"点易台待月","f":"五言古诗","c":["待月月在天，待明不待上。","月明松影来，风静流泉响。","与客谈羲文，乾坤入指掌。","山中本无尘，况有出尘想。","云崖去我近，只尺三百丈。","归欤兴未阑，月色随藜杖。"]},{"t":"遗慕为许直赋","f":"五言律诗","c":["父死儿未生，儿生不知父。","问母父形容，十问还九误。","一念自提孩，哀哀到迟暮。","我作遗慕篇，悲歌动行路。"]},{"t":"和陶韵二首 其一 真想","f":"五言古诗","c":["壮志迈千古，尽读天下书。","北登黄金台，四顾意旷如。","献策见天子，致身在云衢。","乔木凌霄汉，落落影扶疏。","周行数万里，翱翔复萦纡。","叙迁历中外，令望长有馀。","横流须巨石，公也孙不居。","渠渠犹夏屋，建业亦多鱼。","真想和陶什，不为韵语拘。","俯仰天地间，何方不籧庐。"]},{"t":"和陶韵二首 其二 遥情","f":"五言古诗","c":["无才有积病，我负二宜休。","五十为亲养，恳乞江东游。","入爱萱草荣，出欣泉水流。","野服听沧浪，近有忘机鸥。","前时堂中人，今为山下丘。","一拜扶两仆，敢望夔龙俦。","岂不念上德，万一涓埃酬。","长揖谒廷陛，此事今有不。","近步亦藜杖，遥情抱幽忧。","柴桑有遗矩，吾当此中求。"]},{"t":"题阙","f":"五言古诗","c":["上有千竿竹，碧影翻阶墀。","我归自南省，方当静脩时。","挈我二三友，讲斯复游斯。","昼诵掩虚室，夕眺摩残碑。","古琴弄淇澳，赓以南风词。","别去三十载，往往梦见之。","圃蔬未足叹，伤哉草离离。","西游且北览，何以慰夙期。","云生志复旧，作堂请新规。","我昔寓白鹿，尝以图志来。","愿言植嘉木，绿阴散繁枝。","愧兹未能赋，聊作林堂诗。"]},{"t":"巨然山寺图用虞邵庵韵","f":"五言古诗","c":["古寺据崇岭，亦复设远关。","中有苦行僧，终岁不下山。","长松结深霭，釐然界尘寰。","双瀑落悬厓，涧声日潺湲。","殿堂栖古佛，长有云半间。","阁登一纵目，目过心自閒。","朝送白云去，暮迎白云还。"]},{"t":"梦药诗","f":"五言古诗","c":["醉后谢山翁，梦中闻地瘿。","仙人戴唐巾，飘飘发垂领。","口诵复掌画，除子旧疾疢。","觉来检草经，逢人辄言请。","尔来数月馀，笑我捕风影。","人从芜湖来，自谓能记省。","此物出巴陵，近始露茫颖。","不知掘者谁，殆如金出矿。","或将汤液之，神功在俄顷。","某也病中风，不死亦天幸。","林居十五年，吾亦爱吾胫。","从兹矢长服，不敢一日屏。"]},{"t":"谢冯佥宪惠文石","f":"五言古诗","c":["昔见石如松，今见石如竹。","如松纹在皮，如竹纹在肉。","纵横金错刀，凌乱锦一幅。","置之山亭中，为案比青玉。","焚香对初阳，古书时展读。","问之赠者谁，仙人粲山麓。","欲报何所将，寒泉手堪掬。"]},{"t":"煎茶寄吴封君","f":"五言古诗","c":["浊醪有妙理，清茶尤苦心。","采茶阳羡阳，汲泉惠山阴。","秋水碧如玉，百沸成黄金。","此中亦何味，请听希声琴。","陆羽久仙去，千载空遗音。","卢仝不言法，七盌最独深。","吴翁二子流，清风起山林。","陶匏介垆竹，煎竟还自斟。","京师一饮我，再饮荆溪浔。","迩来虽裹寄，烹事吾谁任。","报君一罂水，撱石仍中沈。","临发更致语，新火君当寻。"]},{"t":"石床行","f":"古风","c":["惠山石床古有之，声声松子金风时。","皮休题诗李冰篆，千秋并作山中奇。","山庵之名本缘此，石也移来应偶尔。","游人玩侮等寻常，识者共怜非所止。","墙西松树几百春，大围三人小二人。","此松此石雅相友，乾坤无心物有神。","二泉山人爱观物，谓物皆然胡独不立。","破颓垣，遣往参，却笑他年两湮郁。","君不见赤松子，黄石公，姓名久落荒唐中。","酒酣击节发清啸，春深绣岭回天风。"]},{"t":"寄题阁老费公至乐楼","f":"七言古诗","c":["黄阁仙人天上还，幽兴却寄溪山间。","横林深处起重屋，别有眼界非尘寰。","群溪东来向西去，流到龙溪两倾注。","白云飞尽见三峰，政在先生倚阑处。","乾坤一览万古心，北南名胜皆登临。","子长胸次仲淹思，每与山水增高深。","岂知几案有至乐，欧老诗如为公作。","先人种树今数围，槐影重重松落落。","阳春坐我还清秋，静观万物成天游。","半江露白月照水，两涯草碧云生洲。","我行湖东数过此，尚忆清扬在中沚。","病馀偶接季方书，世事茫茫公老矣。","岁月无端白发多，江湖地远心如何。","苍生未起谢安卧，溪上往来空棹歌。"]},{"t":"三门行送刘学正赴陜州","f":"古风","c":["君不见黄河之水从西来，东行万里到陜郡，有石横亘势欲回。","天教禹凿三门开，百川风雨万壑雷。","下孰为之挽，上孰为之推。","当时神禹何不一凿去，留此险阻胡为哉。","玄敬为予言，神门在中人北际，鬼门居南不可济。","水争石斗两无情，地险天生难尽弃。","乾坤万古一奇观，节宣亦为狂澜计，不然下此复有底。","柱山形如滟滪当江间，应愁一倒不复还。","识者观风似观水，作人之道固如此。","寥寥古调数千年，青眼高歌对吾子。"]},{"t":"赤壁图歌次西涯先生韵为华生云作","f":"七言古诗","c":["长江无声动吹万，月上东山度河汉。","东坡词赋思千秋，客吹洞箫如发难。","兴亡有恨客心苦，不独曹吴堪扼腕。","汉家心腹已摧伤，手足安能相救捍。","猛风东来水倒流，南军北军忽相乱。","天公助顺不助逆，若论成功犹未半。","华容道远老瞒愁，周郎渡江江有岸。","朝宗江汉本无心，蜀浪吴潮各分散。","巴丘哀罢又瘴乡，为国意忘天下患。","后人吊古对江山，坐遣胸中置冰炭。","洞萧声尽客何言，似笑老生谈熟烂。","百年水月坡翁心，泛泛不知身在窜。","明朝酒醒赋初成，白雪调高歌欲断。","西涯居士今东坡，逝矣岁星今几换。","画图流转到东吴，诗句人将史书看。","华生况是知音人，击节向余三赏叹。"]},{"t":"寿毛都宪","f":"七言古诗","c":["功名早拟登麟阁，中岁归来问林壑。","临观何处不江湖，范老文如为公作。","方今才望谁如公，郧阳节钺南畿同。","十年朝野均劳后，四省兵民总制中。","江汉朝宗两支水，公心耿耿真如此。","折冲千里笑谈馀，某也曾闻古君子。","公无上书称引年，我为公歌岘水篇。","羊公杜公各片石，更道人间别有仙。","中原之民望公久，过我山中还饮酒。","前年曾寿守溪翁，侑者罂泉诗一首。","春来江上多风波，船如天上闻公过。","白云黄鹤武昌渚，试看东流今若何。"]},{"t":"尚书台纪梦次万晦之韵","f":"七言古诗","c":["昔之梦似今之所，吾台谁谓前无古。","寻常灌莽接松楸，突出烟霞三百武。","青云有阶人可得，轻举尤须藉风伯。","小池新引露泉清，大笔深刊厓石白。","海天佳气从东来，一滴万古真水哉。","金春玉应碧山静，道人对此方心斋。","西岭东峰拥前后，一方真与乾坤久。","危厓铁笛夜凄清，城市茫茫失尘垢。","高丘远海谪仙诗，歌声入云云欲飞。","先天有易本无画，谁向清溪问点为。"]},{"t":"赠东湖","f":"七言古诗","c":["东湖来自东海涯，到山先拜梁溪祠。","梁溪先生千载士，文章德业真吾师。","前公来时未有此，我归方浚吾泉水。","此时此地复此泉，青眼相看更吾子。","草蔬一饭正愧予，野人忽馈深溪鱼。","急烹入馔肥且硕，此事真合牵联书。","泉傍有台名点易，昔梦依稀尚能忆。","高丘远海谪仙诗，歌对沧茫两无极。","平生知己主一翁，几回墓草经秋风。","因之尚论文庄叶，遗录今谁问水东。"]},{"t":"次王郡公煎茶行","f":"楚辞体","c":["今之诗伯溪上翁，六年为郡声隆崇。","一清如水比泉德，馀兴却慕茶仙风。","贪夫见公不自省，公眼白兮心非瞢。","诗来遣吏问茶法，茶法酒法将无同。","酒成曲糵过乃敝，酒之甘苦茶淡浓。","竹炉石鼎文具耳，妙手只在调和中。","大才于物无不可，岂以一艺称诗工。","何时鼎鼐入公手，汉室行徵黄次公。","惠山泉上节屡驻，甘棠勿伐何丛丛。","公虽爱酒不如晋，茶乎谁许唐人仝。","二泉山人爱泉者，欲茶每与山僧假。","芝歌未已复茶歌，共喜山中得风雅。","饮公醇者西坡笃，读书茶经犹不足。","烹煎未解吾何言，愿乞吴翁为君告。","吾泉上人不欲多，西推山瀑东江波。","仲尼饮水别无法，此味不知今若何。"]},{"t":"寿华封君七十","f":"古风","c":["文华侍书凡几年，权阉斥逐江南田。","翰林有子领京荐，飘然同上嘉兴船。","事定移家还辇毂，清风如水人如玉。","百年共肃世守之，雅称东藩画中竹。","君不见谏垣回首江湖长，南极星高北极光。","向来夷险何足道，莱衣春酒封君堂。"]},{"t":"谢王郡公惠风折古柏用杜韵","f":"七言古诗","c":["郡公书致郡堂柏，珍重真胜二千石。","若非风雨起秋潮，此地何人敢绳尺。","岁寒尚有不拔者，此两三株何足惜。","相知相馈惟此物，公也清廉心愈白。","鄙人谢病江水东，方为吾亲营寿宫。","贞节碑成阁老笔，鬼神诃护青山空。","客来劝我作亭子，少蔽上雨兼傍风。","工师求木苦无力，得此立可观成功。","小者为槛大者栋，材之良矣情尤重。","召伯风能为我留，杜陵诗不愁谁送。","亭前故有两危柯，松可鹤巢梧可凤。","公材自合柱明堂，历尽冰霜终大用。"]},{"t":"题画竹","f":"七言古诗","c":["石涧潺潺楚江曲，上有猗猗万竿菉。","天风时来起众音，如金如玉皆无心。","萦回成文妙天下，物理相资不相假。","听之未足观有馀，春云匝地秋天虚。","我行潇湘数千里，此景随人何迤逦。","谁其图者琴川翁，造化又在生绡中。","披图忽忆旧游处，九疑如烟水东注。"]},{"t":"寿毛夫人","f":"古风","c":["见母之母如见母，恨不百岁还千秋。","此心真似南山石，有酒深如东海流。","毛夫人，秦母母。","德俪中丞真作友，汶也受恩独良厚。","果钱药饵远劳心，衣线谁云不亲手。","砺翁致政方一年，夫人七十开寿筵。","两阶班出诸孙后，百里心悬二卣前。","一词我为汶称祝，二老高堂双碧玉。","庭兰有茁桂亦芳，凤在梧桐鸾在竹。"]},{"t":"题画","f":"古风","c":["千峰万峰云复云，瀑布上自天河分。","峰头五老镇长在，呦呦鹿鸣犹声闻。","问之此境是何地，无乃庐麓鄱湖濆。","平生爱此难再到，空羡画笔超尘群。","世人笑我太迂癖，有眼错认南康军。","苏门少室亦曾历，卅年别后劳心魂。","黄楼滕阁近城市，大观祗在江东奔。","画中所见皆不类，烟霞入望徒纷纷。","君不见跫然空谷慰岑寂，相契于心不于迹。","杨郎击节似知音，大轴卷还江上客。"]},{"t":"题吴从周狻猊图","f":"古风","c":["厖然大物名狻猊，丹青何处貌得之。","曾闻宣德有此贡，流沙万里牵来时。","茜红?毹金锁络，壮士如云共挥霍。","铜睛铁额照上林，守有啬夫拘有柙。","熊栏豹槛海子傍，狎视群兽如群羊。","寻常莫试纵擒手，此物骄悍无能当。","上林风高秋日暮，野心应尔关西路。","左钳右掣不得行，一吼乾坤为谁怒。","今人豢虎古豢龙，云沈风郁皆无功。","狻猊狻猊，嗟尔非龙复非虎，饱食兀兀将安庸。","君不见孝宗弘治初春秋，西人贡狮南海头。","数行诏下直遣去，中国圣人歌我周。"]},{"t":"擒虎行","f":"古风","c":["一日擒一豹，两日擒两虎。","绣衣使者到荆溪，三日尽知民病苦。","使君诏县令，县令召猎户。","赏格高悬网新补，尽道使君仁且武。","使君谓父老，汝邑昔有周处公。","力与蛟虎争长雄，不知名落三害中。","斩蛟杀虎翻然改行收奇功，今人古人性本同。","彼哉名在丹书欲焚者，能言擒虎自效吾其从。","甲能独当乙并力，所不汝贷有如此溪石。","一鼓再作，声如风雷。","山谷响应林木摧，丑类欲逃安往哉。","一虎复一虎，一豹复一豹，从今日日闻飞报。","君不见山南山北行人多，争和使君擒虎歌，何处乡村愁政苛。"]},{"t":"两节妇诗","f":"楚辞体","c":["姑哭良人十载前，妇哭良人十载后。","夜深星月入空帷，一盏青灯两相守。","姑前孀居二十四，妇后孀居一十八。","谁言人事有易难，两节相成竟颃颉。","姑心竹有节，妇心井无波。","文章师傅史迁笔，姑兮妇兮千载名不磨。"]},{"t":"许道宁秋山晴岚图","f":"古风","c":["春山岚重秋山少，宿雾浮烟亦昏晓。","千峰万峰爽气生，望入虚无俱缥缈。","画图到此须写真，许君笔力真能神。","丹丘博士有巨眼，谓是晚年尤可人。","题诗更得鹿场子，万里秋旻双决眦。","本来面目见苍厓，笼罩谁加青与紫。","乾坤无心四时改，万变消沉一真在。","古人观物复今人，秋色无端几千载。","君不见邹君得此爱如玉，长卷装潢更犀轴。","何当携上九龙巅，南望湖天送孤鹜。"]},{"t":"择庵赠周用仁","f":"七言古诗","c":["择庵择术如择邻，家传医道能通神。","庵中读书二十载，养得满腔多是春。","春来沴气方流转，择庵出门无近远。","独将一点天地心，厉鬼闻之亦遄返。","吾家诸子婉清扬，一疾偶到沉痾乡。","择庵谓此不足治，坐令二竖违膏肓。","我为题诗当金帛，声动东阡与西陌。","杏林红映橘泉清，回首龙峰片云白。"]},{"t":"双松图寿司徒秦公","f":"古风","c":["一春三寄寿公诗，未尽平生爱公意。","清秋忽展双松图，于我初心乃深契。","乔柯落落生涧阿，下荫流泉上云气。","万古长撑雨露天，四时平视冰霜地。","问谁作者宋季人，一幅生绡墨尚新。","题诗千里应尊酒，岁寒标格当青春。","君不见司徒嘉绩奏三载，只尺天颜真简在。","麟袍玉带照贞姿，四海人方仰风采。"]},{"t":"喻太安人七十","f":"古风","c":["秋官郎中纯孝人，慈闱中有希龄亲。","昔从北阙乞南省，板舆迎共金陵春。","春光媚人乡只尺，舆出都门指无锡。","翟冠象服对诸孙，百有千年未终极。","山花有芳溪有鲜，野人时送来堂前。","郎中东望拜南极，九峰青映沧溟天。","司寇所司彝典系，平反为仁断为义。","郎中持此答慈闱，万古萱花一生意。","君不见西望瑶池降王母，画图今乃在人间。","人间懿德不胜述，一览春风生笑颜。"]},{"t":"为莫临安曰纯题画","f":"七言古诗","c":["千峰乱历岐山青，秋天怅望开翠屏。","乾坤何处下鸣鸟，野人漫谓山鸡形。","姬公召伯日以远，世道江河几流转。","生绡数尺悬我前，万古愁怀一消遣。","南溪之上桐树林，君家楼高溪水深。","而翁登我歌且啸，有招不来伤我心。","君游江湖倘奇遇，黄陵庙下舟曾住。","云隐苍梧柰望何，独有东流可分付。"]},{"t":"耆英图歌寿钱东湖八十","f":"古风","c":["宋之洛社唐香山，清风长在天地间。","元丰遗像十三子，千古勋名问青史。","西都回首但青山，五百馀年那有此。","柽社曾临郑奂图，风流今落钱东湖。","东湖晚隐东海上，天送烟霞入屏障。","年来大耋庆生辰，嘉客登堂还揖让。","唐人萧散宋人雅，异代衣冠不相假。","君不见文潞公，富韩公，好贤真有缁衣风。","旷世相感难相逢，前有香山居士后有东湖翁。","读书堂在虞山东，虹飞丹井湖波红，千二百岁逍遥中。"]},{"t":"春满东郊图赠游二尹","f":"古风","c":["东郊昨夜春风起，千挺琅玕烟雨里。","箨龙隐地惊新雷，踊跃出土如相催。","旧干凌云方未艾，新枝头角居然在。","章江西来浪捲空，此君得水应为龙。","丞哉负君君自玉，哦松之馀无不足。","我昔知君今更深，为君题画输君心。","君不见息斋墨妙君须识，虚心如竹贞如石。"]},{"t":"春雪独坐","f":"五言律诗","c":["春雷还见雪，二月不胜寒。","山色愁频望，梅花笑独看。","窖蒲柔怯盎，畦菜冻羞盘。","庭草青如许，因渠更倚栏。"]},{"t":"红梅未开用春雪韵","f":"五言律诗","c":["红梅才两蕊，犹自茹春寒。","出以希争睹，开应半好看。","正怜香入坐，未论实登盘。","笑我迂狂甚，巡檐更倚栏。"]},{"t":"风雨阻山行柬如山","f":"五言律诗","c":["偶约山中路，其如风雨何。","花期怜客甫，茗事负僧陀。","柳岸渔翁艇，松坡牧竖蓑。","此时应入画，无计一相过。"]},{"t":"喜子春至用前韵","f":"五言律诗","c":["千里天台客，重来喜柰何。","郡传一手劄，寺问两头陀。","野史操无简，山人卧有蓑。","隔年期故在，不放仲春过。"]},{"t":"哭杨长史宗周","f":"五言律诗","c":["五更哭声起，已矣叹斯人。","留剑还知树，回槎已失津。","榻悬新月夜，社散故山春。","咫尺桥东路，相过独怆神。"]},{"t":"张提学留精舍三日别去诗以寄之","f":"五言律诗","c":["欲尽平生语，匆匆客又东。","山中三夜月，江上片时风。","荒径芟方始，寒泉汲未穷。","逢人询我病，莫论著书功。"]},{"t":"明水草堂次守溪王公韵","f":"五言律诗","c":["泽国连平野，青山路始分。","草堂斜带水，石径细穿云。","月谷三更籁，风漪万古文。","主人招舞鹤，时起白鸥群。"]},{"t":"述喜","f":"五言律诗","c":["闻道銮舆返，南来两报同。","浮云开北极，久雨转东风。","病力慈闱下，欢声醉社中。","惟应操短简，日课著书功。"]},{"t":"赠吴道士","f":"五言律诗","c":["羽人偶相过，野服带烟霞。","处处山中药，年年海上槎。","寻常聊作客，三十早辞家。","何日天风便，蓬莱海一涯。"]},{"t":"寄恽宪副功甫","f":"五言律诗","c":["八载荆南使，忧勤欲白头。","歌声斫地剑，行色济川舟。","岁月空成晚，江湖况及秋。","平生范老记，一读一登楼。"]},{"t":"寄夏参议如山","f":"五言律诗","c":["书破来鸿在，情深柰鼠何。","黄花十月雨，白草九江波。","云梦荆人猎，潇湘屈子歌。","淹留君太久，吾道竟蹉跎。"]},{"t":"避暑山中答莫如山","f":"五言律诗","c":["残暑未受遣，有诗来故人。","数行犹觉少，三复不知频。","竹径留题近，松坛入梦新。","朝闻参赞语，传慰到慈亲。"]},{"t":"林见素翁寄沙鱼翼","f":"五言律诗","c":["远致沙鱼翼，山亭见海天。","银丝抽出细，韭叶藉来鲜。","制法留新简，尝时赋短篇。","若人南斗重，风味亦堪传。"]},{"t":"月夜","f":"五言律诗","c":["长怀七月望，赤壁有人游。","此夜复明月，吾亭如小舟。","笛声兼籁起，槎影带星流。","客动登高兴，台峰最上头。"]},{"t":"避客","f":"五言律诗","c":["避客游山馆，高秋霁景鲜。","方修初服地，况近始生年。","云影秋潭底，松枝晚阁前。","老僧迷眼界，谓我羽衣仙。"]},{"t":"出郭","f":"五言律诗","c":["雪后行南郭，茅堂处处开。","漫投新岁刺，偶接故人杯。","径指梅如迓，帘看燕欲来。","溪桥回首地，塔倚少城隈。"]},{"t":"过惠麓","f":"五言律诗","c":["胜寺游人少，春深不见春。","茶留僧供淡，草唤客愁频。","野望时时极，途号字字真。","吾衰敢忘世，无语独伤神。"]},{"t":"登东冈舒啸亭复之厚本庵","f":"五言律诗","c":["舒啸东皋上，翛然见麦秋。","短篱花气煖，深树鸟声幽。","家报源源至，宾斋信信留。","多情还吊古，斜日到林邱。"]},{"t":"喜何梓材至","f":"五言律诗","c":["入城先过我，应只为论诗。","思在停云地，情如泛雪时。","风前歌更激，雨后句偏奇。","避暑松阴石，相逢不可期。"]},{"t":"送王子春还天台","f":"五言律诗","c":["天台人欲去，把酒问桃花。","履向山中石，裾凌海上霞。","一经终遁世，数亩自成家。","更作明年约，春泉共煮茶。"]},{"t":"坐月诗五首 其一 二月八夜月","f":"五言律诗","c":["此夜看明月，新晴光满庭。","草边留雨碧，树杪失烟青。","世事停杯问，书声隔院听。","从今渐圆满，夜夜照东亭。"]},{"t":"坐月诗五首 其二 九夜月","f":"五言律诗","c":["此夜看明月，黄昏正可庭。","微生酒波渌，轻引烛烟青。","小酌元无约，高歌若有听。","开轩步清影，梧竹两亭亭。"]},{"t":"坐月诗五首 其三 十夜月","f":"五言律诗","c":["此夜看明月，从东渐过庭。","一方心共白，独对眼逾青。","即有帘能卷，那无笛可听。","梅花未全放，诗在影中亭。"]},{"t":"坐月诗五首 其四 十三夜月","f":"五言律诗","c":["此夜看明月，还过昨夜庭。","梅于溪上白，山是雨前青。","光霁真堪坐，阴晴不可听。","明朝诗客去，何处忆吾亭。"]},{"t":"坐月诗五首 其五 十四夜月","f":"五言律诗","c":["此夜看明月，悬如镜在庭。","即令心境白，安得鬓丝青。","槎客他年到，裳歌何处听。","冯谁纪佳兴，十日六登亭。"]},{"t":"观泉和叶巡按","f":"五言律诗","c":["柱史心如水，观风及我泉。","评于唐客外，诗在宋人先。","寒响回云壑，春流带野烟。","閒来驻骢马，入寺不参禅。"]},{"t":"西郭","f":"五言律诗","c":["新霁行西郭，青畴接野泉。","小车随水曲，高屋指云边。","山沐欣今雨，湖颴忆去年。","浩歌乘夜月，何日泛溪船。"]},{"t":"冬日与王元信访许东庐于梅里","f":"五言律诗","c":["携我平生友，东庐访故人。","近来身更健，静里趣愈真。","白屋支新柱，乌纱戴旧巾。","不须谈世事，谈罢恐伤神。"]},{"t":"青山道中","f":"五言律诗","c":["踏月青山路，青山半白云。","千峰如速客，数月已期君。","林籁随风息，潮光隔渚分。","登台问泉水，滴滴细还闻。"]},{"t":"送张汝立 其一","f":"五言律诗","c":["尘海风波定，山林径路深。","閒情能对酒，雅调尚留琴。","隔岁论文地，平生点易心。","归舟经玉峡，老树晚萧森。"]},{"t":"送张汝立 其二","f":"五言律诗","c":["山中方独吟，客至共登临。","城塔回高鸟，溪帆送远林。","乘槎如有约，坐树亦何心。","明日东吴道，相思迟尔音。"]},{"t":"田司谏白砚","f":"五言律诗","c":["闻道端溪上，佳人类玉成。","墨蒸云气重，朱滴露华清。","皓皓怜长濯，庚庚陋大横。","公心如皦日，自尔献承明。"]},{"t":"次顾与成闻与新报","f":"五言律诗","c":["安得从容语，春风转杀机。","寻常忘地分，只尺冒天威。","抗志通排闼，惊魂逐褫衣。","他年看碣石，沧海一云矶。"]},{"t":"雨","f":"五言律诗","c":["雨坐才三日，晴游已一冬。","壮怀淹阁茗，润色对庭松。","泥阻东山屐，云沉北寺钟。","何当拥衾起，微旭在帘栊。"]},{"t":"山中听泉","f":"五言律诗","c":["秋日山亭上，观泉坐夕曛。","先声虚谷应，馀沥小池分。","滴滴初疑露，源源半接云。","载歌云谷句，樵子隔溪闻。"]},{"t":"存问后奉陪郡守王公小燕泉亭","f":"五言律诗","c":["落叶声到耳，流泉歌吹馀。","日斜群客醉，山静一堂虚。","能听今逢子，无言夙起予。","庐陵方在坐，何处问环滁。"]},{"t":"次韵王郡公除夕 其一","f":"五言律诗","c":["郡阁还除夕，青灯酒独斟。","时情新旧历，物色短长吟。","草野欣风动，蓂阶爱雪侵。","梅花如索笑，诗思若为禁。"]},{"t":"次韵王郡公除夕 其二","f":"五言律诗","c":["屡得徵黄报，还怜借寇身。","清声无汉吏，惠思有周人。","漏转公庭午，香凝燕寝春。","召棠歌满路，赤子孰非亲。"]},{"t":"清狂赠郭仁弘","f":"五言律诗","c":["万古清谁圣，吾希敢讳狂。","甘心从饭颗，散发和沧浪。","避世讥门磬，闻仙问海航。","尚馀诗画在，珍赏动遐方。"]},{"t":"秋镜堂","f":"五言律诗","c":["湖水明如镜，秋来虚映空。","尘消凉雨后，天在古堂中。","巫峡帘犹远，澄江练自工。","载歌收潦句，为问主人翁。"]},{"t":"吴封君送茶笋","f":"五言律诗","c":["人忆荆溪上，茶来谷雨前。","两封专走仆，七盌或通仙。","露箨兼将笋，风漪已试泉。","东坡诗句在，歌罢一泠然。"]},{"t":"属邵翁种蒲于石","f":"五言律诗","c":["片石能还水，移来楚水滨。","仙家九节草，吾室数茎春。","苍溢空江露，青消老眼尘。","凭谁了兹事，西郭有閒人。"]},{"t":"移竹","f":"五言律诗","c":["醉日堪移竹，南枝记得真。","寸金还有土，片玉已无尘。","挺挺数君子，岩岩一丈人。","明年春雨后，请看箨龙鳞。"]},{"t":"孟训堂","f":"五言律诗","c":["三迁胎教后，孟母古无前。","一念机能转，千秋语尚传。","慈亲真达者，才子本超然。","礼乐吾方短，东邻愧尔贤。"]},{"t":"西郭雨行","f":"五言律诗","c":["冒雨行西郭，遥闻山下泉。","林回俄鹭起，草际即云边。","入寺应疑客，逢农且贺年。","登台望东渚，个个泊渔船。"]},{"t":"次答马巡按留别","f":"五言律诗","c":["达也非吾事，高楼鸟欲窠。","湖光迎月起，壁影送云过。","秋老径边竹，春深洞口萝。","勘书多暇日，时和野人歌。"]},{"t":"山南道中","f":"五言律诗","c":["惯行山北路，今日偶山南。","丹井他年汲，羽人何处参。","野田栖晚谷，溪树落寒潭。","近午天风起，重湖破宿岚。"]},{"t":"送过司训赴天台","f":"五言律诗","c":["浙左皆名郡，惟台更古风。","群经芸阁上，多士杏坛中。","禄在休嗟老，文成且送穷。","深山饶大木，阴庇海天东。"]},{"t":"赠牛总戎","f":"五言律诗","c":["旧镇新荒路，新衔督府官。","九重亲授节，万里独登坛。","远计胸中定，先声檄外欢。","请看传令日，风采动旗竿。"]},{"t":"谢王郡公惠响器留别","f":"五言律诗","c":["君谢江湖器，山林安用之。","鱼龙迎旧节，虎豹避清时。","劄至起三肃，衔成试一吹。","平生知我意，惟有此泉知。"]},{"t":"寿薛同庵七十","f":"五言律诗","c":["草堂风雨昼，嘉客且醇醪。","老去心犹壮，狂来兴转高。","酒杯宽处放，诗客醉时豪。","昨夜悬明镜，青青照鬓毛。"]},{"t":"春日新晴","f":"五言律诗","c":["湿烟飞不起，春雨夜来深。","草色才如染，花枝半未禁。","过门无俗客，击壤有新吟。","独坐东亭下，熙然太古心。"]},{"t":"寄题理梦斋","f":"五言律诗","c":["理梦复理梦，梦如江水长。","达生迷化蝶，玩世托炊粱。","忽起汤齑口，仍留冰炭肠。","醉醒都两字，毕竟不如忘。"]},{"t":"哭虚庵陈郡侯 其一","f":"五言律诗","c":["不见古循吏，见公良慰心。","野阴多种树，门静绝怀金。","客醉曹参酒，童便阅道琴。","道南营建处，深谢势家侵。"]},{"t":"哭虚庵陈郡侯 其二","f":"五言律诗","c":["半溪辞我去，极口谓公贤。","素履元随地，幽居不愧天。","留台分道日，赐告养痾年。","一见醇醪醉，先声不浪传。"]},{"t":"施雪谷七十","f":"五言律诗","c":["我少君三岁，看君冠且昏。","漫从今老数，已入古稀论。","诗价随时长，医名与齿尊。","有官无吏事，真乐荷殊恩。"]},{"t":"谢管令尹请春酒","f":"五言律诗","c":["春酒勤相召，其如病足何。","坐惭推我先，揖恐答宾多。","懒性容清世，狂吟和雅歌。","县堂廉陛远，十载不曾过。"]},{"t":"月夜怀素翁","f":"五言律诗","c":["南海沧波远，东山宿雾深。","清秋连夜月，吾道百年心。","勿药闻新报，无弦对古琴。","相思不相见，青壁一千寻。"]},{"t":"病足初愈","f":"五言律诗","c":["■足欣初愈，行嫌柱杖多。","吾诗惟望雨，客论漫悬河。","山墅棋边屐，江城矢复戈。","园亭饶竹树，风晚兴如何。"]},{"t":"山中偶成 其一","f":"五言律诗","c":["古寺名泉畔，钟鸣客到初。","溪山春日昼，花柳老人舆。","远眺招无鹤，閒居食有鱼。","卧云呼不起，苔隐石床书。"]},{"t":"山中偶成 其二","f":"五言律诗","c":["无期还隔夜，春事共游初。","径仄花薰盖，坡平草藉舆。","山僧劳供茗，野客许提鱼。","新句推敲处，摩挲石上书。"]},{"t":"树儿埋之明日视冢还有感","f":"五言律诗","c":["老年悲不得，恸哭付长歌。","也自吾庭在，其如嘉树何。","山林游兴少，风雨梦魂多。","最是伤心处，新邱在涧阿。"]},{"t":"晓起用前韵","f":"五言律诗","c":["苦调无饶语，长歌复短歌。","寒知春每尔，雨问夜如何。","僻巷门常静，新晴客渐多。","感时惊物色，青草长东阿。"]},{"t":"华从龙往祇陀读书诗以问之","f":"五言律诗","c":["别我诗仍物，先天第一花。","新春乘野艇，斜日到僧家。","雨化曾无力，风光渐有涯。","相过知不远，石鼎试新茶。"]},{"t":"送钱以正再赴太医院","f":"五言律诗","c":["有术能医国，无阶可致身。","孤槎沽海月，瘦马洛京尘。","心苦书檠夜，情欣药笼春。","千秋夔契外，岐伯是何人。"]},{"t":"送莫典史","f":"五言律诗","c":["堂上亲双老，天涯客早归。","他年毛义檄，此日老莱衣。","晴岭穿云易，风滩上水稀。","曾闻巡按语，未艾独知几。"]},{"t":"超然堂送丽水酒后漫述","f":"五言律诗","c":["登台兼赏雨，且送远行人。","此日尊前醉，殊方别后春。","红云天北极，青野海西滨。","高处君明眼，临分懒重陈。"]},{"t":"闻茹令人卒追忆水亭子","f":"五言律诗","c":["水亭能共老，也属古稀年。","此日歌无地，他时哭有天。","言犹如白日，见已及黄泉。","手植西冈树，霜清月正圆。"]},{"t":"晓起","f":"五言律诗","c":["拭眼将观雪，翻成听雨吟。","暑寒元有，天地亦何心。","岭洒松间细，邱沾麦处深。","几时还集霰，三白抵千金。"]},{"t":"送冯少府","f":"五言律诗","c":["震泽连三郡，官程百里船。","哦松多隙地，监水有馀天。","惠博春忻作，征宽夜稳眠。","民风堪采处，时致乃翁前。"]},{"t":"送莫江陵","f":"五言律诗","c":["古来雄胜地，今送令君游。","星宿连中极，江山据上游。","政从平处善，学向静中优。","春雨桑麻绿，时登郭外楼。"]},{"t":"送吴经历从韶","f":"五言律诗","c":["武卫参文吏，西川控贵阳。","塞平宵檄少，幕静昼吟长。","江汉才难尽，风云志未忘。","量移还有地，宣力答君王。"]},{"t":"送陆海盐以昭","f":"五言律诗","c":["佐令盐官去，严程向海边。","千家成邑地，一命济人年。","晚听弦歌市，春行斥卤田。","南康弓冶在，异政有超迁。"]},{"t":"葺跨塘桥成","f":"五言律诗","c":["桥誇东西岸，道当南北冲。","若非今日补，几废昔人功。","风送难驱石，天全欲断虹。","从兹舟骑客，相顾笑谈中。"]},{"t":"独坐","f":"五言律诗","c":["独坐复独坐，清斋起自朝。","嚣从閒处却，饱向静中消。","客径遥通市，邻家近隔桥。","西林闻络纬，幽兴晚来饶。"]},{"t":"避客山堂卧起","f":"五言律诗","c":["卧起闻清磬，悠然与境忘。","秋高山寺静，夕霁海天长。","避客还逢客，馀觞更洗觞。","老僧知我意，隔水和沧浪。"]},{"t":"咏梅花菊","f":"五言律诗","c":["有菊蒙梅姓，寒香亦近之。","渊明方待酒，和靖已成诗。","雪未滋清骨，霜还剩碧枝。","世间多品汇，岁晚汝偏奇。"]},{"t":"送李司训宗文之建昌","f":"五言律诗","c":["山水旴江郡，诸生喜得师。","吾游曾此地，君去不同时。","仙观真卿笔，乡仓晦父碑。","相寻还有暇，为我吊磁龟。"]},{"t":"金莲池上偶成","f":"五言律诗","c":["藉草仍移坐，临池看水流。","松阴知日午，萍色报霜秋。","渠曲僧廊转，波澄佛殿浮。","上方时供茗，与客共淹留。"]},{"t":"风雨之夕子春将别写怀","f":"五言律诗","c":["别思逢风雨，无堂漫置觞。","客嫌冬日短，主恨越天长。","老砚三传世，寒灯十起阳。","西兴回首地，吴树正苍茫。"]},{"t":"冬日偶过听松南院","f":"五言律诗","c":["丈室东移去，南房自一家。","树留不尽叶，菊有欲残花。","日昃壶添酒，烟消灶熟茶。","閒行甘淡味，休向俗人誇。"]},{"t":"归途再用前韵","f":"五言律诗","c":["谈馀方外士，乘兴到禅家。","云尽长依竹，山寒不见花。","客留新卷墨，僧试旧垆茶。","世味吾痴在，无官处处誇。"]},{"t":"送王蒙","f":"五言律诗","c":["夜深犹诵读，扶我出风烟。","水陆仍千里，门墙未一年。","课程虽应举，科级本希贤。","明岁春风里，还来饮此泉。"]},{"t":"敬止为姚江汤梦卜赋","f":"五言律诗","c":["信国河山誓，濠梁水木心。","东来三世近，北望两江深。","继别还成谱，承休欲嗣音。","诗人桑梓意，时托短长吟。"]},{"t":"与丰城夏宗选叙别","f":"五言律诗","c":["别子剑江上，相逢二十秋。","盐车终厄骥，渔艇不惊鸥。","招隐歌空谷，酬知赋远游。","我无徐孺榻，山馆缺淹留。"]},{"t":"寿陆野云","f":"五言律诗","c":["八十称大耋，年来又此翁。","相人能法眼，谓我有仙风。","世事清谈里，家声远谱中。","笑看兰桂长，黄发碧双瞳。"]},{"t":"次杜地官游惠山","f":"五言律诗","c":["閒登山阁上，纵目九峰巅。","有兴还题石，多情更饮泉。","云栖追旧梦，风景入新联。","异地应同调，吾曾守颍川。"]},{"t":"从龙之祗陀林读书欲往送之不果用韵致意","f":"五言律诗","c":["云林曾榻处，数里到君家。","松结千年顶，梅留二月花。","情知资浩博，力欲谢浮誇。","忽起怀人思，悠然天一涯。"]},{"t":"追次西涯先生寄题叠嶂楼","f":"五言古诗","c":["涯老题诗在，居然见此楼。","书邮何日到，碑刻几人留。","树色分淮甸，江声接楚流。","吾登方恨晚，谁赋不悲秋。","六代孤鸿没，三山片石浮。","村墟多佛塔，野水有渔舟。","吴越连诸郡，荆扬跨两州。","岁年齐始建，风景白曾游。","谢眺亭偏古，严陵石最幽。","傥非公一语，千载若为酬。"]},{"t":"题画寿周秉道","f":"五言古诗","c":["郁郁顾山树，青连东海天。","几家能卜世，此老夙称贤。","大隐非居市，长生不问仙。","骑迎侯子左，鞭让祖生先。","兰已充佳佩，芹将荐御筵。","舟横江北渚，剑倚斗南躔。","传业书签万，生涯食指千。","初心三岛日，晚兴五湖烟。","榻下欣留客，旌招耻赴田。","少微知此野，大耋值今年。","独鹤吟筇畔，群鸥钓石边。","慕亲题感怙，怀世赋思玄。","人士缁冠雅，儿郎綵服鲜。","夜深销短烛，冬煖谢轻绵。","永日方嘉燕，清风复大篇。","贤甥献春酒，侑以惠山泉。"]},{"t":"萤","f":"五言绝句","c":["过楼还绕井，入户更深深。","老可观书卷，惟应照我心。"]},{"t":"蛩","f":"五言绝句","c":["隐隐复悠悠，虫鸣早应秋。","夜凉人未寝，草露湿阶头。"]},{"t":"菜 其一","f":"五言绝句","c":["菜以甜为姓，应须老圃知。","苦心谁氏子，更道馑如饴。"]},{"t":"菜 其二","f":"五言绝句","c":["此根真可咬，不用问康侯。","鼎鼐非君事，徒能白相头。"]},{"t":"紫薇花","f":"五言绝句","c":["簇簇繁缨色，谁教媚早秋。","省臣今白首，还忆浙中楼。"]},{"t":"络纬","f":"五言绝句","c":["络纬复络纬，一虫还一虫。","年年声不断，未了禦寒功。"]},{"t":"兰","f":"五言绝句","c":["天风一夜霜，萧然见秋野。","兰蕙化为茅，亦有不化者。"]},{"t":"菊","f":"五言绝句","c":["秋菊有黄花，万古长如此。","谁知栗里风，却胜南阳水。"]},{"t":"雪兔","f":"五言绝句","c":["山川雪模糊，明视明如月。","高秋夜气清，犹怀广寒阙。"]},{"t":"洗石 其一","f":"楚辞体","c":["汲水洗石床，上有唐时字。","不用太兮明，恐损莓苔翠。"]},{"t":"洗石 其二","f":"五言绝句","c":["石上听松声，松化石不老。","移石就新松，新松数人抱。"]},{"t":"春日访知微门焉未应诗以嘲之","f":"五言绝句","c":["剥啄应松声，客去僧未起。","僧病一春过，老却山中杞。"]},{"t":"小雨过海天亭前饮酒","f":"五言绝句","c":["山风吹雨霁，藉草对邻僧。","回首淹留地，白云知几层。"]},{"t":"偶过听松听竹间泉","f":"五言绝句","c":["削壁皴斧痕，下有洞如屋。","积铁不知年，时许莓苔绿。"]},{"t":"寄司徒孙九峰 其一","f":"五言绝句","c":["江汉云重阻，秋风白发多。","相思不相见，木落洞庭波。"]},{"t":"寄司徒孙九峰 其二","f":"五言绝句","c":["老节曾相倚，虚心几岁寒。","九龙山下梦，夜夜楚江干。"]},{"t":"王山长归越灯前酌别 其一","f":"五言绝句","c":["陈榻事巳陈，不用再三渎。","君去闭山斋，岁寒两竿竹。"]},{"t":"王山长归越灯前酌别 其二","f":"五言绝句","c":["君如蜀山人，我愧程叔子。","往来皆可书，山中无野史。"]},{"t":"王山长归越灯前酌别 其三","f":"五言绝句","c":["点点易未了，山中年复年。","期君弄春水，早渡越江船。"]},{"t":"王山长归越灯前酌别 其四","f":"五言绝句","c":["鹿洞本无洞，鹅湖亦无湖。","勿谓吾台小，中涵太极图。"]},{"t":"题画 其一","f":"五言绝句","c":["溪上有梅花，岁寒心不老。","不见履斋翁，山中几春草。"]},{"t":"题画 其二","f":"五言绝句","c":["微月生西岭，清光日渐多。","直从圆处满，试问夜如何。"]},{"t":"邻竹","f":"五言绝句","c":["万玉栽非易，千金买更难。","题诗问东老，须向岁寒看。"]},{"t":"待月 其一","f":"五言绝句","c":["夜夜待月明，每被浮云苦。","今夜天无云，月明本如古。"]},{"t":"待月 其二","f":"五言绝句","c":["月从东海来，待月吟正苦。","素娥本无心，不管人今古。"]},{"t":"雪林","f":"五言绝句","c":["冬老繁华尽，山深雪满林。","潇然茅屋下，千古岁寒心。"]},{"t":"警斋","f":"五言绝句","c":["林居事幽讨，长诵敬斋箴。","客至论今古，时兴策励心。"]},{"t":"书石泉画","f":"五言绝句","c":["石泉作溪山，信意复信手。","知音者后溪，兴在梁溪口。"]},{"t":"月下推篷看梅卷","f":"五言绝句","c":["梅花本幽贞，月下更奇绝。","推篷何处舟，孤山夜来雪。"]},{"t":"观泉有感","f":"五言绝句","c":["阳城居晋鄙，薰德几千人。","我亦山林久，观泉愧我巾。"]},{"t":"蒙斋 其一","f":"五言绝句","c":["涓涓山下水，日夜游从东。","策杖临流者，曾闻说圣功。"]},{"t":"蒙斋 其二","f":"五言绝句","c":["有美道乡孙，学道如学海。","海水即吾泉，山下真源在。"]},{"t":"冉泾书院十二咏 其一 曾侍亭","f":"五言绝句","c":["归养荷天恩，孔训闻自少。","不敏请事斯，如闻提耳诏。"]},{"t":"冉泾书院十二咏 其二 容春阁","f":"五言绝句","c":["一堂容万卷，长忆鹤翁诗。","高阁日增崇，老至不自知。"]},{"t":"冉泾书院十二咏 其三 燕居亭","f":"五言绝句","c":["客退解冠裳，坐我北轩下。","我铭揭西楹，时时一瞻顾。"]},{"t":"冉泾书院十二咏 其四 存一斋","f":"五言绝句","c":["先民递传恭，惟一益亲切。","斋居诵新铭，敬对不敢亵。"]},{"t":"冉泾书院十二咏 其五 嘉树亭","f":"五言绝句","c":["吾庭有嘉树，种自容春翁。","百年益封殖，人歌召南风。"]},{"t":"冉泾书院十二咏 其六 八角台","f":"五言绝句","c":["斋前垒石台，台有八卦象。","山中点易时，如坐兹台上。"]},{"t":"冉泾书院十二咏 其七 兰畹在","f":"五言绝句","c":["滋兰自骚人，香草以比德。","九畹如井田，惟馨亦充塞。"]},{"t":"冉泾书院十二咏 其八 思濂沼","f":"五言绝句","c":["莲有君子德，爱多知者鲜。","净植起香风，污泥任浅深。"]},{"t":"冉泾书院十二咏 其九 光霁桥","f":"五言绝句","c":["观莲忆濂翁，因得风月趣。","忽然光霁生，乃在过桥处。"]},{"t":"冉泾书院十二咏 其十 静深径","f":"五言绝句","c":["新竹依旧径，竹长径益深。","青春白昼永，爱尔君子心。"]},{"t":"冉泾书院十二咏 其十一 圭冕二石","f":"五言绝句","c":["石出东野山，其形各有似。","如冕复如圭，堂名称曾侍。"]},{"t":"冉泾书院十二咏 其十二 雪浪石菖蒲","f":"五言绝句","c":["坡翁爱兹石，铭在莲花盆。","吾以种菖蒲，珍重如前闻。"]},{"t":"慧山书院十五咏 其一 忠定祠","f":"五言绝句","c":["梁溪深十寻，湛岘高万武。","我作李公祠，春秋荐牲酤。"]},{"t":"慧山书院十五咏 其二 湍涧","f":"五言绝句","c":["七池流且汇，一水犹在山。","萦回忽成文，至此将下田。"]},{"t":"慧山书院十五咏 其三 野桥","f":"五言绝句","c":["乱石冲径来，徒杠接石砌。","拔断谢游人，水浅人犹揭。"]},{"t":"慧山书院十五咏 其四 云阶","f":"五言绝句","c":["石磴穿云上，悬崖自此升。","谁言风可御，须信气堪乘。"]},{"t":"慧山书院十五咏 其五 静清深处","f":"五言绝句","c":["何处静而清，蒙泉出山下。","观物本无心，一原穷万化。"]},{"t":"慧山书院十五咏 其六 海天亭","f":"五言绝句","c":["兀坐山亭下，悠然海上天。","归墟无尽藏，须记始流年。"]},{"t":"慧山书院十五咏 其七 超然堂","f":"五言绝句","c":["梦中得嘉名，卅载乃斯宇。","珍重病馀身，优游荷天予。"]},{"t":"慧山书院十五咏 其八 吟松个","f":"五言绝句","c":["风来松有声，洒洒当左个。","我吟本无心，松亦何心和。"]},{"t":"慧山书院十五咏 其九 咏竹个","f":"五言绝句","c":["新栽竹数竿，竿竿挺苍玉。","我歌竹和之，步转阑干曲。"]},{"t":"慧山书院十五咏 其十 泉斋","f":"五言绝句","c":["出山如在山，名斋敢忘本。","鉴里看青天，不为泥沙混。"]},{"t":"慧山书院十五咏 其十一 点易台","f":"五言绝句","c":["有象本通玄，义不在句读。","道人坐高台，忘言对苍岫。"]},{"t":"慧山书院十五咏 其十二 滴露泉","f":"五言绝句","c":["滴滴出石间，初疑松上露。","点易日有程，还应周天度。"]},{"t":"慧山书院十五咏 其十三 两知亭","f":"五言绝句","c":["天涯一归客，海内两知音。","万古泉声在，应知此老心。"]},{"t":"慧山书院十五咏 其十四 瘗卷邱","f":"五言绝句","c":["吾道方施行，怀之不胜卷。","故物穴名山，虹光起遐眷。"]},{"t":"慧山书院十五咏 其十五 望阙岩","f":"五言绝句","c":["东南海一隅，天阙勤望眼。","登拜想氤氲，殿上香炉篆。"]},{"t":"除夕勋侄送红酒","f":"五言绝句","c":["红酒桃花色，东风吹更鲜。","将情来旧宅，送喜入新年。"]},{"t":"遣暑四事 其一","f":"五言绝句","c":["清泉白石子，置之古铜簋。","泉出此山中，石来汉江水。"]},{"t":"遣暑四事 其二","f":"五言绝句","c":["两峰泻寒泉，石庵得意笔。","悬之堂西偏，白日风萧瑟。"]},{"t":"遣暑四事 其三","f":"五言绝句","c":["净扫席间地，周旋仅函丈。","矮几置中央，坐爱垆烟上。"]},{"t":"遣暑四事 其四","f":"五言绝句","c":["楛槎种菖蒲，盆水半欲没。","露珠上叶稍，爱尔仙灵物。"]},{"t":"雨坐","f":"七言律诗","c":["初春烟雨似梅天，墙角梅花尚索然。","病客有情常梦野，閒人无事漫占年。","永萦浅碧连城外，草送轻青到槛前。","闻道忧民新令尹，几回骑马劝耕田。"]},{"t":"忽忆江西湖南时风景用前韵","f":"七言律诗","c":["漫道吴天似楚天，四时风雨一萧然。","滕王阁下维舟地，黄鹤楼中听笛年。","春色渐回梅放后，秋声应尽雁归前。","东山屐在堪乘兴，閒送清泉下石田。"]},{"t":"雨中寄浦文玉用前韵","f":"七言律诗","c":["风雨无端莫问天，新编读罢自欣然。","寸心敢谓能千古，一话真应胜十年。","江郭鸠声春笠外，山窗梅影暮灯前。","明朝独上鹅湖棹，回首蘼芜满野田。"]},{"t":"春日无绪泉亭书院俱缺一至次浦文玉山行用杜韵","f":"七言律诗","c":["仲春风日尚微寒，两月多愁懒戴冠。","雨后花催连夜赏，雪中山忆隔年看。","云开平野还盘谷，石转清流更激湍。","物色有馀情绪少，几时慈壸报平安。"]},{"t":"春水寿王郡侯","f":"七言律诗","c":["怀李楼前春水深，郡公多暇重登临。","长江对我一杯酒，白日在天千古心。","笔无留翰汉老吏，诗有馀才唐正音。","年来初度未须祝，手植甘棠新作阴。"]},{"t":"送顾行人与新","f":"七言律诗","c":["奉使真随八月槎，南风五月又辞家。","松花露溢离亭酒，石子泉将客路茶。","北极朝廷瞻象魏，中原藩省赋皇华。","明年再揽澄清辔，独听民谣到海涯。"]},{"t":"久雨","f":"七言律诗","c":["熟尽黄梅雨不休，出门何处觅沧洲。","势倾底柱河全泻，气塞归墟海逆流。","圃史空传葵有日，田家长叹麦无秋。","渺然舟楫吾安往，古华山前一倚楼。"]},{"t":"秋夜","f":"七言律诗","c":["月流云窦影庭柯，今夜风于昨夜多。","我病未堪空酒在，秋声如此奈愁何。","人言每信天无漏，世事真看地有波。","三叹朱弦谁听者，几回击节杜陵歌。"]},{"t":"野色","f":"七言律诗","c":["黄泥桥西溪岸斜，东风吹水拥溪沙。","杜陵药饵长随我，韩子诗书正满家。","何处不看悬磬室，有人还着替舟槎。","涣然亭外当时路，只隔南涯与北涯。"]},{"t":"秋夜宿惠山精舍","f":"七言律诗","c":["惠山草堂秋夜清，道人夜坐听泉声。","中庭不见古松影，西岭却遮新月明。","一里松庵期信宿，十年鹿洞梦孤征。","明朝藜杖须将去，从我閒行三两生。"]},{"t":"得如山和章再用前韵","f":"七言律诗","c":["落日空山钟磬清，隔溪时听棹歌声。","小桥再渡觉身健，高阁一登增眼明。","望极江湖云北去，梦回岁月雁南征。","黄花亦是秋风客，尽办寒香对老生。"]},{"t":"九日过国臣弟南庄","f":"古风","c":["凤皇墩下扣柴关，篱落黄花手自攀。","适野亦堪酬令节，避高应不到名山。","情多更欲临流坐，兴尽真?载月还。","最喜晚来风色定，小桥回首碧湾湾。"]},{"t":"寄顾台州华玉","f":"七言律诗","c":["秋晚怀人思欲荒，东南江水隔钱塘。","山高故近台三象，郡僻真悬海一方。","他日曾看周砥柱，何时能剪召甘棠。","观风定有新诗句，愿托王生为寄将。"]},{"t":"新春","f":"七言律诗","c":["庭草犹枯渐有情，檐声如雨雪初晴。","缘江积冻朝寻径，匝市浮烟午出城。","风信巳非前九烈，月华应为上元明。","梅花两树香如许，误道诗人在冉泾。"]},{"t":"得章司成枫山先生书","f":"七言律诗","c":["司成书自道卿传，千里枫山越四年。","风雨梦从初起处，江湖心在未归前。","数盘谷可容君筑，万里门曾泊我船。","闻说临风多感慨，乾坤回首一茫然。"]},{"t":"戊寅八月以容春集托乔司马寄王中丞虎谷越岁司马以集还因得中丞之讣","f":"七言律诗","c":["隔岁书回不拆封，惊闻虎谷失髯翁。","风骚辽阔遗音在，江汉萧条老眼空。","壮志欲从汾左右，清声曾动陜西东。","七年又洒柴墟泪，屈指交游俯仰中。"]},{"t":"守溪公惠洞庭新茶侑以长句奉谢","f":"七言律诗","c":["洞庭春茗过湖来，阁老新诗手自裁。","锡谷泉应将撱石，玉川风欲问蓬莱。","竹垆纵有僧堪借，梧几曾无客与陪。","何日山中寻旧约，莫釐高处一登台。"]},{"t":"悼沈提学休翁","f":"七言律诗","c":["江东回首复湖南，到处春风许我参。","万里无槎心独往，千钧有笔力能堪。","凤皇台远空魂梦，黄鹤楼高绝笑谈。","最忆牵衣相别地，碧瞳如水鬓䰐鬖。"]},{"t":"松坛午坐与送茶诸僧","f":"七言律诗","c":["竹里风来生昼凉，况逢时节近端阳。","也知城外尘能少，却道山中日更长。","云壑飞泉频倚杖，松坛磐石漫焚香。","老僧供茗浑忘味，好向嵩峰问溥光。"]},{"t":"答姜士元用舒国裳韵","f":"七言律诗","c":["归舟不见急流难，曾向严滩濯我冠。","何处世情非滟滪，几时尘梦不漪澜。","山中松子秋还落，海上桃根晚更蟠。","遥想栖贤云雾里，定依北斗望长安。"]},{"t":"用杜韵寄李剑州","f":"七言律诗","c":["病馀岑寂向林邱，消息欣传李剑州。","蜀道巳通今四海，禹疆还识古诸侯。","孤城力起千家市，短劄情随万里舟。","我亦旧游忘未得，梦魂长绕紫薇楼。"]},{"t":"答陈宪使文鸣过访不遇","f":"七言律诗","c":["黄梅雨过绿秧齐，日向山庄路不迷。","万里仙槎还海上，十年清梦几湖西。","太行碑刻看新打，岳麓书签忆旧题。","谢客也知非此客，却教泉酿负蒸藜。"]},{"t":"文鸣报书久不至","f":"七言律诗","c":["江船连夜发蓉湖，三宿封书报尚无。","夏榻梦魂便客少，晚舆游兴对僧孤。","惊风骤雨常怀楚，丽水佳山又过吴。","欲向诗囊问奇句，瓜州回首渺烟芜。"]},{"t":"和乔司马三首 其一 梅花水","f":"七言律诗","c":["梅花不见见清痕，何处还堪索笑言。","云影逗风俱澹荡，波声流月自潺湲。","湖山韵绝弦长断，洛浦香销佩独存。","春到江南无限树，不须临水赋招魂。"]},{"t":"和乔司马三首 其二 观音山","f":"七言律诗","c":["观音阁下江水深，阁上丹崖知几寻。","安能羽翼一飞上，独凭阑干时放吟。","鸟去却留云栈影，潮来还起石钟音。","十年老眼今如梦，遥为岩翁重此临。"]},{"t":"和乔司马三首 其三 鸡鸣山","f":"七言律诗","c":["钟山西引一峰高，云磴盘纡步不劳。","画里楼台复钟鼓，望中城市有林皋。","江流入海初奔放，世路怀人更郁陶。","却倚崔嵬发长啸，松风何处起秋涛。"]},{"t":"夏吏部于中以谏除名访予里第予避暑山中闻而赋此","f":"七言律诗","c":["南归吏部一方巾，冉水东头访病人。","万里孤槎浮海梦，片言九死报君身。","风从远道来应好，暑向深山避却真。","从此著书应满室，草堂深闭楚江春。"]},{"t":"舒翰林国裳过锡病不能来其人来言之","f":"七言律诗","c":["病客舟中不著巾，山中而我亦怀人。","平生温饱元非志，万死艰危尚有身。","风力南溟看独近，潮声东海听初真。","也知梦转沧江晚，正想胪传玉殿春。"]},{"t":"万汝信与国裳同舟用韵再寄","f":"七言律诗","c":["一封书上几沾巾，道路争传国有人。","云雾政勤瞻斗念，风波还重渡江身。","吴门晚树舟边近，楚泽秋兰佩后真。","却忆匡庐弦诵地，五峰回首不胜春。"]},{"t":"晚凉","f":"七言律诗","c":["晚凉幽兴为谁多，闻道灵旗巳渡河。","露咽微吟还蟋蟀，雨添新韵到蕖荷。","窗前梦醒风初定，枕上诗成月己过。","从此炎蒸应尽退，不须频问夜如何。"]},{"t":"寄莫如山","f":"七言律诗","c":["五更梦醒忆南沙，只尺天分路两涯。","诗草往来凭稚子，春光深浅问梅花。","节临雨水初飞雪，路阻山泉未试茶。","画里西湖皆幻景，似闻高兴在东家。"]},{"t":"得如山和章兼荷踏雪见过用前韵","f":"七言律诗","c":["雪后相过屐印沙，美人望不在天涯。","九峰西照双溪水，万树东风一夜花。","天台客去方燖橘，阳羡书来未寄茶。","留得山翁曾共醉，数杯今雨对诗家。"]},{"t":"寄张汝立","f":"七言律诗","c":["别来风雨梦初醒，两对山中春草庭。","江汉无情衰可墨，春秋有法简能青。","笔将点易劳君送，琴欲赓歌起我听。","闻道儒台虚席在，何时尊酒海天亭。"]},{"t":"送施克和之平乐","f":"七言律诗","c":["行尽潇湘问吏邮，青山回处古昭州。","自知宦寓应如水，谁道刑官便是秋。","身在江湖频望阙，道经岳鄂两登楼。","三年宪召君当起，莫指苍梧赋远游。"]},{"t":"送钱昌言赴顺宁经府","f":"七言律诗","c":["万里滇南郡幕行，先从水道问邮程。","乾坤何往非臣所，朝夕难违是子情。","晚日每看山外影，寒江犹听雾中声。","独怜泰伯祠前别，数点梅花照眼明。"]},{"t":"喜冬官钱士弘访予惠山草堂","f":"七言律诗","c":["公来犹记十年前，我在山中正浚泉。","陆羽水经应入妙，卢仝茶力漫通仙。","閒边梦亦寻常见，病后诗曾一再传。","他日风雩还有约，沧浪歌罢采金莲。"]},{"t":"杭方伯世卿登我龙山不克奉陪","f":"七言律诗","c":["百里荆溪十载违，相逢谁道旧情非。","病如梦里予初寤，画在诗中子亦归。","两地青山歌响应，一星南极望依微。","凭君再订登高约，听罢沧浪共振衣。"]},{"t":"九月一日","f":"七言律诗","c":["九月一日初度辰，谢客来访山中人。","坐临旧石谈还旧，茗试新泉味更新。","点易笔如周入梦，读书台与李为邻。","高邱远海诗家兴，我亦东驰万里神。"]},{"t":"寿少傅邃翁先生七十","f":"七言律诗","c":["百年师执邃庵翁，几向门墙拜下风。","多士钧陶鸣铎外，累朝经济挂冠中。","时将老矣江山在，兴本超然出处同。","莫道隐园真可隐，庙堂端合坐姬公。"]},{"t":"送施渐之平乐省亲","f":"七言律诗","c":["潇湘洞庭涵太空，诗人行色在胸中。","石钟舟畔三江月，铁笛楼前五夜风。","衡岳雁回程可计，苍梧云尽望无穷。","凭将一勺龙泉水，远向昭州寿乃翁。"]},{"t":"昼坐偶成","f":"七言律诗","c":["两月悭诗到社中，日长应负绿阴风。","病多自笑药无力，步少不知筇有功。","五里汲泉将石子，一春戒酒谢山翁。","故人送笔能留在，点易台高对晚峰。"]},{"t":"点易台八首答张侍御汝立 其一","f":"七言律诗","c":["象笔双缄自吉州，书题点易远相投。","老来已悟浮生梦，病后兼忘应世筹。","磴入烟霞须策杖，台穷云海胜登楼。","凭谁净扫焚香石，千仞冈头拜孔周。"]},{"t":"点易台八首答张侍御汝立 其二","f":"七言律诗","c":["海天亭畔卜幽居，三古精神一卷书。","象管搦残朱未落，松梢滴尽露还馀。","姓同康节希何敢，年过蘧瑗化不如。","月出东山时起我，独凭高处问盈虚。"]},{"t":"点易台八首答张侍御汝立 其三","f":"七言律诗","c":["桐树扶疏荫石台，巉岩西望更崔嵬。","日流云影前峰去，风送泉声别涧来。","鸿渐茗从閒客试，李绅书自少年开。","晚凉每有风雩兴，随意邻僧坐碧苔。"]},{"t":"点易台八首答张侍御汝立 其四","f":"七言律诗","c":["高台百尺临苍茫，白云渺渺溪泱泱。","松垂一枝去地近，草碧千里兼天长。","有时岩顶起清籁，何物涧边生异香。","操铅点易者谁子，老矣羲文心未忘。"]},{"t":"点易台八首答张侍御汝立 其五","f":"七言律诗","c":["万壑风云万壑涛，人间天上在岩嶅。","丘园掩映松楸密，台殿参差鹳鹤高。","僻地自堪成晚节，浮名真合付秋毫。","野翁错指丹崖是，应怪频来杖屦劳。"]},{"t":"点易台八首答张侍御汝立 其六","f":"七言律诗","c":["百年佳兴独登台，草结为堂白日开。","云暝气连东海石，风睛光动北山莱。","故应壁立千寻在，安得泉分一道来。","老衲似知天假我，手移松树夹庭栽。"]},{"t":"点易台八首答张侍御汝立 其七","f":"七言律诗","c":["金莲池水即沧浪，白石冈云接草堂。","竹合凤箫难起调，树留虫篆不成行。","百原泉上风神远，五老峰前梦寐长。","万卷相看才数画，漫劳书客问芸香。"]},{"t":"点易台八首答张侍御汝立 其八","f":"七言律诗","c":["观水长怀子在川，衣冠时向古坛前。","蓍从上蔡无真种，图到希夷有别传。","客送屐声云里径，僧将瓢影月中泉。","閒来准拟忘言久，莫问新诗月几篇。"]},{"t":"次韵答鹅湖费公","f":"七言律诗","c":["清时谁敢爱深山，风雨应惭厦万间。","东国尽容原宪病，西京犹放涑翁閒。","诗传秘阁歌盈耳，药进慈闱笑强颜。","乌鸟情真天鉴在，一封已达九重关。"]},{"t":"代柬寄刘司徒","f":"七言律诗","c":["平生青眼老司徒，两地暄凉一字无。","经济有才空岁月，登临何处不江湖。","百年第宅长安市，千古衣冠洛社图。","久矣吾衰还病母，旧游回首渺云芜。"]},{"t":"追悼杜柽居","f":"七言律诗","c":["柽翁书断几经年，忍见哀音到耳边。","梦里关山犹阻在，画中人物竟萧然。","游追司马才千里，隐比东方但一廛。","独爱高谈惊鬼胆，江湖风雨不堪传。"]},{"t":"侍御东君来言大司马洪洞韩公问讯志感二首 其一","f":"七言律诗","c":["柱史传来洪洞语，病夫心事有公知。","东曹疏笔还谁执，西野吟筇也自支。","千里寒暄音似玉，百年忧乐鬓如丝。","风吹凉雨清茶罢，正是怀人欲渴时。"]},{"t":"侍御东君来言大司马洪洞韩公问讯志感二首 其二","f":"七言律诗","c":["太行云远独怀人，近古风流大耋身。","一代典刑千百世，两朝平格二三臣。","梦回曹省灯无影，诗到山林笔有神。","更喜清廉卫参政，白头情话正相邻。"]},{"t":"闻申诏侍养喜而有述","f":"七言律诗","c":["一封书奏再踰年，温诏春来忽自天。","此日益知亲寿远，何人敢望圣恩偏。","新衔承乏催无驾，旧禄留馀养有田。","最是衰迟惭报称，山中常检白云篇。"]},{"t":"九月一日点易台新成登而观之又得一石如台漫赋","f":"七言律诗","c":["台成点易试高秋，更爱真台在上头。","石小似看千仞立，云多还许一方留。","飘然野步长随鹤，何处机心不见鸥。","分付山僧种松树，曲肱閒送翠阴流。"]},{"t":"九日与畅大夫以下八君子登台述事","f":"七言律诗","c":["上尽高台复有台，海天睛眼逐云回。","径当转处还逢石，坐得便时本藉苔。","风雨重阳初掩霭，乾坤吾道政徘徊。","县公自送江州酒，更许山僧供茗来。"]},{"t":"十月望日冯按察邀予登璨山高处观庐仙丹井至于新筑中台上台述兴二首 其一","f":"七言律诗","c":["行过青山复璨山，几层云磴几松关。","中岩泉落龙犹卧，上界坛高鹤未还。","十月风清双篴远，五湖波阔一舟閒。","凭君着我题名处，应在丹崖万仞间。"]},{"t":"十月望日冯按察邀予登璨山高处观庐仙丹井至于新筑中台上台述兴二首 其二","f":"七言律诗","c":["几年高兴拟登台，此日肩舆偶上来。","画里水曾誇震泽，望中山欲问蓬莱。","风神似与仙灵遇，踪迹从教野老猜。","日暮不须催返棹，东方明月正徘徊。"]},{"t":"赵秘阁训夫哀挽册","f":"七言律诗","c":["别君远在廿年前，偶读哀词一泫然。","越客调经涯老赏，晋人书自洑翁传。","天连阁道长当御，地近瀛洲太逼仙。","曾向缙云询白叟，潮江烟雨隔青田。"]},{"t":"咏雪灯答勋侄","f":"七言律诗","c":["雪制方灯昔未闻，阿咸才思夙超群。","一中造化离为火，四外经纶坎作云。","石室春光从地起，冰壶月色自天分。","閒来静坐能生白，更爱骊珠夜到门。"]},{"t":"司徒凤山公见过","f":"七言律诗","c":["江汉功成召命新，南来泉上问山人。","时哉春暮还灵雨，久矣吾衰更老亲。","万里长安天在望，千秋淮海水如神。","相过莫怪频留坐，话到平生字字真。"]},{"t":"送秦古峰别驾用前韵","f":"七言律诗","c":["孔嘉驿前江草新，送行偏感旧游人。","骥才此地方堪展，凤德何民不可亲。","春雨桑麻无旷野，秋风黍稷有明神。","烦君为吊康斋墓，十字题碑愧未真。"]},{"t":"次幸庵彭司马寄吴宪长","f":"七言律诗","c":["司马登廷昼接三，閒情及我我何堪。","梅花陇外嫌疏阔，萱草堂前愧旨甘。","望日直从双阙下，观风曾到两峰南。","他年出将成功地，时雨亭高酒半酣。"]},{"t":"次顾少参山行韵二首 其一","f":"七言律诗","c":["明月青天两度秋，太虚如水屋如舟。","一年节物还黄雀，十里溪光共白鸥。","自信菊华堪托醉，谁知萱草未忘忧。","山林况有平生癖，莫怪封章恳乞休。"]},{"t":"次顾少参山行韵二首 其二","f":"七言律诗","c":["步尽僧廊转曲阿，肩舆长记驻松坡。","愁看白发千茎长，病谢青山数月过。","地僻自应尘事少，夜长偏怪雨声多。","床头易在吾衰久，敢向苏门拟旧窝。"]},{"t":"二十日与诸生私祀忠定祠退馂松风阁","f":"七言律诗","c":["山中景物雨中楼，争道风雩是此游。","竹径有香深处净，松坛无影上方幽。","茗留宿润春初撷，苓待新晴夜欲收。","何处美人同我兴，便题书劄向渠投。"]},{"t":"雨中归自惠山得见素和我点易台诗用前韵","f":"七言律诗","c":["风雨西庵正倚楼，素翁书至似同游。","十年海上人非远，何处山中事不幽。","竹蘖乍肥分仆送，松花将老托僧收。","易台八首从头读，始信平生分已投。"]},{"t":"寄浦进士文玉用其韵","f":"七言律诗","c":["长安为客一年多，喜听明良和舜歌。","风海稍纡仙足骥，云山微露佛头螺。","两都赋在名为累，三策文成病作魔。","独有知音隔江左，蓉湖秋晚水增波。"]}]};